const a={id:"s02",unidad:1,semana:2,kind:"aprendizaje",temaGenerador:"Un mercado saludable y respetuoso",title:"Un mercado saludable y respetuoso",subtitle:"Investigamos alimentos seguros, intercambios respetuosos, recursos locales y formas útiles de comunicar",icon:"Store",color:"var(--area-cnt)",contexto:"Un mercado sirve a la comunidad cuando ofrece alimentos manipulados con higiene, aprovecha con cuidado los recursos locales y trata a cada persona con respeto. Esta semana investigarás cómo reducir el riesgo de parásitos sin hacer promesas exageradas de salud, cómo comunicar una oferta con claridad en español y en inglés y cómo convertir una necesidad, un recurso y un saber familiar en una idea posible. Las demás materias aportarán sus propios conceptos para comprender las formas, los seres vivos, la población, el patrimonio, la música, los derechos y el movimiento que también forman parte de la vida comunitaria.",ejes:["multiculturalidad","vida-familiar","trabajo","equidad"],media:{id:"s02-portada",kind:"video",title:"Un día de mercado",aspect:"16:9",duration:60,alt:"Recorrido por un mercado guatemalteco al amanecer: puestos de verduras, tejidos de colores, vendedoras que saludan y niños que ayudan a sus familias.",brief:'Video de 60 s (o animación 2D ilustrada) de un mercado de pueblo del altiplano al amanecer. Tomas: toldos que se abren, canastos con aguacates y güisquiles, güipiles con rombos colgados, una vendedora que saluda "Buenos días, doña", un puesto de agua pura, un celular usado para cobrar. Sobreimpresos: "Salud", "Figuras", "Personas", "Ideas". Marimba suave de fondo. Cierre con la pregunta "¿Qué descubres en el mercado de tu pueblo?". Sin marcas comerciales ni rostros identificables en primer plano. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste.'},badge:{id:"medalla-s02",name:"Guía del mercado",icon:"Store",desc:"Completaste la semana 2 y superaste su reto"},bank:[{fase:"comprobar",areas:["mat"],cnb:["mat:1.1.9"],prompt:"Para dibujar un rótulo circular, abres el compás a **6 cm**. ¿Cuánto medirá el diámetro del círculo?",type:"number-input",props:{answer:12,unit:"cm",misconceptions:[{value:6,msg:"6 cm es el radio. El diámetro mide dos radios."}]},id:"s02-banco-1"},{fase:"comprobar",areas:["mat"],cnb:["mat:1.1.7"],prompt:"Un marco cerrado tiene **diez lados** y diez vértices. ¿Cómo se llama ese polígono?",type:"choice",props:{options:[{id:"a",text:"Decágono"},{id:"b",text:"Eneágono"},{id:"c",text:"Hexágono"}],correct:["a"]},id:"s02-banco-2"},{fase:"comprobar",areas:["mat"],cnb:["mat:1.1.8"],prompt:"Un marco cuadrilateral irregular tiene tres ángulos de **83°, 96° y 112°**. ¿Cuánto mide el cuarto ángulo?",type:"number-input",props:{answer:69,unit:"°"},id:"s02-banco-3"},{fase:"comprobar",areas:["l1"],cnb:["l1:4.2.1"],prompt:'"Don Luis compra 4 libras de tomate a Q5 la libra y paga con un billete de Q50. Su hija tiene 11 años. ¿Cuánto le dan de vuelto?" ¿Qué dato **sobra**?',type:"choice",props:{options:[{id:"a",text:"La edad de la hija"},{id:"b",text:"El precio de la libra"},{id:"c",text:"El billete de Q50"}],correct:["a"]},id:"s02-banco-4"},{fase:"comprobar",areas:["l1"],cnb:["l1:4.2.2"],prompt:'Quieres buscar la palabra **"corrieron"** en el diccionario. ¿Qué forma buscas?',type:"choice",props:{options:[{id:"a",text:"correr"},{id:"b",text:"corrieron"},{id:"c",text:"corrida"}],correct:["a"]},id:"s02-banco-5"},{fase:"comprobar",areas:["cnt"],cnb:["cnt:1.5.2"],prompt:"¿Qué daño puede causar un parásito intestinal sin que el síntoma por sí solo confirme un diagnóstico?",type:"choice",props:{options:[{id:"a",text:"Consumir nutrientes o irritar el intestino"},{id:"b",text:"Crear cloroplastos en la sangre"},{id:"c",text:"Convertir una célula en piedra"}],correct:["a"]},id:"s02-banco-6"},{fase:"comprobar",areas:["cnt"],cnb:["cnt:2.1.1"],prompt:"¿Qué ser vivo es **unicelular**?",type:"choice",props:{options:[{id:"a",text:"El paramecio"},{id:"b",text:"La lombriz de tierra"},{id:"c",text:"El perro"}],correct:["a"]},id:"s02-banco-7"},{fase:"comprobar",areas:["ccss"],cnb:["ccss:3.1.1"],prompt:"¿Qué continente tiene **más de la mitad** de la población del mundo?",type:"choice",props:{options:[{id:"a",text:"Asia"},{id:"b",text:"Europa"},{id:"c",text:"Oceanía"}],correct:["a"]},id:"s02-banco-8"},{fase:"comprobar",areas:["ccss"],cnb:["ccss:3.2.5"],prompt:"Un archivo presta a la escuela una reproducción autorizada de un antiguo registro de mercado. ¿Qué plan contribuye a conservarlo durante la exposición?",type:"choice",props:{options:[{id:"a",text:"Anotar su procedencia, colocarlo en un soporte que no lo dañe y devolverlo en la fecha acordada"},{id:"b",text:"Recortar una parte para repartir recuerdos entre visitantes"},{id:"c",text:"Quitar la información de origen y presentarlo como propiedad de la escuela"}],correct:["a"]},id:"s02-banco-9"},{fase:"comprobar",areas:["l2"],cnb:["l2:2.1.1"],prompt:"¿Cuál paso pertenece a un instructivo claro para ordenar una mesa de venta?",type:"choice",props:{options:[{id:"a",text:"Finalmente, guarda los utensilios limpios en un recipiente tapado."},{id:"b",text:"La mesa quedó muy bonita y alegre."},{id:"c",text:"Tal vez alguien ordene todo algún día."}],correct:["a"]},id:"s02-banco-10"},{fase:"comprobar",areas:["l3"],cnb:["l3:1.1.2"],prompt:"Complete the service exchange. El mango cuesta Q12.",type:"fill-blank",props:{text:`SELLER: Can I [[help]] you?
CUSTOMER: How much is the mango?
SELLER: It is [[twelve]] quetzales.
CUSTOMER: Thank you!
SELLER: You are [[welcome]].`,distractors:["many","twenty","please"]},id:"s02-banco-11"},{fase:"comprobar",areas:["art"],cnb:["art:1.1.2"],prompt:"Un compás de **2/4** ya tiene una negra. ¿Qué figura falta para completarlo?",type:"choice",props:{options:[{id:"a",text:"Una negra"},{id:"b",text:"Una blanca"},{id:"c",text:"Una redonda"}],correct:["a"]},id:"s02-banco-12"},{fase:"comprobar",areas:["ef"],cnb:["ef:1.3.5"],prompt:"En una secuencia, Rosa corre, gira y lanza una pelota. ¿Cuántas habilidades simples combina?",type:"number-input",props:{answer:3,unit:"habilidades"},id:"s02-banco-13"},{fase:"comprobar",areas:["fc"],cnb:["fc:1.2.2"],prompt:"Una comunidad ya tiene escuela, pero muchas familias aún no cuentan con agua apta para consumo. ¿Qué conclusión se apoya en esos datos?",type:"choice",props:{options:[{id:"a",text:"Hay un avance, pero todavía no se cumplen plenamente todos los derechos"},{id:"b",text:"Todos los derechos ya están garantizados porque existe una escuela"},{id:"c",text:"Ningún derecho se cumple en la comunidad"}],correct:["a"]},id:"s02-banco-14"},{fase:"comprobar",areas:["pyd"],cnb:["pyd:1.3.2"],prompt:"Clasifica acciones para organizar con participación un centro de información comunitaria.",type:"sort",props:{buckets:[{id:"p",label:"Promueve participación",icon:"Users"},{id:"n",label:"No la promueve",icon:"UserX"}],items:[{id:"i1",text:"Explicar para qué se solicitan los aportes",bucket:"p"},{id:"i2",text:"Asignar roles de recepción y clasificación",bucket:"p"},{id:"i3",text:"Ocultar cómo se usarán las fichas",bucket:"n"},{id:"i4",text:"Devolver una síntesis con datos pendientes",bucket:"p"}]},id:"s02-banco-15"}]},e=JSON.parse(`[{"missionId":"s02","version":"cnb-sexto-494cac627076745c","lesson":{"id":"s02-mat-1","title":"Polígonos: nombres hasta 10 lados","icon":"Hexagon","minutes":13,"gancho":"La señal de ALTO, una celda de panal y una pizarra son figuras con lados rectos. ¿Sabes cómo se llama cada una?","objetivos":["Reconocer qué es un polígono y cuáles figuras no lo son","Nombrar y describir polígonos de 3 a 10 lados"],"resumen":["Un polígono es una figura plana y cerrada formada por segmentos rectos que no se cruzan.","Sus partes son: lados, vértices, ángulos interiores y diagonales. Un polígono tiene tantos lados como vértices y ángulos.","Nombres: triángulo (3), cuadrilátero (4), pentágono (5), hexágono (6), heptágono (7), octágono (8), eneágono (9) y decágono (10).","El círculo no es polígono porque su borde es curvo."],"media":{"id":"s02-mat-1-nombres","kind":"image","title":"Polígonos en el camino al mercado","aspect":"16:9","alt":"Calle de un pueblo con una señal de alto octagonal, un panal hexagonal en un árbol, una ventana rectangular y un kiosco de techo octagonal; cada figura con su nombre.","brief":"Ilustración de una calle de pueblo guatemalteco camino al mercado. Resaltar con contorno de color: señal de ALTO (octágono), panal de abejas en un árbol (hexágonos), ventana (cuadrilátero), banderín triangular, kiosco del parque con un recuadro que muestra su techo visto desde arriba (octágono), y una baldosa de 5 lados en la banqueta. Cada figura con una etiqueta pequeña: nombre y número de lados. Estilo plano, colores vivos, sin marcas ni texto adicional. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:1.1.7"],"ambito":"conocer","title":"¿Qué es un polígono?","prompt":"Un **polígono** es una figura **plana** y **cerrada** formada por **segmentos rectos** que no se cruzan. Toca cada tarjeta para conocer sus partes.","media":{"id":"s02-mat-1-partes","kind":"diagram","title":"Partes de un polígono","aspect":"4:3","alt":"Un pentágono con sus partes rotuladas: un lado, un vértice, un ángulo interior y una diagonal punteada.","brief":"Diagrama de un pentágono irregular grande en el centro. Flechas y rótulos: \\"lado\\" (un segmento en azul), \\"vértice\\" (punto rojo en una esquina), \\"ángulo interior\\" (arco amarillo dentro de una esquina) y \\"diagonal\\" (línea punteada que une dos vértices no vecinos). Debajo, tres contraejemplos pequeños tachados suavemente: un círculo (\\"borde curvo\\"), una figura abierta (\\"no cerrada\\") y una figura en forma de moño con lados que se cruzan (\\"lados cruzados\\"). Fondo blanco. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"explain","props":{"icon":"Hexagon","body":"Un polígono tiene **tantos lados como vértices y ángulos**.","reveal":[{"icon":"Minus","front":"Lado","back":"Cada segmento recto del borde."},{"icon":"CircleDot","front":"Vértice","back":"El punto donde se juntan dos lados."},{"icon":"Slash","front":"Diagonal","back":"Segmento que une dos vértices que **no** son vecinos."},{"icon":"X","front":"No son polígonos","back":"El círculo (borde curvo), una figura abierta y una figura cuyos lados se cruzan."}]},"id":"s02-mat-1-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.7"],"ambito":"conocer","prompt":"Tres figuras del camino al mercado. ¿Cuál **no** está formada solo por lados rectos?","explain":"La tortilla es redonda: su borde es **curvo**. Las figuras hechas solo de lados rectos y cerradas se llaman **polígonos**.","type":"choice","props":{"layout":"grid","options":[{"id":"a","text":"La señal de ALTO","icon":"Octagon","feedback":"La señal de ALTO tiene 8 lados rectos."},{"id":"b","text":"Una tortilla","icon":"Pizza"},{"id":"c","text":"Una ventana","icon":"AppWindow","feedback":"La ventana tiene 4 lados rectos."}],"correct":["b"]},"id":"s02-mat-1-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.7"],"prompt":"¿Es polígono o no?","hint":"Revisa tres cosas: ¿es cerrada?, ¿todos sus lados son rectos?, ¿sus lados no se cruzan?","explain":"Basta con que falle una de las tres condiciones para que no sea polígono.","type":"sort","props":{"buckets":[{"id":"si","label":"Polígono","icon":"Check","color":"var(--c-ok)"},{"id":"no","label":"No es polígono","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"a","text":"Un triángulo","bucket":"si"},{"id":"b","text":"La boca de un cántaro (círculo)","bucket":"no","feedback":"Su borde es curvo."},{"id":"c","text":"Una letra V (dos segmentos abiertos)","bucket":"no","feedback":"No es cerrada."},{"id":"d","text":"Una celda de panal (6 lados)","bucket":"si"},{"id":"e","text":"Un cuadrilátero con 4 lados rectos","bucket":"si"},{"id":"f","text":"Una figura en forma de moño: dos triángulos unidos por la punta, con lados que se cruzan","bucket":"no","feedback":"Sus lados se cruzan."}]},"id":"s02-mat-1-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.7"],"ambito":"conocer","title":"El nombre dice cuántos lados","prompt":"El nombre de cada polígono viene del griego y **cuenta sus lados**. Toca cada tarjeta.","type":"explain","props":{"icon":"ListOrdered","body":"Truco: la primera parte del nombre es el número. **Penta** = 5, **hexa** = 6, **hepta** = 7, **octa** = 8, **enea** = 9, **deca** = 10.","reveal":[{"icon":"Triangle","front":"3 y 4 lados","back":"**Triángulo** (3) y **cuadrilátero** (4)."},{"icon":"Pentagon","front":"5 y 6 lados","back":"**Pentágono** (5) y **hexágono** (6), como las celdas de un panal."},{"icon":"Octagon","front":"7 y 8 lados","back":"**Heptágono** (7) y **octágono** (8), como la señal de ALTO."},{"icon":"Star","front":"9 y 10 lados","back":"**Eneágono** (9), también llamado nonágono, y **decágono** (10)."}]},"id":"s02-mat-1-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.7"],"prompt":"Une cada polígono con su número de lados.","hint":"Usa el truco: penta 5, hexa 6, hepta 7, octa 8, enea 9, deca 10.","explain":"El prefijo del nombre te dice el número de lados.","type":"match","props":{"leftTitle":"Polígono","rightTitle":"Lados","pairs":[{"id":"p1","left":"Pentágono","right":"5 lados"},{"id":"p2","left":"Heptágono","right":"7 lados"},{"id":"p3","left":"Octágono","right":"8 lados"},{"id":"p4","left":"Eneágono","right":"9 lados"},{"id":"p5","left":"Decágono","right":"10 lados"}]},"id":"s02-mat-1-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.7"],"ambito":"hacer","title":"Describir un polígono","prompt":"Describir un polígono es decir su nombre y contar sus partes. Observa.","type":"worked-example","props":{"icon":"Octagon","problem":"Describe la señal de **ALTO**.","steps":[{"text":"Cuento los lados: **8**. Entonces es un **octágono**."},{"text":"Tiene tantos vértices y ángulos como lados: **8 vértices** y **8 ángulos**.","why":"Cada vértice une dos lados y forma un ángulo."},{"text":"Es plana, cerrada y de lados rectos que no se cruzan: sí es polígono."}],"answer":"La señal de ALTO es un **octágono**: 8 lados, 8 vértices y 8 ángulos.","tip":"Lados = vértices = ángulos, en cualquier polígono."},"id":"s02-mat-1-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.7"],"prompt":"Para una fiesta, arman una mesa en forma de **heptágono**. En cada **lado** se sienta una persona y en cada **vértice** ponen un florero. ¿Cuántas personas y floreros hay **en total**?","explain":"Un heptágono tiene 7 lados y 7 vértices: 7 personas + 7 floreros = 14.","type":"number-input","props":{"answer":14,"misconceptions":[{"value":7,"msg":"Contaste solo personas o solo floreros. Súmalos."},{"value":16,"msg":"Revisa: hepta = 7, no 8."}]},"id":"s02-mat-1-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.7"],"prompt":"Completa la descripción.","explain":"Hexágono = 6 lados; eneágono = 9 lados; decágono = 10 lados.","type":"fill-blank","props":{"text":"Una celda de panal es un [[hexágono]]: tiene [[6]] lados y 6 vértices. Un polígono de 9 lados se llama [[eneágono]] y uno de 10 lados, [[decágono]].","distractors":["octágono","8","heptágono"]},"id":"s02-mat-1-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.7"],"prompt":"Una figura cerrada tiene **8 vértices** y lados rectos. ¿Cómo se llama?","explain":"Vértices = lados. Con 8 lados es un **octágono**.","type":"choice","props":{"options":[{"id":"a","text":"Hexágono","feedback":"El hexágono tiene 6 vértices."},{"id":"b","text":"Octágono"},{"id":"c","text":"Decágono","feedback":"El decágono tiene 10."}],"correct":["b"]},"id":"s02-mat-1-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.7"],"prompt":"¿Cuántos **lados** tiene un **eneágono**?","type":"number-input","props":{"answer":9},"id":"s02-mat-1-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.7"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Un círculo es un polígono.","answer":false,"why":"Su borde es curvo."},{"text":"Un pentágono tiene 5 vértices.","answer":true},{"text":"Un heptágono tiene 8 lados.","answer":false,"why":"Tiene 7."},{"text":"Una diagonal une dos vértices que no son vecinos.","answer":true}]},"id":"s02-mat-1-11"}],"kind":"materia","area":"mat","day":1}},{"missionId":"s02","version":"cnb-sexto-9eb7e65a4a3fdb7a","lesson":{"id":"s02-mat-2","title":"Polígonos regulares e irregulares","icon":"Shapes","minutes":13,"gancho":"Las celdas de un panal son todas iguales por dentro y por fuera. ¿Qué las hace tan especiales?","objetivos":["Distinguir un polígono regular de uno irregular","Explicar por qué el rombo y el rectángulo no son regulares"],"resumen":["Un polígono es regular si tiene TODOS sus lados iguales y TODOS sus ángulos iguales.","Si falla una de las dos condiciones, es irregular.","El rombo tiene lados iguales pero ángulos distintos; el rectángulo tiene ángulos iguales pero lados distintos: ambos son irregulares.","Ejemplos de regulares: triángulo equilátero, cuadrado, pentágono y hexágono regulares, la señal de ALTO."],"media":{"id":"s02-mat-2-panal","kind":"image","title":"El panal: hexágonos regulares","aspect":"4:3","alt":"Acercamiento a un panal de abejas: celdas de seis lados iguales, una de ellas resaltada con sus seis lados y sus seis ángulos de 120° marcados.","brief":"Ilustración realista-suave de un panal de abejas de un apiario comunitario (sin marcas). Una celda resaltada en color con cada lado marcado con una rayita igual y cada ángulo con un arco y la etiqueta \\"120°\\". A la par, en recuadro, un hexágono irregular (lados distintos) para comparar, con la etiqueta \\"irregular\\". Fondo cálido, abejas pequeñas amigables. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:1.1.6"],"ambito":"conocer","title":"Regular = dos condiciones","prompt":"Un polígono es **regular** si cumple **dos** condiciones a la vez. Si falla una, es **irregular**. Toca cada tarjeta.","type":"explain","props":{"icon":"ListChecks","body":"**Regular** = todos los lados iguales **y** todos los ángulos iguales.","reveal":[{"icon":"Ruler","front":"Condición 1: lados","back":"Todos sus lados miden lo mismo."},{"icon":"Triangle","front":"Condición 2: ángulos","back":"Todos sus ángulos miden lo mismo."},{"icon":"Check","front":"Ejemplos regulares","back":"Triángulo equilátero (lados iguales y ángulos de 60°), cuadrado, celda de panal, señal de ALTO."},{"icon":"Shapes","front":"Irregular no es \\"feo\\"","back":"Solo significa que sus lados o sus ángulos no son todos iguales. Un terreno, una casa o una hoja de árbol suelen ser irregulares."}]},"id":"s02-mat-2-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.6"],"ambito":"conocer","prompt":"¿Qué tienen de especial las celdas de un panal de abejas?","explain":"Cada celda es un hexágono con **seis lados iguales** y **seis ángulos iguales**. A esos polígonos se les llama **regulares**.","type":"choice","props":{"options":[{"id":"a","text":"Todos sus lados y todos sus ángulos son iguales","icon":"Hexagon"},{"id":"b","text":"Son redondas","icon":"Circle","feedback":"Mira bien: tienen seis lados rectos."},{"id":"c","text":"Cada una tiene lados de distinto tamaño","icon":"Shapes","feedback":"Si así fuera, no encajarían tan bien unas con otras."}],"correct":["a"]},"id":"s02-mat-2-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.6"],"ambito":"hacer","title":"Ejemplo resuelto: la casita","prompt":"A veces una figura parece regular, pero no lo es. Revisa las dos condiciones.","type":"worked-example","props":{"icon":"Home","problem":"La fachada de una casita es un pentágono con sus **5 lados de 3 m** (una pared cuadrada con un techo en punta). Sus ángulos miden **90°, 90°, 150°, 60° y 150°**. ¿Es regular?","steps":[{"text":"Condición 1, lados: los 5 miden 3 m. **Se cumple.**"},{"text":"Condición 2, ángulos: hay de 90°, de 150° y de 60°. **No se cumple.**","why":"Para ser regular, los 5 ángulos deberían ser iguales (108° cada uno)."},{"text":"Como falla una condición, es **irregular**."}],"answer":"La fachada es un pentágono **irregular**, aunque sus lados sean iguales.","tip":"Revisa siempre las dos condiciones: lados y ángulos."},"id":"s02-mat-2-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.6"],"prompt":"¿Regular o irregular?","hint":"Pregunta 1: ¿todos los lados iguales? Pregunta 2: ¿todos los ángulos iguales? Deben cumplirse las dos.","explain":"Solo son regulares los que tienen lados iguales **y** ángulos iguales.","type":"sort","props":{"buckets":[{"id":"re","label":"Regular","icon":"Hexagon","color":"var(--c-ok)"},{"id":"ir","label":"Irregular","icon":"Shapes","color":"var(--c-maiz-strong)"}],"items":[{"id":"a","text":"Cuadrado de 5 cm","bucket":"re"},{"id":"b","text":"Rectángulo de 8 × 3 cm","bucket":"ir","feedback":"Sus ángulos son iguales, pero sus lados no."},{"id":"c","text":"Triángulo con ángulos de 60°, 60° y 60°","bucket":"re"},{"id":"d","text":"Rombo con ángulos de 70° y 110°","bucket":"ir","feedback":"Sus lados son iguales, pero sus ángulos no."},{"id":"e","text":"Terreno de 5 lados: 12, 9, 15, 10 y 8 m","bucket":"ir"},{"id":"f","text":"Octágono de la señal de ALTO","bucket":"re"}]},"id":"s02-mat-2-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.6"],"ambito":"conocer","title":"Dos trampas frecuentes","prompt":"Estas dos figuras engañan a mucha gente. Toca cada una.","type":"explain","props":{"icon":"AlertTriangle","body":"Cumplir **una sola** condición no alcanza.","reveal":[{"icon":"Diamond","front":"El rombo","back":"Lados iguales ✔, ángulos iguales ✘ (dos agudos y dos obtusos). **Irregular.**"},{"icon":"RectangleHorizontal","front":"El rectángulo","back":"Ángulos iguales ✔ (4 rectos), lados iguales ✘. **Irregular.**"},{"icon":"Square","front":"El cuadrado","back":"Lados iguales ✔ y ángulos iguales ✔. Es el **cuadrilátero regular**."}]},"id":"s02-mat-2-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.6"],"prompt":"¿Verdadero o falso?","hint":"Recuerda las dos trampas: el rombo y el rectángulo.","explain":"Un polígono regular necesita las dos condiciones a la vez.","type":"true-false","props":{"statements":[{"text":"Un rectángulo es un polígono regular porque todos sus ángulos miden 90°.","answer":false,"why":"Le falta la condición de los lados iguales."},{"text":"El cuadrado es un polígono regular.","answer":true},{"text":"Si un polígono tiene todos sus lados iguales, siempre es regular.","answer":false,"why":"Mira el rombo: lados iguales, ángulos distintos."}]},"id":"s02-mat-2-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.6"],"prompt":"En el mercado ves estos objetos. ¿Cuáles tienen forma de **polígono regular**? (Elige todos los correctos.)","explain":"La canasta hexagonal de lados y ángulos iguales y la baldosa cuadrada son regulares. El mantel rectangular y el terreno de lados distintos no.","type":"choice","props":{"multiple":true,"options":[{"id":"a","text":"Tapadera de canasta: hexágono de lados y ángulos iguales","icon":"ShoppingBasket"},{"id":"b","text":"Mantel de 2 m × 1 m","icon":"RectangleHorizontal","feedback":"Sus lados no son todos iguales."},{"id":"c","text":"Baldosa cuadrada de 30 cm","icon":"Square"},{"id":"d","text":"Parqueo en forma de trapecio","icon":"Car","feedback":"Un trapecio no tiene todos sus lados iguales."}],"correct":["a","c"]},"id":"s02-mat-2-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.6"],"prompt":"Un pentágono **regular** tiene un lado de **7 cm**. ¿Cuántos centímetros mide cada uno de sus otros lados?","explain":"En un polígono regular todos los lados miden lo mismo: 7 cm.","type":"number-input","props":{"answer":7,"unit":"cm","misconceptions":[{"value":35,"msg":"35 sería la suma de los 5 lados. La pregunta es cuánto mide cada lado."}]},"id":"s02-mat-2-8"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.6"],"prompt":"Un rombo tiene lados de 6 cm y ángulos de **50° y 130°**. ¿Por qué **no** es regular?","type":"choice","props":{"options":[{"id":"a","text":"Porque sus lados no son iguales"},{"id":"b","text":"Porque sus ángulos no son todos iguales"},{"id":"c","text":"Porque tiene 4 lados"}],"correct":["b"]},"id":"s02-mat-2-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.6"],"prompt":"Clasifica.","type":"sort","props":{"buckets":[{"id":"re","label":"Regular","icon":"Hexagon"},{"id":"ir","label":"Irregular","icon":"Shapes"}],"items":[{"id":"a","text":"Hexágono con 6 lados de 4 cm y 6 ángulos de 120°","bucket":"re"},{"id":"b","text":"Triángulo con lados de 3, 4 y 5 cm","bucket":"ir"},{"id":"c","text":"Romboide de 9 × 4 cm","bucket":"ir"},{"id":"d","text":"Triángulo equilátero","bucket":"re"}]},"id":"s02-mat-2-10"}],"kind":"materia","area":"mat","day":2}},{"missionId":"s02","version":"cnb-sexto-3969ce430b672f37","lesson":{"id":"s02-cnt-1","title":"Tipos de parásitos","icon":"Bug","minutes":14,"gancho":"Un piojo vive sobre el cuero cabelludo y una lombriz intestinal vive dentro del cuerpo. ¿Cómo se clasifican?","objetivos":["Diferenciar ectoparásitos y endoparásitos mediante su ubicación en el huésped"],"resumen":["Un parásito obtiene recursos de un huésped y puede dañarlo.","Los ectoparásitos viven sobre la superficie; los endoparásitos viven dentro.","No todo organismo pequeño es parásito y la clasificación no sustituye un diagnóstico."],"media":{"id":"s02-cnt-1-tipos-parasitos","kind":"diagram","title":"Parásitos por ubicación","aspect":"16:9","alt":"Silueta humana con un piojo señalado sobre el cabello y una lombriz intestinal señalada dentro del intestino.","brief":"Diagrama horizontal 1600×900. Silueta humana no explícita dividida en SUPERFICIE e INTERIOR. Mostrar piojo y garrapata fuera; lombriz intestinal y protozoo parásito genérico dentro. Rótulos grandes, contraste alto, escala no real y nota: ejemplos didácticos, no diagnóstico."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:1.5.1"],"title":"Huésped y parásito","prompt":"Un parásito vive en o sobre otro organismo, llamado huésped, y obtiene de él alimento o refugio.","type":"explain","props":{"icon":"Microscope","body":"La relación puede causar daño al huésped. La ubicación permite distinguir dos tipos principales."},"id":"s02-cnt-1-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.5.1"],"title":"Dos tipos","prompt":"Clasifica por el lugar donde vive el parásito.","type":"explain","props":{"icon":"ScanSearch","body":"**Ectoparásito:** sobre piel o cabello, como piojos y algunas garrapatas. **Endoparásito:** dentro del organismo, como lombrices intestinales y ciertos protozoos parásitos. Muchos protozoos no son parásitos."},"id":"s02-cnt-1-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.5.1"],"title":"Modelo de clasificación","prompt":"Usa ubicación y no tamaño o apariencia.","type":"worked-example","props":{"icon":"ListChecks","problem":"Un piojo está sobre el cabello; una lombriz vive en el intestino.","steps":[{"text":"Identifico el huésped."},{"text":"Ubico al organismo: superficie o interior."},{"text":"Superficie corresponde a ectoparásito; interior, a endoparásito."}],"answer":"Piojo: ectoparásito. Lombriz intestinal: endoparásito."},"id":"s02-cnt-1-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.5.1"],"prompt":"Clasifica los ejemplos por su ubicación en el huésped.","hint":"Ecto = afuera; endo = adentro.","explain":"La ubicación define la clasificación.","type":"sort","props":{"buckets":[{"id":"ecto","label":"Ectoparásito"},{"id":"endo","label":"Endoparásito"},{"id":"no","label":"No se describe como parásito"}],"items":[{"id":"a","text":"Piojo sobre el cabello","bucket":"ecto"},{"id":"b","text":"Lombriz en el intestino","bucket":"endo"},{"id":"c","text":"Ameba libre en un estanque","bucket":"no"},{"id":"d","text":"Garrapata adherida a la piel","bucket":"ecto"}]},"id":"s02-cnt-1-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.5.1"],"prompt":"Relaciona cada pista con el tipo de parásito.","hint":"Busca superficie o interior.","explain":"La pista espacial basta para clasificar, no para diagnosticar.","type":"match","props":{"pairs":[{"id":"a","left":"Sobre la piel","right":"Ectoparásito"},{"id":"b","left":"Dentro del intestino","right":"Endoparásito"},{"id":"c","left":"En el cabello","right":"Ectoparásito"}]},"id":"s02-cnt-1-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.5.1"],"prompt":"En una ficha didáctica, un organismo vive dentro de la sangre de su huésped. ¿Cómo se clasifica por ubicación?","type":"choice","props":{"options":[{"id":"a","text":"Endoparásito"},{"id":"b","text":"Ectoparásito"},{"id":"c","text":"No puede clasificarse porque es pequeño"}],"correct":["a"]},"id":"s02-cnt-1-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.5.1"],"prompt":"Clasifica nuevos escenarios sin asumir que todo ser microscópico es parásito.","type":"sort","props":{"buckets":[{"id":"ecto","label":"Ectoparásito"},{"id":"endo","label":"Endoparásito"},{"id":"ins","label":"Información insuficiente"}],"items":[{"id":"a","text":"Ácaro descrito sobre la piel del huésped","bucket":"ecto"},{"id":"b","text":"Organismo dentro del hígado del huésped","bucket":"endo"},{"id":"c","text":"Microorganismo observado en agua, sin huésped descrito","bucket":"ins"}]},"id":"s02-cnt-1-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.5.1"],"prompt":"¿Qué ejemplo corresponde a un ectoparásito?","type":"choice","props":{"options":[{"id":"a","text":"Una garrapata adherida a la piel"},{"id":"b","text":"Una lombriz dentro del intestino"},{"id":"c","text":"Un alga en una laguna"}],"correct":["a"]},"id":"s02-cnt-1-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.5.1"],"prompt":"Comprueba la clasificación de los tipos de parásitos.","type":"true-false","props":{"statements":[{"text":"Un endoparásito vive dentro del huésped.","answer":true},{"text":"Todo protozoo es un parásito.","answer":false,"why":"Hay protozoos de vida libre y también especies parásitas."},{"text":"La ubicación en superficie distingue a un ectoparásito.","answer":true}]},"id":"s02-cnt-1-9"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["cnt"],"cnb":["cnt:1.5.1"],"type":"reflection","props":{"statements":["Diferencié ectoparásitos y endoparásitos por su ubicación"]},"id":"s02-cnt-1-10"}],"kind":"materia","area":"cnt","day":1}},{"missionId":"s02","version":"cnb-sexto-b0dc73ffe10f916f","lesson":{"id":"s02-ccss-1","title":"Los continentes vistos con indicadores","icon":"ChartNoAxesColumn","minutes":14,"gancho":"Un mercado puede necesitar juegos para la ninez o espacios de descanso. ¿Que datos ayudan a decidir sin convertir a millones de personas en un solo estereotipo?","objetivos":["Reflexionar con cautela sobre indicadores demograficos suministrados de los continentes del mundo"],"resumen":["Los indicadores demograficos describen aspectos de una poblacion, como su tamano relativo y su perfil de edades; ninguno explica por si solo toda la realidad.","Comparar continentes permite formular necesidades posibles, pero los datos redondeados y continentales no describen cada pais, comunidad o persona."],"media":{"id":"s02-ccss-1-indicadores","kind":"diagram","title":"Ficha demografica continental","aspect":"16:9","alt":"Tabla didactica fechada en 2024 que compara proporcion aproximada de poblacion mundial y perfil de edad de Africa, Asia, America, Europa y Oceania.","brief":"Diagrama 1600x900 de alto contraste. Tabla titulada \\"Ficha didactica: referencia 2024\\" con Africa, Asia, America, Europa y Oceania; mostrar proporciones redondeadas 19%, 59%, 13%, 9% y menos de 1%, y perfiles cualitativos joven, diverso, diverso, mas envejecido y diverso. Incluir en texto grande: \\"Cifras redondeadas para comparar; no describen cada pais ni sustituyen una fuente actual\\". Tipografia legible, sin banderas ni fotografias."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:3.1.1"],"title":"Una cifra abre preguntas","prompt":"Reflexiona sobre indicadores demograficos de Africa, Asia, America, Europa y Oceania. La ficha usa **datos didacticos redondeados con fecha de referencia 2024**: sirven para comparar, pero no representan cada pais ni toda la realidad.","type":"explain","props":{"icon":"ChartNoAxesColumn","body":"Un indicador resume una caracteristica de una poblacion. La **proporcion de poblacion mundial** compara tamanos; el **perfil de edad** ayuda a preguntar por escuelas, empleo, salud o cuidados. Una cifra no decide por si sola."},"id":"s02-ccss-1-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.1.1"],"title":"Paquete de datos suministrado","prompt":"Compara los cinco continentes y conserva los limites de la ficha antes de inferir necesidades.","type":"explain","props":{"icon":"TableProperties","body":"**Ficha didactica, referencia 2024, cifras redondeadas:** Asia: cerca de 59% de la poblacion mundial; Africa: 19%; America: 13%; Europa: 9%; Oceania: menos de 1%. En conjunto, Africa presenta un perfil mas joven y Europa uno mas envejecido; Asia, America y Oceania contienen perfiles muy diversos. Los redondeos no deben sumarse como medicion exacta y ningun promedio describe cada pais."},"id":"s02-ccss-1-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.1.1"],"title":"Modelo de reflexion cauta","prompt":"Observa como pasar de los indicadores de Africa, Asia, America, Europa y Oceania a una conclusion que reconoce limites.","type":"worked-example","props":{"icon":"SearchCheck","problem":"¿Que puede inferirse del perfil joven de Africa y del perfil mas envejecido de Europa?","steps":[{"text":"Describo la evidencia: la ficha didactica redondeada de 2024 muestra perfiles de edad diferentes."},{"text":"Formulo necesidades posibles: mas poblacion joven puede aumentar demanda de educacion y empleo; mas personas mayores puede aumentar demanda de salud y cuidados."},{"text":"Marco el limite: Asia, America, Europa, Africa y Oceania contienen paises diversos; el indicador continental no basta para decidir en una comunidad."}],"answer":"La reflexion compara indicadores, propone preguntas o necesidades y evita afirmar que todas las personas de un continente viven igual."},"id":"s02-ccss-1-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.1.1"],"prompt":"Guia: relaciona cada lectura de la ficha 2024 sobre Africa, Asia, America, Europa y Oceania con una reflexion demografica cauta.","hint":"Distingue dato, necesidad posible y limite.","explain":"Reflexionar no es repetir un porcentaje: es interpretar que podria significar y reconocer lo que no demuestra.","type":"match","props":{"pairs":[{"id":"a","left":"Asia concentra la mayor proporcion aproximada","right":"Puede implicar grandes necesidades totales, pero no dice como se distribuyen entre paises"},{"id":"b","left":"Africa tiene un perfil mas joven en conjunto","right":"Invita a preguntar por educacion y empleo, sin describir igual a cada pais"},{"id":"c","left":"Europa tiene un perfil mas envejecido en conjunto","right":"Invita a preguntar por salud y cuidados, sin borrar diferencias internas"},{"id":"d","left":"Oceania representa menos de 1% en la ficha","right":"Una proporcion pequena no vuelve menos importantes sus necesidades"}]},"id":"s02-ccss-1-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.1.1"],"prompt":"Con los datos didacticos redondeados de 2024, Africa tiene perfil mas joven, Europa mas envejecido y Asia, America y Oceania son internamente diversas. ¿Que reflexion usa bien los indicadores?","hint":"Busca una conclusion que proponga necesidades y reconozca limites.","explain":"Los indicadores orientan preguntas; no prueban que todos los paises o habitantes tengan la misma necesidad.","type":"choice","props":{"options":[{"id":"a","text":"Conviene explorar educacion, empleo y cuidados con datos de cada pais antes de decidir"},{"id":"b","text":"Toda Africa necesita exactamente lo mismo y toda Europa tambien"},{"id":"c","text":"La proporcion de poblacion demuestra la calidad de vida de cada habitante"}],"correct":["a"]},"id":"s02-ccss-1-5"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:3.1.1"],"prompt":"Aplicacion independiente. Los datos didacticos redondeados de 2024 comparan Africa, Asia, America, Europa y Oceania por proporcion de poblacion y perfil de edad. ¿Que conclusion reflexiva es valida para planear servicios?","explain":"Una decision responsable combina el indicador continental con informacion mas cercana y actual.","type":"choice","props":{"options":[{"id":"a","text":"Los perfiles sugieren necesidades posibles, pero hay que consultar datos actuales de cada pais y comunidad"},{"id":"b","text":"El continente con mas poblacion siempre necesita un unico tipo de servicio"},{"id":"c","text":"Los datos continentales permiten describir a cualquier familia sin preguntar nada mas"}],"correct":["a"]},"id":"s02-ccss-1-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:3.1.1"],"prompt":"Escribe una reflexion de dos oraciones sobre Africa, Asia, America, Europa y Oceania usando un indicador de la ficha didactica 2024: incluye una necesidad posible y un limite de los datos redondeados.","type":"short-answer","props":{"minWords":18,"placeholder":"El indicador sugiere... Sin embargo, no basta porque...","model":"El perfil de edad puede orientar preguntas sobre escuelas o cuidados. Sin embargo, el dato continental redondeado no describe cada pais ni reemplaza informacion local actual.","rubric":["Use un indicador suministrado","Propuse una necesidad o pregunta","Reconoci un limite del dato"]},"id":"s02-ccss-1-7"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:3.1.1"],"prompt":"Salida. En los datos didacticos redondeados de 2024 sobre proporcion de poblacion y edad, Africa tiene perfil mas joven, Europa mas envejecido y Asia, America y Oceania muestran diversidad interna. ¿Que reflexion sobre necesidades y decisiones respeta el limite del indicador?","type":"choice","props":{"options":[{"id":"a","text":"Puede orientar preguntas sobre educacion o cuidados, pero se necesitan datos actuales de cada pais"},{"id":"b","text":"Permite asignar la misma necesidad a todas las personas del continente"},{"id":"c","text":"Hace innecesario conocer informacion de las comunidades"}],"correct":["a"]},"id":"s02-ccss-1-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:3.1.1"],"prompt":"Salida nueva. Reflexiona sobre los datos didacticos redondeados de 2024 de Africa, Asia, America, Europa y Oceania: poblacion, perfil de edad, necesidades y limites.","type":"true-false","props":{"statements":[{"text":"Comparar perfiles de edad puede sugerir preguntas sobre servicios, sin demostrar que todos los paises sean iguales.","answer":true},{"text":"Una proporcion continental basta para decidir las necesidades de cada comunidad.","answer":false}]},"id":"s02-ccss-1-9"}],"kind":"materia","area":"ccss","day":1}},{"missionId":"s02","version":"cnb-sexto-9f1c7309b57e47d0","lesson":{"id":"s02-cnt-2","title":"Seres de una célula y de muchas","icon":"Microscope","minutes":14,"gancho":"Una ameba realiza todas sus funciones con una célula; una persona necesita billones. ¿Cómo se organizan?","objetivos":["Organizar seres vivos en unicelulares y pluricelulares según su número y organización de células"],"resumen":["Los unicelulares tienen una célula que realiza todas las funciones vitales.","Los pluricelulares tienen muchas células especializadas que forman tejidos, órganos y sistemas.","Protozoo describe un grupo diverso de unicelulares; metazoo se refiere a animales pluricelulares."],"media":{"id":"s02-cnt-2-organizacion","kind":"diagram","title":"Una célula o muchas","aspect":"16:9","alt":"Una ameba de una célula comparada con un pez formado por muchas células especializadas.","brief":"Diagrama horizontal 1600×900. Izquierda: ameba rotulada UNICELULAR con una sola membrana y núcleo. Derecha: pez rotulado PLURICELULAR con ampliaciones de células musculares y nerviosas. Flechas a célula, tejido y órgano. Texto grande, contraste alto y escala didáctica declarada."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:2.1.1"],"title":"Número y organización","prompt":"Los seres vivos pueden estar formados por una célula o por muchas células coordinadas.","type":"explain","props":{"icon":"Microscope","body":"**Unicelular:** una célula cumple nutrición, relación y reproducción. **Pluricelular:** muchas células se especializan y cooperan."},"id":"s02-cnt-2-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.1"],"title":"Protozoos y metazoos","prompt":"Los términos describen formas de organización.","type":"explain","props":{"icon":"Microscope","body":"Los **protozoos** son organismos unicelulares; muchos viven libremente y algunos son parásitos. Los **metazoos** son animales pluricelulares, desde una lombriz hasta un jaguar."},"id":"s02-cnt-2-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.1"],"title":"Modelo de decisión","prompt":"Clasifica usando evidencia celular.","type":"worked-example","props":{"icon":"GitCompare","problem":"Una ameba tiene una célula; un pez presenta tejidos y órganos.","steps":[{"text":"Ameba: una célula realiza todas las funciones."},{"text":"Pez: muchas células especializadas forman tejidos y órganos."}],"answer":"Ameba: unicelular/protozoo. Pez: pluricelular/metazoo."},"id":"s02-cnt-2-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.1"],"prompt":"Clasifica por organización celular.","hint":"Una célula frente a tejidos y órganos.","explain":"La clasificación depende del número y coordinación de células.","type":"sort","props":{"buckets":[{"id":"uni","label":"Unicelular"},{"id":"plu","label":"Pluricelular"}],"items":[{"id":"a","text":"Ameba","bucket":"uni"},{"id":"b","text":"Paramecio","bucket":"uni"},{"id":"c","text":"Hormiga","bucket":"plu"},{"id":"d","text":"Planta de maíz","bucket":"plu"}]},"id":"s02-cnt-2-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.1"],"prompt":"Ordena la organización de un ser pluricelular.","hint":"Las células semejantes forman tejidos.","explain":"Célula, tejido, órgano, sistema y organismo.","type":"order","props":{"items":[{"id":"a","text":"Célula"},{"id":"b","text":"Tejido"},{"id":"c","text":"Órgano"},{"id":"d","text":"Sistema"},{"id":"e","text":"Organismo"}]},"id":"s02-cnt-2-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.1.1"],"prompt":"Un ser microscópico tiene una sola célula que se mueve y obtiene alimento. ¿Qué evidencia permite clasificarlo?","type":"choice","props":{"options":[{"id":"a","text":"Es unicelular porque una célula realiza sus funciones"},{"id":"b","text":"Es pluricelular porque es pequeño"},{"id":"c","text":"Es metazoo porque se mueve"}],"correct":["a"]},"id":"s02-cnt-2-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.1.1"],"prompt":"Relaciona cada descripción nueva con su organización.","type":"match","props":{"pairs":[{"id":"a","left":"Levadura: una célula","right":"Unicelular"},{"id":"b","left":"Árbol: raíces, tallo y hojas con tejidos","right":"Pluricelular"},{"id":"c","left":"Protozoo: una célula funcional","right":"Unicelular"}]},"id":"s02-cnt-2-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:2.1.1"],"prompt":"¿Qué rasgo distingue a un ser pluricelular?","type":"choice","props":{"options":[{"id":"a","text":"Muchas células especializadas y coordinadas"},{"id":"b","text":"Una única célula que hace todo"},{"id":"c","text":"Ser necesariamente microscópico"}],"correct":["a"]},"id":"s02-cnt-2-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:2.1.1"],"prompt":"Comprueba la organización de seres vivos.","type":"true-false","props":{"statements":[{"text":"Un protozoo es unicelular.","answer":true},{"text":"Todo organismo microscópico causa enfermedad.","answer":false},{"text":"Los metazoos son animales pluricelulares.","answer":true}]},"id":"s02-cnt-2-9"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["cnt"],"cnb":["cnt:2.1.1"],"type":"reflection","props":{"statements":["Organicé seres vivos en unicelulares y pluricelulares"]},"id":"s02-cnt-2-10"}],"kind":"materia","area":"cnt","day":3}},{"missionId":"s02","version":"cnb-sexto-910b5485443ce7cb","lesson":{"id":"s02-ccss-2","title":"Tecnologia que cambia paises y mercados","icon":"RadioTower","minutes":15,"gancho":"Una tecnologia puede abrir ventas y difundir historias, pero tambien crear nuevas responsabilidades. ¿Ocurre igual en paises distintos?","objetivos":["Comparar cambios tecnologicos de Guatemala y Corea del Sur y sus efectos culturales, economicos y en valores sociales"],"resumen":["Entre las decadas de 1990 y 2020, Guatemala y Corea del Sur ampliaron el uso de redes digitales desde contextos tecnologicos y economicos distintos.","Los cambios tecnologicos pueden transformar cultura y economia; sus efectos sobre privacidad, inclusion, respeto y responsabilidad dependen de decisiones sociales."],"media":{"id":"s02-ccss-2-tecnologia","kind":"diagram","title":"Dos trayectorias tecnologicas","aspect":"16:9","alt":"Dos lineas de tiempo comparan cambios tecnologicos de Guatemala y Corea del Sur entre las decadas de 1990 y 2020 y sus efectos culturales, economicos y sociales.","brief":"Diagrama comparativo 1600x900, alto contraste. Linea Guatemala: radio y telefono fijo en los anos 1990 hacia telefonos moviles, mensajeria y pagos digitales en los 2020. Linea Corea del Sur: manufactura y telefonia de los 1990 hacia internet de alta velocidad, automatizacion y servicios digitales en los 2020. Bajo cada linea, tres columnas rotuladas CULTURA, ECONOMIA y VALORES SOCIALES. Texto grande; nota \\"sintesis didactica de cambios generales; no describe a toda la poblacion\\"."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:3.2.1"],"title":"Comparar cambio y efecto","prompt":"Compara como cambiaron tecnologias en **Guatemala** y **Corea del Sur** entre las decadas de 1990 y 2020, y analiza efectos en **cultura, economia y valores sociales** como privacidad, inclusion y responsabilidad.","type":"explain","props":{"icon":"GitCompareArrows","body":"Una tecnologia no produce un solo efecto. Hay que preguntar: ¿que se usaba antes?, ¿que se usa despues?, ¿que cambia en la cultura y la economia?, ¿que decisiones de respeto, equidad o privacidad aparecen?"},"id":"s02-ccss-2-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.2.1"],"title":"Dos fichas de pais suministradas","prompt":"Lee los cambios generales de Guatemala y Corea del Sur y compara efectos culturales, economicos y de valores.","type":"explain","props":{"icon":"Files","body":"**Guatemala, 1990-2020:** radio y telefono fijo siguieron presentes mientras crecieron celulares, mensajeria y pagos digitales; esto amplio difusion de idiomas y ventas, pero planteo acceso desigual, privacidad y respeto al compartir contenido. **Corea del Sur, 1990-2020:** crecieron internet de alta velocidad, automatizacion y servicios digitales; esto amplio industrias culturales y productividad, pero planteo cambios laborales, proteccion de datos y equidad. Son sintesis generales, no experiencias de toda persona."},"id":"s02-ccss-2-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.2.1"],"title":"Modelo comparativo","prompt":"Observa como comparar Guatemala y Corea del Sur sin aislar la tecnologia de sus efectos culturales, economicos y de valores.","type":"worked-example","props":{"icon":"Columns3","problem":"¿Que semejanza y diferencia muestran las fichas?","steps":[{"text":"**Cambio:** ambos paises ampliaron redes digitales; Corea del Sur tambien extendio fuertemente automatizacion industrial."},{"text":"**Cultura:** en Guatemala facilito difusion de idiomas y expresiones locales; en Corea del Sur amplio circulacion de industrias culturales."},{"text":"**Economia:** apoyo ventas y pagos en Guatemala, y productividad y servicios digitales en Corea del Sur."},{"text":"**Valores sociales:** ambos casos exigen privacidad, inclusion, respeto y responsabilidad; el acceso y los efectos no son iguales."}],"answer":"La comparacion relaciona antes y despues en dos paises con tres dimensiones de efecto."},"id":"s02-ccss-2-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.2.1"],"prompt":"Guia: compara Guatemala y Corea del Sur entre 1990 y 2020. Clasifica efectos del cambio de radio, telefonia, internet y automatizacion en cultura, economia o valores sociales.","hint":"Pregunta si cambia expresion, produccion/intercambio o convivencia responsable.","explain":"El mismo cambio puede tocar varias dimensiones; aqui se clasifica su efecto principal.","type":"sort","props":{"buckets":[{"id":"c","label":"Cultura","icon":"Languages","color":"var(--area-l1)"},{"id":"e","label":"Economia","icon":"Store","color":"var(--c-maiz-strong)"},{"id":"v","label":"Valores sociales","icon":"Scale","color":"var(--area-fc)"}],"items":[{"id":"a","text":"Difusion digital de idiomas locales en Guatemala","bucket":"c"},{"id":"b","text":"Automatizacion y productividad en Corea del Sur","bucket":"e"},{"id":"c","text":"Cuidar privacidad y trato respetuoso en ambos paises","bucket":"v"}]},"id":"s02-ccss-2-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.2.1"],"prompt":"Al comparar Guatemala y Corea del Sur de 1990 a 2020, ¿que analisis integra cambio tecnologico y efectos culturales, economicos y de valores sociales?","hint":"La respuesta debe incluir los dos paises y las tres dimensiones.","explain":"Comparar exige reconocer semejanzas y diferencias, no presentar un ejemplo aislado.","type":"choice","props":{"options":[{"id":"a","text":"Ambos ampliaron redes digitales; cambiaron expresiones culturales y actividades economicas, con retos de privacidad e inclusion"},{"id":"b","text":"Solo Guatemala tuvo cambios y estos fueron unicamente culturales"},{"id":"c","text":"La automatizacion elimina cualquier responsabilidad social"}],"correct":["a"]},"id":"s02-ccss-2-5"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:3.2.1"],"prompt":"Aplicacion independiente. Guatemala paso de mayor dependencia de radio y telefono fijo a mas servicios moviles; Corea del Sur amplio internet y automatizacion. ¿Que comparacion relaciona efectos culturales, economicos y de valores sociales?","type":"choice","props":{"options":[{"id":"a","text":"En ambos cambiaron comunicacion y economia; difusion cultural, empleo, privacidad y equidad requieren decisiones distintas segun el contexto"},{"id":"b","text":"En los dos paises toda persona recibio exactamente los mismos beneficios"},{"id":"c","text":"Los cambios tecnologicos no influyen en cultura ni valores"}],"correct":["a"]},"id":"s02-ccss-2-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:3.2.1"],"prompt":"Escribe una comparacion entre Guatemala y Corea del Sur: un cambio tecnologico entre 1990 y 2020, un efecto cultural, uno economico y una decision de privacidad, inclusion o responsabilidad.","type":"short-answer","props":{"minWords":24,"placeholder":"En Guatemala... En Corea del Sur... Ambos...","model":"Guatemala amplio servicios moviles y Corea del Sur internet y automatizacion. En ambos cambiaron cultura y economia; privacidad e inclusion requieren decisiones responsables segun cada contexto.","rubric":["Compare dos paises","Explique cambio en el tiempo","Inclui cultura, economia y valores sociales"]},"id":"s02-ccss-2-7"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:3.2.1"],"prompt":"Salida. Compara Guatemala y Corea del Sur antes y despues de ampliar radio, telefonia, internet o automatizacion. ¿Que opcion evalua efectos en cultura, economia y valores como privacidad e inclusion?","type":"choice","props":{"options":[{"id":"a","text":"Los dos contextos muestran oportunidades culturales y economicas, junto con responsabilidades sociales que no se resuelven solo con tecnologia"},{"id":"b","text":"Un aparato produce los mismos resultados culturales y economicos en cualquier pais"},{"id":"c","text":"La privacidad no tiene relacion con el cambio tecnologico"}],"correct":["a"]},"id":"s02-ccss-2-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:3.2.1"],"prompt":"Salida nueva. Compara cambios de internet, telefonia y automatizacion entre 1990 y 2020 en Guatemala y Corea del Sur y sus efectos culturales, economicos y en valores sociales.","type":"true-false","props":{"statements":[{"text":"En ambos paises las redes digitales abrieron actividades culturales y economicas, con retos de privacidad, inclusion y responsabilidad.","answer":true},{"text":"Un ejemplo aislado de Guatemala basta para comparar dos paises y todas las dimensiones.","answer":false}]},"id":"s02-ccss-2-9"}],"kind":"materia","area":"ccss","day":3}},{"missionId":"s02","version":"cnb-sexto-05881620ed95edfe","lesson":{"id":"s02-pyd-1","title":"Información comunitaria para una idea productiva","icon":"LibraryBig","minutes":15,"gancho":"En un mercado hay muchas ideas, pero la información está dispersa. ¿Cómo puede participar la comunidad para ordenarla y usarla?","objetivos":["Organizar una simulación de centro de información comunitaria que reúna aportes para generar una idea productiva familiar"],"resumen":["Un centro de información comunitaria organiza aportes identificados para que puedan consultarse y actualizarse.","La participación se promueve con roles seguros, una invitación clara, criterios de clasificación y devolución de resultados.","La información sobre necesidades, recursos y saberes ayuda a generar ideas productivas; los datos simulados no sustituyen una consulta real."],"media":{"id":"s02-pyd-1-centro-informacion","kind":"diagram","title":"Rincón de información del mercado","aspect":"16:9","alt":"Mesa simulada con fichas de necesidades, recursos y saberes, junto a tarjetas de roles para organizar aportes comunitarios.","brief":"Diagrama horizontal 1600×900 rotulado SIMULACIÓN. Mostrar una mesa con tres archivadores: NECESIDADES, RECURSOS y SABERES; tarjetas de roles RECEPCIÓN, CLASIFICACIÓN y DEVOLUCIÓN; y una ficha con autor y fecha. Sin datos de una comunidad real ni respuestas del ejercicio. Texto grande, contraste alto y orden de lectura claro."},"steps":[{"fase":"explorar","areas":["pyd"],"cnb":["pyd:1.3.2"],"title":"Participar para organizar información","prompt":"En esta simulación, un centro de información comunitaria reúne aportes con procedencia y los organiza para que sean útiles.","type":"explain","props":{"icon":"LibraryBig","body":"Promover participación significa explicar el propósito, invitar aportes voluntarios, asignar roles, cuidar los datos y devolver una síntesis. No significa inventar consultas que no ocurrieron."},"id":"s02-pyd-1-1"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:1.4.4"],"title":"De la información a una idea","prompt":"Una idea de proyecto productivo vincula una necesidad, un recurso y un saber para mejorar ingresos familiares.","type":"explain","props":{"icon":"Lightbulb","body":"**Necesidad + recurso comprobado + saber disponible = idea por evaluar.** También se revisan utilidad, posibilidad, cuidado ambiental e ingresos."},"id":"s02-pyd-1-2"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:1.3.2","pyd:1.4.4"],"prompt":"Usa solo estas fichas simuladas del rincón de información.","hint":"Cada ficha identifica tipo, procedencia didáctica y fecha.","explain":"Las fichas permiten practicar organización y generación de ideas sin atribuir datos al mercado real.","type":"reading","props":{"genre":"Fichas simuladas","heading":"Aportes para practicar","passage":"FICHA 1 · Necesidad · Puesto didáctico A · 5 de febrero: “Faltan meriendas de fruta a precio accesible”.\\n\\nFICHA 2 · Recurso · Inventario simulado · 5 de febrero: “Hay fruta madura de temporada que debe usarse pronto”.\\n\\nFICHA 3 · Saber · Familia ficticia · 6 de febrero: “Saben lavar, cortar y conservar fruta siguiendo higiene”.","questions":[{"q":"¿Qué combinación puede estudiarse como idea productiva?","options":[{"id":"a","text":"Preparar porciones de fruta con higiene para venta local"},{"id":"b","text":"Abrir una fábrica de vehículos"},{"id":"c","text":"Afirmar que todo el mercado fue consultado"}],"correct":"a"}]},"id":"s02-pyd-1-3"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:1.3.2","pyd:1.4.4"],"title":"Modelo de organización participativa","prompt":"Observa cómo el centro simulado convierte aportes en una idea sin fingir participación externa.","type":"worked-example","props":{"icon":"Workflow","problem":"Hay tres fichas y tres participantes en la práctica.","steps":[{"text":"Recepción verifica que cada aporte tenga tipo y procedencia."},{"text":"Clasificación ubica las fichas en necesidad, recurso o saber."},{"text":"Síntesis conecta los aportes y formula una idea productiva provisional."},{"text":"Devolución comunica la síntesis y señala qué falta comprobar."}],"answer":"La comunidad participa mediante aportes y roles; la idea se deriva de información organizada."},"id":"s02-pyd-1-4"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:1.3.2"],"prompt":"Clasifica tareas para organizar con participación el centro de información comunitaria simulado.","hint":"Recepción identifica; clasificación ordena; devolución comparte.","explain":"Los roles hacen visible cómo aporta cada participante.","type":"sort","props":{"buckets":[{"id":"r","label":"Recepción"},{"id":"c","label":"Clasificación"},{"id":"d","label":"Devolución"}],"items":[{"id":"1","text":"Revisar procedencia y fecha","bucket":"r"},{"id":"2","text":"Ubicar la ficha por tipo","bucket":"c"},{"id":"3","text":"Compartir síntesis y dato pendiente","bucket":"d"}]},"id":"s02-pyd-1-5"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:1.4.4"],"prompt":"Relaciona aportes del centro simulado con ideas productivas.","hint":"La idea debe usar necesidad, recurso y saber.","explain":"La información organizada permite descartar ideas que no corresponden al caso.","type":"match","props":{"pairs":[{"id":"a","left":"Fruta madura + higiene + merienda cercana","right":"Porciones de fruta preparadas con higiene"},{"id":"b","left":"Bicicletas usadas + herramientas + reparación","right":"Servicio básico de reparación"},{"id":"c","left":"Retazos + costura + bolsas reutilizables","right":"Bolsas de tela para el mercado"}]},"id":"s02-pyd-1-6"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:1.3.2","pyd:1.4.4"],"prompt":"Organiza la simulación del centro de información comunitaria para que la participación produzca una idea útil.","type":"order","props":{"items":[{"id":"a","text":"Invitar aportes con propósito y reglas claras"},{"id":"b","text":"Registrar procedencia y fecha"},{"id":"c","text":"Clasificar necesidades, recursos y saberes"},{"id":"d","text":"Generar una idea productiva provisional"},{"id":"e","text":"Devolver la síntesis y los datos pendientes"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s02-pyd-1-7"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:1.3.2","pyd:1.4.4"],"prompt":"En la simulación, falta quien clasifique los aportes del centro de información comunitaria. ¿Qué coordinación mantiene la participación y permite generar la idea productiva?","type":"choice","props":{"options":[{"id":"a","text":"Redistribuir el rol, registrar el cambio y continuar con criterios comunes"},{"id":"b","text":"Inventar que la clasificación ya ocurrió"},{"id":"c","text":"Excluir todos los aportes"}],"correct":["a"]},"id":"s02-pyd-1-8"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:1.3.2","pyd:1.4.4"],"prompt":"Aporta a la simulación: escribe una invitación breve que indique qué ficha puede entregar la comunidad, cómo se organizará y para qué idea productiva servirá.","type":"short-answer","props":{"minWords":18,"placeholder":"Invitamos a aportar... Se clasificará en... Servirá para...","model":"Invitamos a aportar una ficha de necesidad, recurso o saber con fecha. Se clasificará por tipo para estudiar una idea productiva familiar.","rubric":["Invité un aporte concreto","Expliqué cómo se organiza","Nombré el uso productivo"]},"id":"s02-pyd-1-9"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:1.3.2","pyd:1.4.4"],"prompt":"¿Qué opción promueve participación comunitaria en la organización de un centro de información y usa sus aportes para una idea productiva?","type":"choice","props":{"options":[{"id":"a","text":"Invitar fichas identificadas, asignar roles, clasificarlas y conectar necesidad, recurso y saber"},{"id":"b","text":"Guardar información sin explicar propósito ni devolver resultados"},{"id":"c","text":"Elegir una idea sin aportes ni criterios"}],"correct":["a"]},"id":"s02-pyd-1-10"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:1.3.2","pyd:1.4.4"],"prompt":"Comprueba la organización participativa del centro de información comunitaria y su uso productivo.","type":"true-false","props":{"statements":[{"text":"Asignar roles y devolver una síntesis favorece la participación.","answer":true},{"text":"Una idea productiva puede ignorar necesidades, recursos y saberes registrados.","answer":false},{"text":"Los datos de esta lección son simulados y no prueban una consulta real.","answer":true}]},"id":"s02-pyd-1-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["pyd"],"cnb":["pyd:1.3.2","pyd:1.4.4"],"type":"reflection","props":{"statements":["Organicé aportes comunitarios simulados para generar una idea productiva"],"commitments":["Distinguiré una práctica simulada de una consulta real"]},"id":"s02-pyd-1-12"}],"kind":"materia","area":"pyd","day":3}},{"missionId":"s02","version":"cnb-sexto-234c10b09f05bf8d","lesson":{"id":"s02-ccss-3","title":"Una contribucion respetuosa al patrimonio","icon":"Landmark","minutes":15,"gancho":"Una ficha para una muestra escolar puede ayudar a conservar una expresion cultural o repetir una falta de respeto. ¿Que debe incluir?","objetivos":["Crear una contribucion breve que promueva la proteccion del patrimonio y practique respeto por diferencias etnicas, culturales y linguisticas"],"resumen":["Participar en la proteccion, conservacion y desarrollo del patrimonio implica documentar o difundir con permiso, credito y beneficio respetuoso para quienes lo mantienen vivo.","Aceptar, tolerar y respetar diferencias etnicas, culturales y linguisticas exige escuchar nombres propios, evitar burlas y no presentar una cultura como adorno o curiosidad."],"media":{"id":"s02-ccss-3-fichas","kind":"image","title":"Fichas para una muestra respetuosa","aspect":"16:9","alt":"Dos fichas modelo muestran un tejido comunitario y un relato oral, con espacios para credito, permiso, accion de conservacion y regla de respeto linguistico.","brief":"Imagen didactica 1600x900 de alto contraste. Dos fichas sin fotografias de personas: A, detalle generico de tejido con campos \\"nombre dado por la comunidad\\", \\"credito a artesanas y artesanos\\", \\"permiso\\" y \\"accion de conservacion\\"; B, icono de relato oral con campos \\"idioma\\", \\"persona o comunidad portadora\\", \\"permiso para registrar\\" y \\"regla de respeto a la pronunciacion\\". Incluir texto grande: \\"No inventar significados; preguntar y acreditar\\". Diseno legible y sin atribuir motivos a una comunidad real."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:3.2.5","ccss:3.2.6"],"title":"Patrimonio y diversidad se cuidan juntos","prompt":"Participa en la **proteccion, conservacion y desarrollo del patrimonio** mediante una contribucion escrita, y practica **aceptacion, tolerancia y respeto** por diferencias etnicas, culturales y linguisticas.","type":"explain","props":{"icon":"HandHeart","body":"Promover patrimonio no es copiarlo sin permiso. Una contribucion responsable acredita a la comunidad, evita inventar significados, propone una accion viable y usa nombres e idiomas sin burla ni discriminacion."},"id":"s02-ccss-3-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.2.5","ccss:3.2.6"],"title":"Paquete suministrado para participar","prompt":"Elige una ficha y prepara una contribucion para la muestra escolar del mercado. Ambas permiten proteger patrimonio y practicar respeto por diversidad etnica, cultural y linguistica.","type":"explain","props":{"icon":"Files","body":"**Ficha A, tejido comunitario (escenario):** una asociacion autoriza mostrar una reproduccion didactica si se acredita a las personas artesanas y no se inventa el significado del diseno. **Ficha B, relato oral (escenario):** una familia autoriza citar una frase en su idioma si se escribe el nombre del idioma, se acredita a la familia y nadie imita la pronunciacion para burlarse. En ambos casos, conservar exige permiso, credito y trato digno."},"id":"s02-ccss-3-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.2.5","ccss:3.2.6"],"title":"Modelo de contribucion","prompt":"Observa una ficha que participa en la proteccion del patrimonio y practica aceptacion, tolerancia y respeto por diferencias culturales y linguisticas.","type":"worked-example","props":{"icon":"FileText","problem":"¿Como presentar la Ficha B sin apropiarse del relato?","steps":[{"text":"Credito: \\"Relato compartido con permiso por la familia del escenario; idioma indicado por ella\\"."},{"text":"Conservacion: \\"Guardaremos la fuente y no cambiaremos sus palabras sin autorizacion\\"."},{"text":"Respeto: \\"Escuchamos la pronunciacion sin burlas y aceptamos que otra lengua expresa conocimiento\\"."}],"answer":"La contribucion promueve patrimonio y convierte el respeto linguistico en una practica observable."},"id":"s02-ccss-3-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.2.5","ccss:3.2.6"],"prompt":"Guia: relaciona acciones de una contribucion con proteccion del patrimonio y respeto por diferencias etnicas, culturales y linguisticas.","hint":"Busca permiso, credito, conservacion y trato digno.","explain":"Participar exige acciones concretas, no solo decir que el patrimonio importa.","type":"match","props":{"pairs":[{"id":"a","left":"Pedir permiso y acreditar","right":"Protege la autoria y participacion de la comunidad"},{"id":"b","left":"No inventar un significado","right":"Respeta el conocimiento cultural de quienes mantienen la expresion"},{"id":"c","left":"Escuchar un idioma sin burlas","right":"Practica aceptacion, tolerancia y respeto linguistico"}]},"id":"s02-ccss-3-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.2.5","ccss:3.2.6"],"prompt":"Para crear una ficha que promueva proteccion y conservacion del patrimonio y respeto por diversidad etnica, cultural y linguistica, ¿que conjunto de acciones corresponde?","hint":"La contribucion debe poder usarse en la muestra.","explain":"Permiso, credito, una accion de cuidado y una regla de respeto vuelven ejecutable la participacion.","type":"choice","props":{"options":[{"id":"a","text":"Acreditar, usar permiso, proponer conservacion y evitar burlas o significados inventados"},{"id":"b","text":"Copiar sin credito y cambiar el nombre del idioma para que sea mas facil"},{"id":"c","text":"Decir que todo patrimonio es igual y no mencionar a quienes lo conservan"}],"correct":["a"]},"id":"s02-ccss-3-5"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:3.2.5","ccss:3.2.6"],"prompt":"Realiza ahora tu contribucion para la muestra: elige la Ficha A o B y escribe un mensaje breve que promueva proteccion, conservacion o desarrollo del patrimonio. Incluye credito o permiso y una practica de aceptacion, tolerancia y respeto por la diferencia cultural o linguistica.","type":"short-answer","props":{"minWords":22,"placeholder":"Ficha elegida... Protegemos este patrimonio al... Mostramos respeto al...","model":"Ficha B. Conservamos el relato usando solo la parte autorizada y acreditando a la familia del escenario. Respetamos su idioma al nombrarlo correctamente y escuchar sin burlas.","rubric":["Hice una contribucion completa en la actividad","Propuse una accion de proteccion o conservacion","Inclui permiso o credito","Practique respeto cultural o linguistico"]},"id":"s02-ccss-3-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:3.2.5","ccss:3.2.6"],"prompt":"Antes de publicar tu contribucion de patrimonio, elige la revision que demuestra participacion y respeto por diferencias etnicas, culturales y linguisticas.","type":"choice","props":{"options":[{"id":"a","text":"Verificar permiso, credito, accion de conservacion y lenguaje sin burla ni discriminacion"},{"id":"b","text":"Agregar un significado inventado para que la ficha parezca mas interesante"},{"id":"c","text":"Ocultar el idioma y la comunidad para que todas las fichas se vean iguales"}],"correct":["a"]},"id":"s02-ccss-3-7"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:3.2.5","ccss:3.2.6"],"prompt":"Salida. ¿Que contribucion participa en proteccion, conservacion y desarrollo del patrimonio y practica aceptacion, tolerancia y respeto por diferencias etnicas, culturales y linguisticas?","type":"choice","props":{"options":[{"id":"a","text":"Una ficha con permiso, credito, accion de cuidado y regla contra burlas o discriminacion"},{"id":"b","text":"Una copia sin fuente que cambia nombres culturales para vender mas"},{"id":"c","text":"Una afirmacion de respeto sin realizar ninguna accion de proteccion"}],"correct":["a"]},"id":"s02-ccss-3-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:3.2.5","ccss:3.2.6"],"prompt":"Salida nueva. Evalua una contribucion que promueve proteccion del patrimonio y practica aceptacion, tolerancia y respeto por diversidad etnica, cultural y linguistica.","type":"true-false","props":{"statements":[{"text":"Acreditar a quienes mantienen una expresion y respetar su idioma son acciones concretas de participacion.","answer":true},{"text":"Inventar significados y usar una pronunciacion para burlarse ayuda a conservar el patrimonio.","answer":false}]},"id":"s02-ccss-3-9"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["ccss"],"cnb":["ccss:3.2.5","ccss:3.2.6"],"type":"reflection","props":{"statements":["Interpreto indicadores sin estereotipos","Comparo efectos tecnologicos entre paises","Participo en el cuidado respetuoso del patrimonio"],"commitments":["Acreditare las fuentes culturales","Escuchare otros idiomas sin burlas"]},"id":"s02-ccss-3-10"}],"kind":"materia","area":"ccss","day":4}},{"missionId":"s02","version":"cnb-sexto-f0e13b909fd84f91","lesson":{"id":"s02-l3-2","title":"Let's act! Buying at the market","icon":"Theater","minutes":15,"gancho":"Los actores aprenden sus líneas repitiéndolas y actuándolas. ¿Y si aprendes inglés igual, actuando una compra en el mercado?","objetivos":["Usar frases de cortesía para comprar en inglés","Ordenar y completar un diálogo de compra","Participar en una dramatización para practicar el vocabulario"],"resumen":["Saludar: Good morning! / Good afternoon! · Ofrecer ayuda: Can I help you?","Pedir: Can I have three tomatoes, please? · Preguntar el precio: How much is it?","Al dar algo: Here you are. · Agradecer: Thank you! · Responder: You're welcome.","Dramatizar ayuda a recordar: repites las frases con tu voz, gestos y objetos. Equivocarse es parte de aprender."],"media":{"id":"s02-l3-2-dialogue","kind":"audio","title":"At the market (dialogue)","duration":40,"alt":"Diálogo en inglés entre una vendedora y un niño que compra tomates en el mercado.","brief":"Audio de 40 s con dos voces: vendedora adulta (Seller) y niño de unos 11 años (Buyer). Inglés claro y lento; ambiente suave de mercado de fondo, sin música. Texto exacto: Seller: \\"Good morning! Can I help you?\\" Buyer: \\"Good morning. Can I have three tomatoes, please?\\" Seller: \\"Sure. Here you are.\\" Buyer: \\"How much is it?\\" Seller: \\"It's six quetzales.\\" Buyer: \\"Here you are. Thank you!\\" Seller: \\"You're welcome. Have a nice day!\\" Después, repetir el diálogo con un silencio de 3 s tras cada línea del Seller para que el niño diga la línea del Buyer."},"steps":[{"fase":"explorar","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"convivir","title":"Polite phrases","prompt":"Estas frases hacen que una compra sea amable. Escucha el diálogo de la lección y toca cada tarjeta.","type":"explain","props":{"icon":"MessagesSquare","body":"**Please** (por favor) y **thank you** (gracias) son las palabras mágicas en cualquier idioma.","reveal":[{"icon":"Sun","front":"Saludar","back":"**Good morning!** (Buenos días) · **Good afternoon!** (Buenas tardes) · **Hello!** (¡Hola!)"},{"icon":"HandHeart","front":"Ofrecer ayuda","back":"**Can I help you?** (¿Le puedo ayudar?) — lo dice quien vende."},{"icon":"ShoppingBasket","front":"Pedir","back":"**Can I have** two mangoes, **please**? (¿Me da dos mangos, por favor?)"},{"icon":"Hand","front":"Entregar","back":"**Here you are.** (Aquí tiene.) — lo dice quien entrega algo: la fruta o el dinero."},{"icon":"Smile","front":"Agradecer y responder","back":"**Thank you!** → **You're welcome.** (¡Gracias! → De nada.) · Despedirse: **Have a nice day!** (¡Que tenga buen día!)"}]},"id":"s02-l3-2-1"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"conocer","prompt":"La vendedora te da tus tomates y dice: _\\"Here you are.\\"_ ¿Qué es lo más amable que puedes responder?","explain":"**Thank you!** (¡Gracias!). En inglés, como en español, la cortesía abre puertas. Hoy practicarás una compra completa… ¡actuando!","type":"choice","props":{"options":[{"id":"a","text":"Thank you!","icon":"Heart"},{"id":"b","text":"Good night!","icon":"Moon","feedback":"\\"Good night\\" se usa para despedirse en la noche o antes de dormir."},{"id":"c","text":"How much is it?","icon":"Coins","feedback":"Es una pregunta útil, pero primero agradece lo que te entregaron."}],"correct":["a"]},"id":"s02-l3-2-2"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"hacer","title":"Dialogue","prompt":"Escucha el audio de la lección mientras lees el diálogo. Luego responde.","type":"reading","props":{"genre":"Dialogue","heading":"At the market","passage":"Seller: Good morning! Can I help you?\\n\\nBuyer: Good morning. Can I have three tomatoes, please?\\n\\nSeller: Sure. Here you are.\\n\\nBuyer: How much is it?\\n\\nSeller: It's six quetzales.\\n\\nBuyer: Here you are. Thank you!\\n\\nSeller: You're welcome. Have a nice day!","questions":[{"q":"What does the buyer want?","options":[{"id":"a","text":"Three tomatoes"},{"id":"b","text":"Six tomatoes"},{"id":"c","text":"Three onions"}],"correct":"a"},{"q":"How much is it?","options":[{"id":"a","text":"Six quetzales"},{"id":"b","text":"Three quetzales"},{"id":"c","text":"Sixteen quetzales"}],"correct":"a","why":"\\"It's six quetzales\\": six = 6."},{"q":"¿Quién dice \\"Here you are\\" y por qué lo dicen las dos personas?","options":[{"id":"a","text":"Los dos: la vendedora al entregar los tomates y el comprador al entregar el dinero"},{"id":"b","text":"Solo la vendedora, para saludar"},{"id":"c","text":"Solo el comprador, para despedirse"}],"correct":"a","why":"\\"Here you are\\" se dice al entregar algo, sea fruta o dinero."}]},"id":"s02-l3-2-3"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: ordena este otro diálogo de compra.","hint":"Toda compra empieza con un saludo y termina con gracias. En medio: pedir, entregar, preguntar el precio.","explain":"Saludo → pedir → entregar → precio → pagar y agradecer → despedida.","type":"order","props":{"labels":{"start":"Empieza","end":"Termina"},"items":[{"id":"o1","text":"Seller: Good afternoon! Can I help you?"},{"id":"o2","text":"Buyer: Can I have two mangoes, please?"},{"id":"o3","text":"Seller: Here you are."},{"id":"o4","text":"Buyer: How much is it?"},{"id":"o5","text":"Seller: It's ten quetzales."},{"id":"o6","text":"Buyer: Here you are. Thank you!"}]},"id":"s02-l3-2-4"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"ser","title":"How to act a dialogue","prompt":"Dramatizar es una de las mejores formas de aprender un idioma: la voz, los gestos y los objetos ayudan a recordar. Toca cada consejo.","type":"explain","props":{"icon":"Theater","body":"No necesitas un escenario: basta con una mesa, unas frutas de verdad o dibujadas y alguien con quien actuar.","reveal":[{"icon":"Users","front":"Roles","back":"Una persona es **Seller** y otra **Buyer**. Después cambian de papel."},{"icon":"Apple","front":"Objetos","back":"Usa frutas o verduras de tu cocina y billetes de papel dibujados."},{"icon":"Volume2","front":"Voz y gestos","back":"Habla despacio y claro. Sonríe al saludar y extiende la mano al decir \\"Here you are\\"."},{"icon":"Heart","front":"Ánimo","back":"Si olvidas una palabra, mira el diálogo y sigue. **Equivocarse es parte de aprender**; nadie nace sabiendo inglés."}]},"id":"s02-l3-2-5"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"hacer","prompt":"Une cada frase con la **respuesta** más adecuada.","explain":"Cada frase de cortesía tiene su respuesta: Thank you → You're welcome; How much is it? → It's … quetzales.","type":"match","props":{"leftTitle":"Dices…","rightTitle":"Te responden…","pairs":[{"id":"r1","left":"Good morning!","right":"Good morning! Can I help you?"},{"id":"r2","left":"Can I have an orange, please?","right":"Sure. Here you are."},{"id":"r3","left":"How much is it?","right":"It's two quetzales."},{"id":"r4","left":"Thank you!","right":"You're welcome."}]},"id":"s02-l3-2-6"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"hacer","prompt":"Completa el diálogo con las palabras del banco.","explain":"Help (ayudar), have (pedir: Can I have…?), much (How much…?), welcome (You're welcome).","type":"fill-blank","props":{"text":"Seller: Hello! Can I [[help]] you?\\nBuyer: Can I [[have]] four carrots, please?\\nBuyer: How [[much]] is it?\\nSeller: It's eight quetzales.\\nBuyer: Thank you!\\nSeller: You're [[welcome]].","distractors":["many","please"]},"id":"s02-l3-2-7"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"convivir","prompt":"Your turn! Completa una **simulación individual** de compra con el guion suministrado. Una práctica familiar o entre compañeros después es opcional.","type":"project","props":{"goal":"Ensayar en inglés una compra completa en el mercado mediante una ruta individual sin objetos ni grabación.","steps":[{"title":"Usa la tarjeta suministrada","detail":"Producto: three oranges. Precio: six quetzales. No necesitas frutas, dibujos ni carteles externos."},{"title":"Buyer","detail":"Lee en voz alta: “Good morning. Can I have three oranges, please? How much is it? Thank you!”"},{"title":"Seller","detail":"Cambia la voz y responde: “Good morning! Sure. Here you are. It is six quetzales. You are welcome.”"},{"title":"Segunda vuelta","detail":"Repite ambos papeles sin grabarte. Extensión opcional: practica el mismo guion con otra persona disponible."}],"evidence":"Lista de cotejo de ambas voces y diálogo completado en el cuaderno; no se requiere grabación.","rubric":["Representé Buyer y Seller","Pedí algo con \\"Can I have…, please?\\"","Pregunté el precio y respondí con el número","Usé Thank you / You're welcome"]},"id":"s02-l3-2-8"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.1.2"],"prompt":"Boleto de salida: quieres pedir dos aguacates de forma amable. ¿Qué dices?","type":"choice","props":{"options":[{"id":"a","text":"Can I have two avocados, please?"},{"id":"b","text":"You're welcome, two avocados."},{"id":"c","text":"Where is two avocados?"}],"correct":["a"]},"id":"s02-l3-2-9"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.1.2"],"prompt":"Completa: el vendedor te entrega las naranjas. Tú agradeces y él responde.","type":"fill-blank","props":{"text":"Seller: Here you [[are]]. Buyer: Thank [[you]]! Seller: You're [[welcome]].","distractors":["is","please"]},"id":"s02-l3-2-10"},{"fase":"reflexionar","areas":["l3"],"cnb":[],"ambito":"ser","prompt":"How was your week? ¿Cómo te fue?","type":"reflection","props":{"statements":["Nombro frutas y verduras en inglés","Pregunto y entiendo precios del 1 al 20","Uso frases de cortesía para comprar","Me animé a actuar un diálogo en inglés"],"commitments":["Nombraré en inglés lo que compremos en casa esta semana","Actuaré el diálogo con otra persona de mi familia","Practicaré los números del 11 al 20"]},"id":"s02-l3-2-11"}],"kind":"materia","area":"l3","day":4}},{"missionId":"s02","version":"cnb-sexto-3a06eb404fabf464","lesson":{"id":"s02-art-2","title":"La melodía: sonidos que suben, bajan y se repiten","icon":"Music2","minutes":15,"gancho":"Si tarareas una canción que te gusta, tu voz sube y baja como un camino entre montañas. ¿Se podrá dibujar ese camino?","objetivos":["Explicar qué es una melodía: sonidos de distinta altura con un ritmo","Reconocer si una melodía sube, baja o se repite, al escucharla y al leerla","Distinguir movimientos por grado conjunto y por salto en el pentagrama"],"resumen":["Una melodía es una sucesión de sonidos de distinta altura, organizada con un ritmo. Es la parte de la canción que puedes cantar o tararear.","El contorno de una melodía es el \\"camino\\" que dibuja: puede subir (ascendente), bajar (descendente) o repetir la misma nota.","Grado conjunto: pasar a la nota vecina (de una línea al espacio de al lado). Salto: pasar a una nota más lejana (de línea a línea o de espacio a espacio, o más).","Para leer una melodía se leen dos cosas a la vez: la altura (dónde está la nota) y la duración (qué figura es)."],"media":{"id":"s02-art-2-contorno","kind":"animation","title":"El camino de la melodía","aspect":"16:9","duration":45,"alt":"Mientras suena una melodía de marimba, un punto brillante va dejando una línea que sube y baja sobre el pentagrama, como el perfil de una montaña.","brief":"Animación 2D de 45 s. Pentagrama en clave de sol. Suena en marimba la melodía Mi-Mi-Fa-Sol | Sol-Fa-Mi-Re | Do-Do-Re-Mi | Mi-Re-Re (tema del \\"Himno a la alegría\\" de Beethoven, dominio público). Cada nota aparece como negra (la penúltima como negra con puntillo opcional; puede simplificarse a negras) y un hilo de color las une, formando un contorno que sube y baja. Al final el hilo se separa del pentagrama y se convierte en la silueta de un volcán y un valle. Rótulos: \\"sube\\", \\"baja\\", \\"se repite\\". Narración breve en español, subtítulos."},"steps":[{"fase":"explorar","areas":["art"],"cnb":["art:1.1.2"],"ambito":"conocer","title":"¿Qué es una melodía?","prompt":"Ya conoces el **ritmo** (duraciones) y las **notas** (alturas). Cuando se juntan, nace la **melodía**. Toca cada tarjeta.","type":"explain","props":{"icon":"Music","body":"Una **melodía** es una **sucesión de sonidos de distinta altura, organizada con un ritmo**. Es la parte de una canción que puedes cantar o tararear.","reveal":[{"icon":"Timer","front":"Ritmo sin melodía","back":"Un tambor tocando \\"ta · ta · ti-ti · ta-a\\" tiene ritmo, pero todos sus golpes tienen la misma altura."},{"icon":"Music2","front":"Ritmo + altura","back":"Si cada golpe es una nota distinta (Do, Re, Mi…), el ritmo se convierte en melodía."},{"icon":"TrendingUp","front":"Contorno","back":"Es el \\"camino\\" de la melodía: **sube** (ascendente), **baja** (descendente) o **se repite** (misma nota)."},{"icon":"Mountain","front":"Dibujarla","back":"Si unes las notas del pentagrama con una línea, ves su contorno: parece el perfil de montañas y valles."}]},"id":"s02-art-2-1"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.2"],"ambito":"conocer","prompt":"Escucha la melodía de flauta. ¿Qué camino dibuja?","explain":"Empieza grave y termina aguda: es una melodía **ascendente**. Hoy aprenderás a reconocer ese camino al oír y al leer.","media":{"id":"s02-art-2-flauta","kind":"audio","title":"Una melodía que viaja","duration":10,"alt":"Una flauta dulce toca cinco notas, cada una un poco más aguda que la anterior.","brief":"Audio de 10 s: flauta dulce soprano toca Do-Re-Mi-Fa-Sol en negras, tempo tranquilo (≈80), con un final sostenido en Sol. Sin acompañamiento ni voz. Afinación cuidada. Accesibilidad: transcripcion del contenido sonoro y guion exacto de las voces, si las hay."},"type":"choice","props":{"options":[{"id":"a","text":"Sube: de grave a agudo","icon":"TrendingUp"},{"id":"b","text":"Baja: de agudo a grave","icon":"ArrowDown","feedback":"Escucha otra vez: la última nota es la más delgada (aguda)."},{"id":"c","text":"Se queda en la misma nota","icon":"Minus","feedback":"Cada nota es distinta; fíjate si se vuelven más graves o más agudas."}],"correct":["a"]},"id":"s02-art-2-2"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.2"],"ambito":"conocer","title":"Grado conjunto y salto","prompt":"Una melodía puede avanzar **paso a paso** o **saltando**. En el pentagrama se ve fácil.","type":"explain","props":{"icon":"Footprints","body":"Recuerda que las notas se escriben en **líneas** y **espacios** que se alternan. Fíjate a dónde va la nota siguiente.","reveal":[{"icon":"Footprints","front":"Grado conjunto","back":"La nota pasa a su **vecina**: de una línea al espacio de al lado (o al revés). Ejemplo: **Mi → Fa**. Suena \\"escalonado\\", fácil de cantar."},{"icon":"Rabbit","front":"Salto","back":"La nota pasa a una **más lejana**: de **línea a línea**, de **espacio a espacio** o más. Ejemplo: **Mi → Sol** (1.ª línea → 2.ª línea)."},{"icon":"Repeat","front":"Repetición","back":"La nota se queda **en el mismo lugar**. Ejemplo: **Sol → Sol**. El contorno queda plano."}]},"id":"s02-art-2-3"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.2"],"ambito":"hacer","title":"Ejemplo resuelto: leer una melodía famosa","prompt":"Esta melodía es del **\\"Himno a la alegría\\"**, del compositor alemán Ludwig van Beethoven (más de 200 años de antigüedad). Mira cómo se lee.","type":"worked-example","props":{"icon":"Music2","problem":"En 4/4 hay dos compases de negras: **| Mi · Mi · Fa · Sol | Sol · Fa · Mi · Re |**. ¿Qué camino dibuja y cómo se mueve?","steps":[{"text":"Ubico las notas (clave de sol): Mi en la 1.ª línea, Fa en el 1.er espacio, Sol en la 2.ª línea y Re debajo de la 1.ª línea."},{"text":"Compás 1: Mi · Mi (**se repite**) · Fa · Sol (**sube** paso a paso).","why":"Mi → Fa → Sol va de línea a espacio a línea: son notas vecinas, por **grado conjunto**."},{"text":"Compás 2: Sol · Sol (se repite, entre compases) y luego Fa · Mi · Re (**baja** paso a paso)."},{"text":"Ritmo: todas son negras, así que cada nota dura 1 tiempo; 4 tiempos por compás ✔."}],"answer":"La melodía **se repite, sube y luego baja**, siempre por **grado conjunto**. Su contorno es como una loma: sube hasta Sol y vuelve a bajar.","tip":"Cántala con los nombres de las notas mientras señalas el pentagrama con el dedo."},"id":"s02-art-2-4"},{"fase":"construir","areas":["art"],"cnb":["art:1.1.2"],"ambito":"hacer","prompt":"Clasifica cada par de notas: ¿se mueven por **grado conjunto** o por **salto**?","hint":"Si las dos están en líneas (o las dos en espacios), es salto. Si una está en línea y la otra en el espacio vecino, es grado conjunto.","explain":"Do-Re, Sol-La y Si-La son vecinas (grado conjunto). Mi-Sol, Fa-La y Sol-Re se saltan al menos una nota.","type":"sort","props":{"buckets":[{"id":"g","label":"Grado conjunto","icon":"Footprints","color":"var(--c-ok)"},{"id":"s","label":"Salto","icon":"Rabbit","color":"var(--area-art)"}],"items":[{"id":"p1","text":"Do → Re","bucket":"g"},{"id":"p2","text":"Mi → Sol","bucket":"s","feedback":"Entre Mi y Sol está Fa: se lo saltó."},{"id":"p3","text":"Sol → La","bucket":"g"},{"id":"p4","text":"Fa → La","bucket":"s","feedback":"Fa y La están en espacios (1.º y 2.º): entre ellas está Sol."},{"id":"p5","text":"Si → La","bucket":"g"},{"id":"p6","text":"Sol → Re (agudo)","bucket":"s"}]},"id":"s02-art-2-5"},{"fase":"aplicar","areas":["art"],"cnb":["art:1.1.2"],"ambito":"hacer","prompt":"Escucha esta frase de marimba y elige la escritura que le corresponde.","explain":"La frase empieza aguda y baja nota por nota: **Sol · Fa · Mi · Re · Do**. Es **descendente por grado conjunto**.","media":{"id":"s02-art-2-dictado","kind":"audio","title":"Dictado melódico","duration":12,"alt":"Una marimba toca cinco notas seguidas, cada una más grave que la anterior; se toca dos veces.","brief":"Audio de 12 s: marimba toca Sol4-Fa4-Mi4-Re4-Do4 en negras (tempo ≈80) y la última nota sostenida; pausa de 2 s y se repite. Sin acompañamiento. Accesibilidad: transcripcion del contenido sonoro y guion exacto de las voces, si las hay."},"type":"choice","props":{"options":[{"id":"a","text":"Do · Re · Mi · Fa · Sol","feedback":"Esa melodía sube. Lo que escuchaste empieza agudo y termina grave."},{"id":"b","text":"Sol · Fa · Mi · Re · Do"},{"id":"c","text":"Sol · Mi · Do · Mi · Sol","feedback":"Esa melodía salta y vuelve a subir. Lo que escuchaste baja paso a paso."}],"correct":["b"]},"id":"s02-art-2-6"},{"fase":"aplicar","areas":["art"],"cnb":["art:1.1.2"],"ambito":"hacer","prompt":"Completa la descripción de esta melodía en 3/4: **| Do · Mi · Sol | Sol (blanca) · Sol |** ","explain":"Do → Mi → Sol va de línea adicional a línea a línea: sube **por salto**. Después Sol se **repite**. El primer compás tiene 3 negras (3 tiempos) y el segundo, blanca + negra (3 tiempos).","type":"fill-blank","props":{"text":"En el primer compás la melodía [[sube|asciende]] por [[salto|saltos]]. En el segundo compás la nota Sol se [[repite]]. Cada compás dura [[3]] tiempos.","distractors":["baja","grado conjunto","4"]},"id":"s02-art-2-7"},{"fase":"aplicar","areas":["art"],"cnb":["art:1.1.2"],"ambito":"hacer","prompt":"En una hoja o cuaderno, dibuja el **contorno melódico** de una secuencia nueva: Do · Mi · Re · Sol · Sol.","type":"project","props":{"goal":"Representar con lápiz un contorno melódico que muestre ascensos, descensos, saltos y repetición.","steps":[{"title":"Coloca cinco puntos","detail":"De izquierda a derecha, ubica cada nota más arriba o abajo según su altura."},{"title":"Une y rotula","detail":"Une los puntos y escribe sobre cada tramo: sube, baja, salto o repetición."}],"evidence":"El dibujo queda en el papel o cuaderno; la lista solo verifica que se representaron las cinco notas y sus movimientos.","rubric":["La altura de los puntos corresponde a las notas","Distinguí ascenso, descenso, salto y repetición","El contorno se lee de izquierda a derecha"]},"id":"s02-art-2-8"},{"fase":"comprobar","areas":["art"],"cnb":["art:1.1.2"],"prompt":"¿Qué movimiento hace la melodía **La → Si → Do**?","type":"choice","props":{"options":[{"id":"a","text":"Sube por grado conjunto"},{"id":"b","text":"Baja por grado conjunto"},{"id":"c","text":"Sube por salto"},{"id":"d","text":"Se repite"}],"correct":["a"]},"id":"s02-art-2-9"},{"fase":"comprobar","areas":["art"],"cnb":["art:1.1.2"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Una melodía combina sonidos de distinta altura con un ritmo.","answer":true},{"text":"Pasar de la 1.ª línea a la 2.ª línea es un movimiento por grado conjunto.","answer":false,"why":"Entre dos líneas hay un espacio (una nota) en medio: es un salto."},{"text":"Una melodía descendente va de sonidos agudos a sonidos graves.","answer":true}]},"id":"s02-art-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["art"],"cnb":["art:1.1.2"],"type":"reflection","props":{"statements":["Encuentro el acento y cuento compases de 2, 3 y 4","Reviso si un compás suma los tiempos de la cifra","Reconozco si una melodía sube, baja o se repite"],"commitments":["Dibujaré otros contornos melódicos con lápiz y papel","Cantaré con nombres de notas una melodía corta"]},"id":"s02-art-2-11"}],"kind":"materia","area":"art","day":4}},{"missionId":"s02","version":"cnb-sexto-7c4dfbea72b9ecf9","lesson":{"id":"s02-mat-5","title":"Polígonos en la cultura maya","icon":"Landmark","minutes":15,"gancho":"Si volaras sobre una pirámide maya de Tikal, ¿qué figuras verías desde arriba?","objetivos":["Identificar polígonos regulares e irregulares en la arquitectura y los tejidos mayas","Interpretar cómo se usa la geometría en diseños de tu cultura","Repasar polígonos, sus nombres y sus ángulos"],"resumen":["Las pirámides mayas escalonadas, vistas desde arriba, muestran cuadrados o rectángulos uno dentro de otro: cada cuerpo es más pequeño que el de abajo.","En los tejidos aparecen rombos, triángulos, cuadrados y zigzags hechos con simetría.","Para interpretar un diseño: nombra sus polígonos, di si son regulares o irregulares y busca el patrón que se repite.","El significado de los diseños puede variar entre comunidades: vale la pena preguntar a quienes tejen."],"media":{"id":"s02-mat-5-tikal","kind":"image","title":"Geometría en Tikal y en un güipil","aspect":"16:9","alt":"A la izquierda, un templo escalonado de Tikal visto de frente y desde arriba, con sus cuerpos como rectángulos uno dentro de otro. A la derecha, un güipil con rombos, triángulos y zigzags.","brief":"Ilustración en dos mitades. Izquierda: un templo maya escalonado de Tikal (Petén) entre la selva; un recuadro muestra su vista desde arriba como rectángulos de colores uno dentro de otro, con la etiqueta \\"vista desde arriba\\". Derecha: la parte frontal de un güipil con franjas de rombos, triángulos en zigzag y cuadrados, con uno de los rombos resaltado con contorno. Sin personas identificables, sin reproducir un diseño específico de una comunidad; colores inspirados en textiles del altiplano. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:1.1.10","mat:1.1.6"],"ambito":"conocer","title":"Cómo interpretar un diseño","prompt":"Interpretar un diseño con ojos de matemático es responder tres preguntas. Toca cada tarjeta.","type":"explain","props":{"icon":"Search","body":"Nombrar, clasificar y buscar el patrón.","reveal":[{"icon":"Tag","front":"1. ¿Qué polígonos hay?","back":"Nómbralos por su número de lados: triángulos, cuadrados, rombos, rectángulos…"},{"icon":"Hexagon","front":"2. ¿Regulares o irregulares?","back":"El cuadrado y el triángulo equilátero son regulares. El rombo (sin ángulos rectos) y el rectángulo son irregulares."},{"icon":"Repeat","front":"3. ¿Qué se repite?","back":"Busca la simetría (una mitad refleja la otra) y la franja que se repite a lo largo."}]},"id":"s02-mat-5-1"},{"fase":"construir","areas":["mat","ccss"],"cnb":["mat:1.1.10"],"ambito":"conocer","prompt":"Una pirámide maya escalonada tiene varios \\"pisos\\" o cuerpos, cada uno más pequeño que el de abajo. **Vista desde arriba**, ¿qué verías?","explain":"Verías **cuadriláteros uno dentro de otro**: cada cuerpo es un rectángulo o cuadrado más pequeño, encima del anterior.","type":"choice","props":{"options":[{"id":"a","text":"Círculos uno dentro de otro","icon":"Target","feedback":"Los cuerpos de estas pirámides tienen lados rectos, no curvos."},{"id":"b","text":"Cuadriláteros uno dentro de otro","icon":"Square"},{"id":"c","text":"Un solo triángulo","icon":"Triangle","feedback":"De frente puede parecer un triángulo; desde arriba se ven los cuerpos escalonados."}],"correct":["b"]},"id":"s02-mat-5-2"},{"fase":"construir","areas":["mat","ccss"],"cnb":["mat:1.1.10"],"ambito":"conocer","prompt":"Lee este texto sobre la geometría en la cultura maya y responde.","type":"reading","props":{"heading":"Geometría que se construye y se teje","genre":"texto expositivo","passage":"Los antiguos mayas construyeron grandes ciudades como Tikal, en Petén. Sus templos son pirámides escalonadas: varios cuerpos de piedra, uno encima de otro, cada uno más pequeño que el de abajo. Vistos desde arriba, esos cuerpos forman rectángulos o cuadrados uno dentro de otro. Para construirlos se necesitaba medir, trazar ángulos rectos y repetir formas.\\n\\nEn muchas ciudades mayas también había canchas para el juego de pelota. Su forma, vista desde arriba, se parece a una letra I mayúscula: un rectángulo largo en el centro y dos rectángulos más anchos en los extremos.\\n\\nLa geometría sigue viva en los tejidos. En güipiles, fajas y cortes aparecen rombos, triángulos, cuadrados y zigzags. Las tejedoras cuentan hilos para que cada figura sea igual a la otra y para que el diseño sea simétrico. Muchas tejedoras explican que sus figuras tienen significados, por ejemplo relacionados con la naturaleza o con el universo, y esos significados pueden cambiar de una comunidad a otra.","questions":[{"q":"¿Qué forma tienen los cuerpos de una pirámide escalonada vistos desde arriba?","options":[{"id":"a","text":"Rectángulos o cuadrados uno dentro de otro"},{"id":"b","text":"Círculos concéntricos"},{"id":"c","text":"Hexágonos"}],"correct":"a","why":"El texto dice que forman rectángulos o cuadrados uno dentro de otro."},{"q":"¿Por qué las tejedoras cuentan hilos?","options":[{"id":"a","text":"Para gastar menos hilo"},{"id":"b","text":"Para que las figuras sean iguales y el diseño simétrico"},{"id":"c","text":"Para tejer más rápido"}],"correct":"b","why":"Contar hilos asegura figuras congruentes y simetría."},{"q":"Si quieres saber qué significa un rombo en el güipil de tu comunidad, ¿qué es lo más adecuado?","options":[{"id":"a","text":"Suponer que significa lo mismo en todos los pueblos"},{"id":"b","text":"Preguntar con respeto a una tejedora de tu comunidad"},{"id":"c","text":"Decir que no significa nada"}],"correct":"b","why":"El texto dice que los significados pueden cambiar entre comunidades; quienes tejen son la mejor fuente."}]},"id":"s02-mat-5-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.10","mat:1.1.6"],"prompt":"Estos polígonos aparecen en construcciones y tejidos mayas. ¿Son regulares o irregulares?","hint":"Regular: todos los lados iguales y todos los ángulos iguales.","explain":"Cuadrados y triángulos equiláteros son regulares; rombos sin ángulos rectos y rectángulos, irregulares.","type":"sort","props":{"buckets":[{"id":"re","label":"Regular","icon":"Hexagon","color":"var(--c-ok)"},{"id":"ir","label":"Irregular","icon":"Shapes","color":"var(--c-maiz-strong)"}],"items":[{"id":"a","text":"Cuerpo cuadrado de una pirámide, vista desde arriba","bucket":"re"},{"id":"b","text":"Rombo de un güipil con ángulos de 60° y 120°","bucket":"ir"},{"id":"c","text":"Rectángulo central de una cancha de juego de pelota","bucket":"ir"},{"id":"d","text":"Triángulo de un zigzag con sus 3 lados iguales","bucket":"re"},{"id":"e","text":"Estela de piedra: rectángulo de 3 m × 1 m","bucket":"ir"}]},"id":"s02-mat-5-4"},{"fase":"aplicar","areas":["mat","art"],"cnb":["mat:1.1.10"],"ambito":"hacer","prompt":"Teje un **rombo** con un **rombo más pequeño adentro**, como en muchas fajas. Completa la mitad derecha reflejando la izquierda.","explain":"El reflejo produce dos mitades congruentes: el rombo completo queda simétrico.","type":"symmetry-loom","props":{"motif":"Rombo dentro de rombo","palette":["#c0283b","#1c9a6b","#eeae1f"],"half":[[null,null,null,0],[null,null,0,1],[null,0,1,2],[0,1,2,2],[null,0,1,2],[null,null,0,1],[null,null,null,0]]},"id":"s02-mat-5-5"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.10","mat:1.1.7"],"prompt":"Vista desde arriba, una cancha de juego de pelota tiene forma de **I mayúscula**: un rectángulo largo y dos rectángulos más anchos en los extremos. Si recorres **todo el borde** de la figura completa, ¿cuántos lados tiene ese polígono?","hint":"Dibuja una I con \\"sombrero\\" y \\"zapatos\\" y cuenta los segmentos del contorno uno por uno.","explain":"Cada extremo ancho aporta 5 lados visibles (arriba, dos costados y dos pedacitos por dentro) y el centro aporta 2 lados largos: 5 + 5 + 2 = 12. Es un polígono irregular de 12 lados.","type":"number-input","props":{"answer":12,"misconceptions":[{"value":4,"msg":"Eso sería un solo rectángulo. La I tiene \\"escalones\\" que agregan lados."},{"value":8,"msg":"Casi: no olvides los pedacitos de borde por dentro de cada extremo."}]},"id":"s02-mat-5-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.8"],"prompt":"Repaso: un bordado tiene un **octágono**. ¿Cuánto suman sus ángulos interiores?","explain":"Octágono: 8 − 2 = 6 triángulos. 6 × 180° = 1,080°.","type":"number-input","props":{"answer":1080,"unit":"°","misconceptions":[{"value":1440,"msg":"Multiplicaste 8 × 180. Recuerda: son 2 triángulos menos que lados."},{"value":135,"msg":"135° mide cada ángulo si el octágono es regular. Te piden la suma."}]},"id":"s02-mat-5-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.6","mat:1.1.7","mat:1.1.8","mat:1.1.9"],"prompt":"Repaso de la semana. ¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Un decágono tiene 10 lados.","answer":true},{"text":"El rectángulo es un polígono regular.","answer":false,"why":"Sus lados no son todos iguales."},{"text":"El diámetro mide el doble del radio.","answer":true},{"text":"Un hexágono se divide en 6 triángulos desde un vértice.","answer":false,"why":"Se divide en 6 − 2 = 4."}]},"id":"s02-mat-5-8"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.10"],"prompt":"Una faja tiene rombos con sus 4 lados iguales y ángulos de **45° y 135°**, separados por cuadrados. ¿Qué afirmación es correcta?","type":"choice","props":{"options":[{"id":"a","text":"Los rombos son irregulares y los cuadrados son regulares"},{"id":"b","text":"Los rombos y los cuadrados son regulares"},{"id":"c","text":"Los rombos son regulares y los cuadrados irregulares"}],"correct":["a"]},"id":"s02-mat-5-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.10","mat:1.1.7"],"prompt":"Vista desde arriba, una plataforma maya tiene **8 lados iguales y 8 ángulos iguales**. ¿Cómo se describe?","type":"choice","props":{"options":[{"id":"a","text":"Octágono regular"},{"id":"b","text":"Hexágono regular"},{"id":"c","text":"Octágono irregular"}],"correct":["a"]},"id":"s02-mat-5-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["mat"],"cnb":[],"type":"reflection","props":{"statements":["Nombro polígonos de hasta 10 lados","Distingo polígonos regulares e irregulares","Calculo la suma de ángulos de pentágonos y hexágonos","Creo diseños con círculos"],"commitments":["Buscaré polígonos en los tejidos de mi familia o comunidad","Preguntaré a una tejedora qué significan sus figuras","Haré una roseta con compás o cordel"]},"id":"s02-mat-5-11"}],"kind":"materia","area":"mat","day":5}},{"missionId":"s02","version":"cnb-sexto-8055faa4d44f01d5","lesson":{"id":"s02-cnt-3","title":"Daños y prevención de parásitos","icon":"ShieldCheck","minutes":15,"gancho":"Conocer un riesgo no significa asustarse: permite elegir medidas concretas y buscar atención cuando hace falta.","objetivos":["Relacionar daños posibles de parásitos con medidas específicas de prevención y atención"],"resumen":["Los parásitos pueden irritar tejidos, consumir nutrientes o transmitir agentes infecciosos; los efectos varían.","Lavado de manos, agua tratada, cocción adecuada, calzado y no compartir objetos personales reducen riesgos específicos.","El diagnóstico y tratamiento corresponden a personal de salud; no se recomienda automedicarse."],"media":{"id":"s02-cnt-3-prevencion","kind":"diagram","title":"Riesgo y barrera de prevención","aspect":"16:9","alt":"Tres rutas didácticas muestran manos y alimentos, suelo y pies, y cabello, cada una con una barrera preventiva.","brief":"Diagrama horizontal 1600×900 con tres rutas: manos/alimentos hacia intestino, suelo hacia pies y contacto de cabello. Añadir barreras: lavado y cocción, calzado, peine personal y revisión adulta. Sin imágenes alarmantes, texto grande, contraste alto y nota: acudir a servicios de salud para diagnóstico."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:1.5.2"],"title":"Daños posibles, no diagnósticos","prompt":"El daño depende del parásito, la cantidad, el lugar afectado y la salud de la persona.","type":"explain","props":{"icon":"Activity","body":"Puede haber irritación, picazón, pérdida de nutrientes, dolor o lesión de tejidos. Por ejemplo, **Entamoeba histolytica** es una ameba parásita que puede causar enfermedad intestinal; no debe confundirse con las amebas comunes de vida libre. Un síntoma aislado no prueba por sí solo una parasitosis."},"id":"s02-cnt-3-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.5.3"],"title":"Barreras específicas","prompt":"Cada vía de exposición requiere una medida pertinente.","type":"explain","props":{"icon":"ShieldCheck","body":"Manos limpias, agua tratada y alimentos bien lavados o cocidos reducen exposición oral; el calzado protege del suelo; no compartir peines ayuda frente a piojos. El tratamiento debe indicarlo personal de salud."},"id":"s02-cnt-3-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.5.2","cnt:1.5.3"],"title":"Modelo: ruta, daño y prevención","prompt":"Relaciona una situación con una barrera sin prometer riesgo cero.","type":"worked-example","props":{"icon":"Route","problem":"Huevos microscópicos pueden pasar de manos sucias a alimentos.","steps":[{"text":"Ruta posible: manos, alimento y boca."},{"text":"Daño posible: el parásito intestinal puede consumir nutrientes o irritar."},{"text":"Barrera: lavado de manos y preparación higiénica."},{"text":"Si hay síntomas persistentes, se consulta a personal de salud."}],"answer":"La medida reduce el riesgo; no garantiza que nunca ocurra una infección."},"id":"s02-cnt-3-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.5.2","cnt:1.5.3"],"prompt":"Relaciona un daño posible con una prevención pertinente.","hint":"Busca la vía de exposición.","explain":"La prevención es específica para la ruta.","type":"match","props":{"pairs":[{"id":"a","left":"Piojos: picazón e irritación","right":"No compartir peines y solicitar revisión adulta"},{"id":"b","left":"Parásito intestinal: pérdida de nutrientes","right":"Lavado de manos, agua tratada y cocción adecuada"},{"id":"c","left":"Larvas presentes en suelo contaminado","right":"Usar calzado"}]},"id":"s02-cnt-3-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.5.3"],"prompt":"Clasifica medidas responsables.","hint":"Prevenir no es automedicarse.","explain":"La atención profesional evita tratamientos inadecuados.","type":"sort","props":{"buckets":[{"id":"si","label":"Prevención o atención segura"},{"id":"no","label":"Práctica riesgosa"}],"items":[{"id":"a","text":"Lavarse las manos antes de comer","bucket":"si"},{"id":"b","text":"Tomar medicina sin diagnóstico","bucket":"no"},{"id":"c","text":"Cocinar bien los alimentos","bucket":"si"},{"id":"d","text":"Compartir peines durante un brote","bucket":"no"}]},"id":"s02-cnt-3-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.5.2","cnt:1.5.3"],"prompt":"En un escenario escolar aparecen piojos. ¿Qué respuesta relaciona el daño posible con prevención respetuosa?","type":"choice","props":{"options":[{"id":"a","text":"Evitar burlas, no compartir peines y pedir revisión y orientación adulta"},{"id":"b","text":"Aislar y culpar a una persona"},{"id":"c","text":"Tomar cualquier medicamento sin indicación"}],"correct":["a"]},"id":"s02-cnt-3-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.5.2","cnt:1.5.3"],"prompt":"Relaciona escenarios nuevos con una acción que reduzca el daño o la exposición.","type":"sort","props":{"buckets":[{"id":"oral","label":"Ruta oral"},{"id":"piel","label":"Piel o cabello"},{"id":"salud","label":"Atención"}],"items":[{"id":"a","text":"Lavar manos y preparar alimentos con higiene","bucket":"oral"},{"id":"b","text":"Usar calzado y objetos personales","bucket":"piel"},{"id":"c","text":"Consultar ante síntomas persistentes","bucket":"salud"}]},"id":"s02-cnt-3-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.5.2","cnt:1.5.3"],"prompt":"¿Qué opción relaciona un daño posible de parásitos con una prevención adecuada?","type":"choice","props":{"options":[{"id":"a","text":"Pérdida de nutrientes; higiene de manos, agua segura y alimentos bien preparados"},{"id":"b","text":"Picazón; compartir peines"},{"id":"c","text":"Dolor; automedicarse siempre"}],"correct":["a"]},"id":"s02-cnt-3-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.5.2","cnt:1.5.3"],"prompt":"Comprueba daños, prevención y atención.","type":"true-false","props":{"statements":[{"text":"Los efectos de un parásito pueden variar entre personas.","answer":true},{"text":"Lavarse las manos reduce algunas rutas de exposición.","answer":true},{"text":"Cualquier síntoma confirma un parásito y permite automedicarse.","answer":false,"why":"El diagnóstico y tratamiento corresponden a personal de salud."}]},"id":"s02-cnt-3-9"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["cnt"],"cnb":["cnt:1.5.2","cnt:1.5.3"],"type":"reflection","props":{"statements":["Relacioné daños posibles con prevención y atención segura"]},"id":"s02-cnt-3-10"}],"kind":"materia","area":"cnt","day":5}},{"missionId":"s02","version":"cnb-sexto-6f8f7a082494c6dd","lesson":{"id":"s02-fc-2","title":"Desarrollo social: ¿se cumplen los derechos en Guatemala?","icon":"TrendingUp","minutes":15,"gancho":"En algunas comunidades hay escuela, agua y centro de salud; en otras, faltan. ¿Cómo podemos saber si un país avanza en el cumplimiento de los derechos?","objetivos":["Explicar qué es el desarrollo social y cómo se relaciona con los derechos humanos","Analizar datos sencillos para comparar la situación de los derechos en distintos lugares","Reconocer retos reales de Guatemala, como la desnutrición crónica, y quién vigila los derechos"],"resumen":["El desarrollo social es la mejora de la calidad de vida de toda la población: salud, educación, alimentación, vivienda, empleo y participación. Hay desarrollo social cuando los derechos se vuelven realidad para todos.","Para analizar la situación de un derecho se usan datos (indicadores): cuántas casas tienen agua potable, cuántos niños van a la escuela, etc. Comparar lugares muestra desigualdades (brechas).","Un gran reto de Guatemala es la desnutrición crónica: según la encuesta nacional de salud de 2014-2015, casi la mitad de las niñas y los niños menores de cinco años la padecían. Afecta su salud y su aprendizaje.","La Procuraduría de los Derechos Humanos vigila que se respeten los derechos. El Estado, las comunidades y las familias trabajan juntos para el desarrollo social."],"media":{"id":"s02-fc-2-brecha","kind":"animation","title":"Dos aldeas, una brecha","aspect":"16:9","duration":45,"alt":"Dos aldeas lado a lado; en cada una se llenan barras de agua potable, escuela y centro de salud, y se ve que una tiene mucho más que la otra.","brief":"Animación 2D de 45 s. Pantalla dividida: \\"Aldea A\\" (con carretera asfaltada) y \\"Aldea B\\" (lejana, camino de tierra). Sobre cada aldea suben tres barras con íconos: gota (agua potable), libro (niños en la escuela), cruz (centro de salud cerca). En la Aldea A las barras suben alto; en la B quedan bajas. Aparece una llave de corchete entre las barras con la palabra \\"brecha\\". Narración: \\"Los datos nos ayudan a ver dónde los derechos todavía no se cumplen\\". Etiqueta visible: \\"Datos hipotéticos\\". Sin cifras reales, estilo plano, colores cálidos. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"conocer","title":"¿Qué es el desarrollo social?","prompt":"Un país no se desarrolla solo porque tenga edificios altos. Toca cada tarjeta para entender el **desarrollo social**.","type":"explain","props":{"icon":"TrendingUp","body":"Desarrollo social y derechos humanos van juntos: **hay desarrollo social cuando los derechos se cumplen para todas las personas**, no solo para algunas.","reveal":[{"icon":"Users","front":"Desarrollo social","back":"La mejora de la **calidad de vida de toda la población**: salud, educación, alimentación, vivienda, empleo y participación."},{"icon":"BarChart3","front":"Indicador","back":"Un **dato** que muestra cómo está un derecho. Ejemplo: de cada 10 casas, cuántas tienen agua potable."},{"icon":"Scale","front":"Brecha","back":"La **diferencia** entre dos grupos o lugares. Ejemplo: entre el área urbana y el área rural, o entre niñas y niños."},{"icon":"Landmark","front":"Procuraduría de los Derechos Humanos","back":"Institución creada por la **Constitución de 1985**. El Procurador vigila que el Estado respete los derechos humanos y recibe denuncias."}]},"id":"s02-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"conocer","prompt":"Si quisieras saber si en tu municipio se cumple el derecho a la educación, ¿qué dato te ayudaría **más**?","explain":"Los **datos** (cuántos niños estudian, cuántas casas tienen agua…) permiten analizar la situación de los derechos con hechos, no solo con opiniones.","type":"choice","props":{"options":[{"id":"a","text":"Cuántas niñas y niños en edad escolar van a la escuela","icon":"School"},{"id":"b","text":"Cuántos equipos de fútbol hay","icon":"Trophy","feedback":"Es un dato interesante, pero no dice nada sobre la educación."},{"id":"c","text":"De qué color están pintadas las escuelas","icon":"Palette","feedback":"El color no nos dice si los niños están aprendiendo."}],"correct":["a"]},"id":"s02-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"hacer","prompt":"Supongamos que un comité revisó **10 casas** en la aldea El Porvenir. Construye la gráfica con estos datos: agua potable **6**, electricidad **8**, casas donde todos los niños van a la escuela **9**, centro de salud a menos de 30 minutos **2**.","hint":"Cada barra sube de 1 en 1. Busca cada dato en la consigna y súbela hasta ese número.","explain":"La barra más baja (centro de salud cercano: 2 de 10) muestra el derecho que **menos** se cumple en esa aldea: la salud.","type":"chart-builder","props":{"categories":[{"id":"agua","label":"Agua potable","icon":"Droplets","color":"var(--area-ccss)"},{"id":"luz","label":"Electricidad","icon":"Zap","color":"var(--c-maiz-strong)"},{"id":"esc","label":"Escuela","icon":"School","color":"var(--c-jade)"},{"id":"sal","label":"Salud cerca","icon":"Stethoscope","color":"var(--area-fc)"}],"data":[6,8,9,2],"max":10,"step":1,"unit":"casas de 10","source":"Datos hipotéticos de la aldea El Porvenir"},"id":"s02-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"hacer","title":"Ejemplo resuelto: leer la gráfica como ciudadano","prompt":"Una gráfica no termina en las barras: hay que **interpretarla**. Mira cómo.","type":"worked-example","props":{"icon":"BarChart3","problem":"Con los datos de El Porvenir (agua 6, electricidad 8, escuela 9, salud cercana 2, de 10 casas), ¿qué derecho está en peor situación y qué se puede proponer?","steps":[{"text":"**Busco el dato más bajo:** salud cercana, **2 de 10** casas."},{"text":"**Lo traduzco a derechos:** 8 de cada 10 familias no tienen un centro de salud cerca. El **derecho a la salud** no se cumple plenamente.","why":"10 − 2 = 8 familias sin servicio cercano."},{"text":"**Comparo:** la escuela (9 de 10) está mucho mejor. Hay una **brecha** entre educación y salud en la aldea."},{"text":"**Propongo:** el COCODE puede presentar estos datos a la municipalidad y al Ministerio de Salud para pedir un puesto de salud o jornadas médicas."}],"answer":"El derecho en peor situación es la **salud**. Con los datos, la comunidad puede **pedir soluciones con argumentos**.","tip":"Dato → derecho → comparación → propuesta."},"id":"s02-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"conocer","prompt":"Lee este texto sobre la situación real de algunos derechos en Guatemala y responde.","type":"reading","props":{"genre":"Texto informativo","heading":"Derechos que aún son un reto","passage":"La **Constitución Política de la República de Guatemala** reconoce que todas las personas tienen derecho a la vida, la salud y la educación. Sin embargo, esos derechos no se cumplen igual en todo el país.\\n\\nUno de los mayores retos es la **desnutrición crónica**: una niña o un niño la padece cuando, por no alimentarse bien durante mucho tiempo, su estatura queda por debajo de la que corresponde a su edad. Según la encuesta nacional de salud de 2014-2015, **casi la mitad** de las niñas y los niños menores de cinco años en Guatemala la padecían. Esto afecta su salud y su aprendizaje durante toda la vida.\\n\\nTambién hay **brechas**: en muchas comunidades rurales el centro de salud o la escuela quedan a varios kilómetros. Para vigilar que se respeten los derechos existe la **Procuraduría de los Derechos Humanos**. El **desarrollo social** se logra cuando el Estado, las comunidades y las familias trabajan juntos para que los derechos sean una realidad para todos.","questions":[{"q":"¿Qué es la desnutrición crónica, según el texto?","options":[{"id":"a","text":"Tener una estatura menor a la de la edad por no alimentarse bien durante mucho tiempo"},{"id":"b","text":"Comer demasiados dulces un día"},{"id":"c","text":"Una enfermedad que se contagia por el aire"}],"correct":"a"},{"q":"¿Por qué la desnutrición afecta también el derecho a la educación?","options":[{"id":"a","text":"Porque un niño mal alimentado tiene más dificultad para concentrarse y aprender"},{"id":"b","text":"Porque la comida y la escuela no tienen relación"},{"id":"c","text":"Porque solo afecta a las personas adultas"}],"correct":"a","why":"Los derechos son interdependientes: sin alimentación adecuada, aprender es más difícil."},{"q":"¿Qué institución vigila el respeto de los derechos humanos?","options":[{"id":"a","text":"La Procuraduría de los Derechos Humanos"},{"id":"b","text":"El mercado municipal"},{"id":"c","text":"La liga de fútbol"}],"correct":"a"}]},"id":"s02-fc-2-5"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"hacer","prompt":"Supongamos que en otra aldea, Las Flores, **7 de cada 10** casas **no** tienen agua potable. En un grupo de **30 casas**, ¿cuántas **sí** tienen agua potable?","explain":"Si 7 de cada 10 no tienen agua, 3 de cada 10 sí tienen. En 30 casas hay 3 grupos de 10: 3 × 3 = 9 casas con agua potable.","type":"number-input","props":{"answer":9,"unit":"casas","misconceptions":[{"value":21,"msg":"21 son las casas que NO tienen agua (7 × 3). La pregunta es por las que sí tienen."},{"value":3,"msg":"3 es por cada 10 casas. Hay 30 casas: son 3 grupos de 10."}]},"id":"s02-fc-2-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.2"],"prompt":"Clasifica: ¿es un **avance** del desarrollo social o un **reto pendiente**?","explain":"Analizar la situación de los derechos es reconocer lo que se ha logrado y lo que falta, sin exagerar ni negar los problemas.","type":"sort","props":{"buckets":[{"id":"av","label":"Avance","icon":"TrendingUp","color":"var(--c-ok)"},{"id":"re","label":"Reto pendiente","icon":"Target","color":"var(--c-maiz-strong)"}],"items":[{"id":"r1","text":"Una aldea recibe por primera vez un puesto de salud con enfermera","bucket":"av"},{"id":"r2","text":"Muchas niñas y niños pequeños con desnutrición crónica","bucket":"re"},{"id":"r3","text":"Escuelas rurales que enseñan en el idioma materno y en español","bucket":"av"},{"id":"r4","text":"Familias rurales que caminan horas para llegar a un centro de salud","bucket":"re"},{"id":"r5","text":"Un sistema de agua potable construido con la comunidad y la municipalidad","bucket":"av"}]},"id":"s02-fc-2-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"hacer","prompt":"Elige **un derecho de la niñez** y analiza su situación en tu comunidad: ¿qué dato o hecho observas?, ¿es un avance o un reto?, ¿quién debería actuar y qué propones?","type":"short-answer","props":{"minWords":35,"placeholder":"Elegí el derecho a… En mi comunidad observo que…","model":"Elegí el derecho a la educación. En mi comunidad observo que casi todos los niños van a la escuela primaria, pero varios jóvenes no siguen el básico porque el instituto queda lejos. Es un avance en primaria y un reto en básico. La municipalidad y el Ministerio de Educación deberían actuar; propongo que el COCODE pida transporte escolar o un instituto por cooperativa más cerca.","rubric":["Elegí un derecho de la niñez","Usé un dato o un hecho observado","Dije si es un avance o un reto","Nombré quién debe actuar y propuse algo posible"]},"id":"s02-fc-2-8"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.2"],"prompt":"¿Cuál es la mejor definición de **desarrollo social**?","type":"choice","props":{"options":[{"id":"a","text":"La mejora de la calidad de vida de toda la población, cuando los derechos se cumplen para todos"},{"id":"b","text":"Construir muchos edificios altos en la capital"},{"id":"c","text":"Que unas pocas familias tengan mucho dinero"}],"correct":["a"]},"id":"s02-fc-2-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.2"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La desnutrición crónica es uno de los grandes retos para los derechos de la niñez en Guatemala.","answer":true},{"text":"Una brecha es la diferencia en la situación de dos lugares o grupos.","answer":true},{"text":"En Guatemala todos los derechos se cumplen igual en todas las comunidades.","answer":false,"why":"Todavía hay brechas, por ejemplo entre áreas urbanas y rurales."},{"text":"La Convención sobre los Derechos del Niño protege a toda persona menor de 18 años.","answer":true}]},"id":"s02-fc-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["fc"],"cnb":["fc:1.2.2"],"type":"reflection","props":{"statements":["Conozco la Convención sobre los Derechos del Niño y la Ley PINA","Clasifico los derechos de la niñez en cuatro familias","Analizo con datos si un derecho se cumple en un lugar"],"commitments":["Contaré a mi familia qué es el interés superior del niño","Observaré un dato de mi comunidad (agua, escuela, salud) y lo anotaré","Si sé de un niño que sufre, hablaré con una persona adulta de confianza"]},"id":"s02-fc-2-11"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s02","version":"cnb-sexto-fcbc79912e70642e","lesson":{"id":"s02-ef-2","title":"Combinar habilidades: correr, saltar y girar","icon":"Footprints","minutes":15,"gancho":"Un portero de fútbol corre, salta y atrapa en un solo movimiento. ¿Cómo aprende el cuerpo a unir varias acciones sin trabarse?","objetivos":["Reconocer las habilidades motrices simples: desplazarse, saltar, girar, lanzar y atrapar","Combinar dos o más habilidades simples en una habilidad genérica","Coordinar flexión, extensión y rotación al saltar, caer y girar"],"resumen":["Las habilidades simples (básicas) son: desplazarse (caminar, correr), saltar, girar, lanzar y recibir (atrapar).","Una habilidad genérica combina dos o más habilidades simples de forma fluida: correr y saltar, botar mientras corres, girar y lanzar. Son la base de todos los deportes.","En el salto: flexión de rodillas para prepararse, extensión fuerte para impulsarse y flexión otra vez para caer suave, sobre la punta de los pies y luego todo el pie.","Para combinar habilidades: practica cada una por separado, luego únelas despacio y aumenta la velocidad poco a poco."],"media":{"id":"s02-ef-2-circuito","kind":"video","title":"Circuito de habilidades","aspect":"9:16","duration":50,"alt":"Un niño corre, salta una línea, cae con rodillas dobladas, gira media vuelta y lanza una pelota a un aro; primero despacio y luego fluido.","brief":"Video vertical de 50 s en patio escolar. Un niño y una niña (ropa deportiva sencilla, rostros no protagonistas) demuestran un circuito: (1) cada habilidad por separado con rótulo (\\"correr\\", \\"saltar\\", \\"girar\\", \\"lanzar\\"); (2) la combinación despacio; (3) la combinación fluida. Cámara lenta en el salto con rótulos \\"flexión → extensión → flexión (caída suave)\\". Materiales caseros: línea de yeso, llanta vieja como aro, pelota de trapo. Aviso \\"Practica en suelo seco y despejado\\". Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:1.3.5"],"ambito":"conocer","title":"De simples a genéricas","prompt":"Así como las letras forman palabras, las **habilidades simples** se unen para formar **habilidades genéricas**. Toca cada tarjeta.","type":"explain","props":{"icon":"Blocks","body":"Primero dominamos las simples; luego las combinamos; después las usamos en deportes (habilidades específicas).","reveal":[{"icon":"Footprints","front":"Desplazarse","back":"Caminar, correr, reptar, cuadrupedia. Mover todo el cuerpo de un lugar a otro."},{"icon":"ArrowUp","front":"Saltar","back":"Despegar del suelo con una o dos piernas y caer con control."},{"icon":"RotateCw","front":"Girar","back":"Rotar el cuerpo: media vuelta, vuelta completa, rodar."},{"icon":"Target","front":"Lanzar y recibir","back":"Enviar un objeto con las manos o los pies, y atraparlo o detenerlo."},{"icon":"Layers","front":"Genéricas","back":"Combinaciones fluidas: **correr + saltar** un charco, **correr + botar**, **girar + lanzar**, **saltar + atrapar**."}]},"id":"s02-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.3.5"],"ambito":"conocer","prompt":"En el **basquetbol**, una jugadora **corre botando la pelota** hacia la canasta. ¿Cuántas habilidades está haciendo a la vez?","explain":"Dos: **correr** (desplazarse) y **botar** la pelota. Cuando unimos habilidades simples en una sola acción fluida, formamos una **habilidad genérica**.","type":"choice","props":{"options":[{"id":"a","text":"Una sola","icon":"Circle","feedback":"Fíjate en sus pies y en sus manos: hacen cosas distintas al mismo tiempo."},{"id":"b","text":"Dos: correr y botar","icon":"Layers"}],"correct":["b"]},"id":"s02-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.3.6"],"ambito":"hacer","title":"El salto: flexión, extensión, flexión","prompt":"El salto es una habilidad que usa los tres movimientos que aprendiste la semana pasada. Toca cada fase.","media":{"id":"s02-ef-2-salto","kind":"animation","title":"Las fases del salto","aspect":"16:9","duration":30,"alt":"Una figura de niña salta: primero dobla rodillas y brazos atrás, luego se estira hacia arriba con brazos al cielo, y cae doblando las rodillas.","brief":"Animación 2D de 30 s, figura de niña en silueta con articulaciones marcadas (cadera, rodilla, tobillo). Fase 1 \\"Preparación\\": flexión de rodillas y cadera, brazos atrás (arcos de ángulo en rojo que se cierran). Fase 2 \\"Impulso\\": extensión explosiva de piernas y brazos arriba (arcos que se abren en verde). Fase 3 \\"Vuelo\\". Fase 4 \\"Caída\\": contacto con punta de pie → todo el pie, flexión de rodillas para amortiguar (resorte dibujado). Se repite en cámara lenta. Rótulos grandes."},"type":"explain","props":{"icon":"ArrowUp","body":"Las piernas funcionan como un **resorte**: se doblan para cargar energía y se estiran para liberarla.","reveal":[{"icon":"ArrowDown","front":"1. Preparación","back":"**Flexión** de rodillas y cadera, brazos hacia atrás. Cargas energía como un resorte."},{"icon":"ArrowUp","front":"2. Impulso","back":"**Extensión** fuerte de piernas y brazos hacia arriba y adelante."},{"icon":"Feather","front":"3. Caída suave","back":"Caes en la **punta de los pies** y luego todo el pie, con **flexión** de rodillas para amortiguar. Nunca caigas con las piernas rectas."},{"icon":"RotateCw","front":"+ Rotación","back":"Si quieres girar en el aire, **rota** hombros y cadera hacia donde quieres ir al despegar."}]},"id":"s02-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.3.5","ef:1.3.6"],"ambito":"hacer","title":"Ejemplo resuelto: aprender a correr y saltar un charco","prompt":"Mira cómo Fernanda aprende a combinar **correr + saltar** sin detenerse.","type":"worked-example","props":{"icon":"Droplets","problem":"Después de la lluvia hay un charco en el camino a la escuela (imaginario: una línea doble de yeso en el patio). Fernanda quiere pasarlo corriendo, sin frenar ni mojarse.","steps":[{"text":"**Practica cada habilidad sola:** corre 10 pasos; luego salta la línea desde parada, con la técnica de flexión-extensión-flexión."},{"text":"**Une despacio:** trota, y a 3 pasos de la línea mira dónde va a despegar.","why":"Calcular el lugar de despegue evita frenarse o pisar el charco."},{"text":"**Despega con un pie** y lleva la otra pierna adelante (como un paso largo en el aire)."},{"text":"**Cae con la pierna adelantada**, rodilla doblada, y **sigue corriendo**.","why":"Si la caída es suave y sigue el movimiento, la combinación queda fluida."},{"text":"**Aumenta la velocidad** poco a poco en los siguientes intentos."}],"answer":"Fernanda formó la habilidad genérica **correr + saltar**: primero practicó por separado, luego unió despacio y al final aceleró.","tip":"Si te trabas, vuelve a la velocidad lenta: la coordinación se construye con repeticiones."},"id":"s02-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.3.5"],"ambito":"conocer","prompt":"Clasifica cada acción: ¿habilidad **simple** o **genérica** (combinación)?","hint":"Cuenta cuántas acciones distintas hay: si hay dos o más unidas, es genérica.","explain":"Una sola acción = simple. Dos o más acciones unidas de forma fluida = genérica.","type":"sort","props":{"buckets":[{"id":"s","label":"Simple","icon":"Circle","color":"var(--area-ef)"},{"id":"g","label":"Genérica","icon":"Layers","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"Saltar con los pies juntos en el lugar","bucket":"s"},{"id":"x2","text":"Correr y saltar una cuerda que gira","bucket":"g"},{"id":"x3","text":"Caminar","bucket":"s"},{"id":"x4","text":"Girar media vuelta y lanzar una pelota","bucket":"g"},{"id":"x5","text":"Atrapar una pelota estando quieto","bucket":"s"},{"id":"x6","text":"Correr botando una pelota","bucket":"g"}]},"id":"s02-ef-2-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.3.5","ef:1.3.6"],"ambito":"hacer","prompt":"¡Circuito del mandadero! **Calentamiento (1 min):** trote suave, rotación de tobillos, rodillas y cadera. **Circuito (repite 3 veces):** corre 5 pasos → **salta** una línea (flexión-extensión-flexión) → **gira** media vuelta → **lanza** una pelota de trapo o un calcetín enrollado a una caja o llanta → corre de regreso. Primero despacio, luego fluido. **Poco espacio:** paso largo en lugar de correr, salto en el lugar, giro y lanzamiento a una caja cercana. **Adaptación:** en silla de ruedas: avanza, gira la silla y lanza. **Estira** piernas al final y toma agua.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después del calentamiento","exercise":{"name":"Trote suave y rotaciones","icon":"RotateCw","seconds":60}},{"label":"Después del circuito","exercise":{"name":"Correr, saltar, girar y lanzar","icon":"Footprints","seconds":90}}]},"id":"s02-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.3.6"],"ambito":"hacer","prompt":"Al saltar la línea, Pablo siente un golpe fuerte en las rodillas cada vez que cae. ¿Qué está haciendo mal?","explain":"Al caer hay que **flexionar** las rodillas y apoyar primero la punta del pie: así los músculos amortiguan el impacto como un resorte.","type":"choice","props":{"options":[{"id":"a","text":"Cae con las piernas rectas, sin doblar las rodillas"},{"id":"b","text":"Dobla las rodillas antes de saltar","feedback":"Eso es correcto: es la fase de preparación."},{"id":"c","text":"Mueve los brazos hacia arriba al impulsarse","feedback":"Eso es correcto: los brazos ayudan al impulso."}],"correct":["a"]},"id":"s02-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.3.5"],"ambito":"hacer","prompt":"Ordena los pasos para **aprender** una habilidad genérica nueva.","explain":"Separado → unido despacio → unido con más velocidad → usado en un juego.","type":"order","props":{"items":[{"id":"a","text":"Practicar cada habilidad simple por separado"},{"id":"b","text":"Unirlas despacio"},{"id":"c","text":"Aumentar la velocidad poco a poco"},{"id":"d","text":"Usar la combinación en un juego"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s02-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.3.5"],"prompt":"¿Qué ejemplo combina dos habilidades simples en una **habilidad genérica**?","type":"choice","props":{"options":[{"id":"a","text":"Correr y saltar un obstáculo"},{"id":"b","text":"Caminar"},{"id":"c","text":"Estar sentado"}],"correct":["a"]},"id":"s02-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.3.6"],"prompt":"Une cada fase del salto con el movimiento de las rodillas.","type":"match","props":{"pairs":[{"id":"p","left":"Preparación","right":"Flexión para cargar energía"},{"id":"i","left":"Impulso","right":"Extensión fuerte"},{"id":"c","left":"Caída","right":"Flexión para amortiguar"}]},"id":"s02-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["ef"],"cnb":["ef:1.3.5"],"type":"reflection","props":{"statements":["Acelero y freno con control y seguridad","Reconozco habilidades simples y genéricas","Salto y caigo suave con flexión y extensión"],"commitments":["Jugaré al semáforo con mi familia","Practicaré correr y saltar una línea","Siempre caeré con las rodillas dobladas"]},"id":"s02-ef-2-11"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s02","version":"cnb-sexto-ced35831edae99b6","lesson":{"id":"s02-d5-taller","kind":"taller","day":5,"title":"Un puesto sano y respetuoso","icon":"Store","minutes":18,"gancho":"Si tu grado organizara un mercadito en la escuela, ¿qué venderías, cómo cuidarías la salud de tus clientes y cómo los atenderías?","objetivos":["Planear una oferta sencilla que una una necesidad, un recurso y un saber de la comunidad","Escribir un procedimiento concreto de higiene para manipular alimentos","Atender a cada cliente con lenguaje respetuoso y útil"],"resumen":["Necesidad + recurso + saber = idea productiva. Una oferta simple dice qué se ofrece y a qué precio.","Lavarse las manos con agua y jabón antes de preparar, lavar los alimentos con agua apta para consumo, separar el dinero de la comida, dejar el cuchillo a una persona adulta, mantener el alimento tapado y volver a lavarse las manos después de manejar dinero ayuda a reducir riesgos de contaminación.","Un instructivo tiene título, materiales y pasos en orden con palabras como primero, después, luego y finalmente.","Con personas mayores o desconocidas usamos usted, títulos como don o doña y expresiones como buenos días, por favor y gracias."],"media":{"id":"s02-d5-taller-puesto","kind":"image","title":"El mercadito escolar","aspect":"4:3","alt":"Patio de escuela con puestos hechos con mesas y manteles tejidos; un puesto de vasitos de fruta tapados, un cartel de precios en quetzales y una estación para lavarse las manos.","brief":"Ilustración plana y alegre de un mercadito escolar en el patio de una escuela pública guatemalteca: mesas con manteles de tela típica, un puesto de fruta picada en vasos tapados, un recipiente con chorro y jabón para lavarse las manos, un recipiente tapado para la fruta, un cartel \\"Fruta fresca · Q2.00 / Fresh fruit\\" y niñas y niños de distintos pueblos atendiendo a una señora mayor. Sin marcas comerciales ni rostros identificables. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["pyd","cnt","l2"],"cnb":["pyd:1.4.4","cnt:1.5.3","l2:2.1.1","l2:1.3.1"],"ambito":"emprender","title":"Misión y tiempo · 1 min","prompt":"En **18 minutos** recuperarás dos decisiones breves y dedicarás la mayor parte del tiempo a construir, revisar y corregir el plan de tu puesto.","type":"explain","props":{"icon":"Timer","body":"El plan tendrá una **oferta sencilla**, un **procedimiento de higiene** y **frases de servicio respetuoso**.","reveal":[{"icon":"Lightbulb","front":"Productividad","back":"Necesidad + recurso local + saber familiar."},{"icon":"ShieldCheck","front":"Ciencias y L2","back":"El procedimiento seguro que ya modelaste y ordenaste."},{"icon":"MessagesSquare","front":"L2","back":"Saludo, oferta y despedida con usted y palabras de cortesía."}]},"id":"s02-d5-taller-1"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:1.4.4"],"ambito":"emprender","prompt":"Recuperación rápida · 1 min. Hay poca fruta lista en el recreo, la familia tiene mangos y sabe preparar vasitos. ¿Qué oferta une necesidad, recurso y saber?","hint":"Usa la fórmula que ya aprendiste.","explain":"La oferta responde a la necesidad y aprovecha un recurso y un saber disponibles.","type":"choice","props":{"options":[{"id":"a","text":"Vasitos de mango a un precio sencillo","icon":"Citrus"},{"id":"b","text":"Juguetes comprados lejos de la comunidad","icon":"ToyBrick"},{"id":"c","text":"Un producto que nadie sabe preparar","icon":"CircleHelp"}],"correct":["a"]},"id":"s02-d5-taller-2"},{"fase":"construir","areas":["cnt","l2"],"cnb":["cnt:1.5.3","l2:2.1.1"],"ambito":"hacer","prompt":"Recuperación del procedimiento · 2 min. Ordena los cuidados modelados en L2 antes de escribir tu versión.","hint":"Empieza por organizar roles y lavarse las manos antes de preparar; termina con el nuevo lavado después de manejar dinero.","explain":"El orden recupera los seis cuidados enseñados: manos lavadas antes de preparar, agua apta para consumo, dinero separado, cuchillo a cargo de una persona adulta, alimento tapado y nuevo lavado de manos después de manejar dinero.","type":"order","props":{"items":[{"id":"h1","text":"Antes de empezar, separa el dinero de la comida y asigna quién cobrará.","icon":"BadgeDollarSign"},{"id":"h2","text":"Primero, antes de preparar, quienes servirán se lavan las manos con agua y jabón.","icon":"HandHelping"},{"id":"h3","text":"Una persona adulta lava el alimento con agua apta para consumo y usa el cuchillo.","icon":"UtensilsCrossed"},{"id":"h4","text":"Sirve el alimento y mantenlo tapado.","icon":"Container"},{"id":"h5","text":"Quien cobra mantiene el dinero separado y no toca la comida.","icon":"HandCoins"},{"id":"h6","text":"Después de manejar dinero, se lava las manos con agua y jabón antes de tocar alimentos.","icon":"RefreshCcw"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s02-d5-taller-3"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:1.4.4"],"ambito":"emprender","title":"Etapa 1: escribe la oferta · 2 min","prompt":"Empieza tu hoja con el nombre del puesto y una oferta que puedas explicar en una sola oración.","type":"project","props":{"goal":"Definir una oferta sencilla y posible.","steps":[{"title":"Producto y precio · 1 min","detail":"Escribe qué ofrecerás y a qué precio."},{"title":"Por qué es posible · 1 min","detail":"Añade la necesidad, el recurso local y el saber familiar que reúne."}],"evidence":"Nombre del puesto y una oración de oferta con precio.","rubric":["La oferta dice qué se ofrece y a qué precio","Responde a una necesidad y usa un recurso y un saber disponibles"]},"id":"s02-d5-taller-4"},{"fase":"aplicar","areas":["cnt","l2"],"cnb":["cnt:1.5.3","l2:2.1.1"],"ambito":"hacer","title":"Etapa 2: procedimiento de higiene · 4 min","prompt":"Debajo de la oferta, escribe el procedimiento breve que recuperaste. No agregues cuidados que no fueron enseñados.","type":"project","props":{"goal":"Dejar una secuencia clara que otra persona pueda seguir.","steps":[{"title":"Materiales","detail":"Anota jabón, agua apta para consumo, recipientes con tapa, un cuchillo para uso de una persona adulta y un lugar separado para el dinero."},{"title":"Cinco pasos","detail":"Como preparación, separa el dinero de la comida y asigna quién cobra. **Primero**, antes de preparar, lávense las manos con agua y jabón. **Después**, una persona adulta lava el alimento con agua apta para consumo y usa el cuchillo. **Luego**, sirve y mantén el alimento tapado. **A continuación**, cobra sin tocar la comida y mantén el dinero separado. **Finalmente**, después de manejar dinero, lávate las manos con agua y jabón antes de tocar alimentos."}],"evidence":"Materiales y cinco pasos breves con palabras de orden.","rubric":["Incluye lavarse las manos antes de preparar, agua apta para consumo, dinero separado de la comida, cuchillo reservado para una persona adulta, alimento tapado y lavado de manos después de manejar dinero","Los cinco pasos usan palabras de orden y se pueden seguir sin adivinar"]},"id":"s02-d5-taller-5"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:1.3.1"],"ambito":"convivir","prompt":"Antes de escribir · 1 min. ¿Qué estructura sirve para atender con respeto a una persona mayor?","explain":"El servicio respetuoso saluda, ofrece con claridad y cierra con agradecimiento.","type":"choice","props":{"options":[{"id":"a","text":"“Buenos días, doña Rosa. ¿En qué le puedo servir?” · oferta · “Gracias”"},{"id":"b","text":"“¿Qué quiere?” · precio · silencio"},{"id":"c","text":"“Ey, vos” · oferta · “Apúrese”"}],"correct":["a"]},"id":"s02-d5-taller-6"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:1.3.1"],"ambito":"convivir","title":"Etapa 3: lenguaje de servicio · 2 min","prompt":"Añade tres frases que realmente usarías al atender a una persona mayor o desconocida.","type":"project","props":{"goal":"Preparar un intercambio breve, claro y respetuoso.","steps":[{"title":"Saludo y oferta · 1 min","detail":"Escribe un saludo con usted y don o doña, y una frase para ofrecer el producto con por favor."},{"title":"Despedida · 1 min","detail":"Añade una despedida breve con gracias."}],"evidence":"Saludo, oferta y despedida.","rubric":["El saludo usa usted y un título","La oferta y la despedida usan por favor y gracias de manera natural"]},"id":"s02-d5-taller-7"},{"fase":"aplicar","areas":["pyd","cnt","l2"],"cnb":["pyd:1.4.4","cnt:1.5.3","l2:2.1.1","l2:1.3.1"],"ambito":"emprender","title":"Etapa 4: integra y revisa el plan final · 3 min","prompt":"Ordena lo que ya escribiste, corrige una cosa y entrega el **plan de tu puesto sano y respetuoso**.","type":"project","props":{"goal":"Entregar un plan breve, completo y realizable.","steps":[{"title":"Integra · 2 min","detail":"Coloca arriba la oferta; al centro, el procedimiento de higiene numerado que empieza con **primero**; y al final, las tres frases de servicio respetuoso."},{"title":"Corrige · 1 min","detail":"Revisa la rúbrica y corrige una sola cosa que falte o no se entienda."}],"evidence":"Una hoja con oferta simple, procedimiento de higiene y tres frases de servicio respetuoso.","rubric":["La oferta indica qué se ofrece, el precio y un recurso y saber disponibles","El procedimiento incluye lavarse las manos antes de preparar, agua apta para consumo, dinero separado de la comida, cuchillo para una persona adulta, alimento tapado y lavado de manos después de manejar dinero","El servicio usa usted, un título, por favor y gracias"]},"id":"s02-d5-taller-8"},{"fase":"aplicar","areas":["pyd","cnt","l2"],"cnb":["pyd:1.4.4","cnt:1.5.3","l2:2.1.1","l2:1.3.1"],"ambito":"hacer","prompt":"Revisión rápida · 1 min. Decide qué está listo y qué debes corregir en tu hoja.","explain":"La revisión comprueba solo los tres componentes pedidos y los cuidados ya aprendidos.","type":"sort","props":{"buckets":[{"id":"listo","label":"Listo","icon":"BadgeCheck"},{"id":"corregir","label":"Corregir","icon":"Pencil"}],"items":[{"id":"r1","text":"La oferta dice producto y precio","bucket":"listo"},{"id":"r2","text":"El procedimiento empieza con las manos limpias antes de preparar","bucket":"listo"},{"id":"r3","text":"La misma persona cobra y sirve sin volver a lavarse las manos","bucket":"corregir"},{"id":"r4","text":"El saludo usa usted y una palabra de cortesía","bucket":"listo"}]},"id":"s02-d5-taller-9"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["pyd","cnt","l2"],"cnb":["pyd:1.4.4","cnt:1.5.3","l2:2.1.1","l2:1.3.1"],"type":"reflection","props":{"statements":["Creé una oferta posible","Escribí un procedimiento completo y ordenado","Preparé frases de servicio respetuoso"],"commitments":["Me lavaré las manos antes de preparar alimentos y después de manejar dinero","Mantendré separados el dinero y la comida","Trataré a cada cliente con respeto"]},"id":"s02-d5-taller-10"}]}},{"missionId":"s02","version":"cnb-sexto-d36209ef35fb1184","lesson":{"id":"s02-l3-1","title":"At the market: fruits, vegetables and prices","icon":"ShoppingBasket","minutes":14,"gancho":"En el mercado de tu pueblo hay aguacates, mangos, tomates y cebollas. ¿Sabes decirlos en inglés?","objetivos":["Nombrar en inglés frutas y verduras del mercado","Formar el plural: one tomato, two tomatoes","Preguntar y decir precios: How much is it? It's ten quetzales."],"resumen":["Fruits: banana, mango, orange (naranja), avocado (aguacate). Vegetables: tomato, onion (cebolla), carrot (zanahoria), potato (papa), corn (maíz).","Plural: casi siempre se agrega -s (bananas, carrots). Tomato y potato agregan -es: tomatoes, potatoes. Mango acepta mangoes o mangos.","Números para precios: ten (10), eleven (11), twelve (12), fifteen (15), twenty (20).","How much is it? = ¿Cuánto cuesta? · It's five quetzales. = Cuesta cinco quetzales."],"media":{"id":"s02-l3-1-market","kind":"image","title":"The market stall","aspect":"16:9","alt":"Un puesto de mercado guatemalteco con canastos de frutas y verduras; cada canasto tiene un cartel con su nombre en inglés y su precio.","brief":"Ilustración colorida de un puesto de mercado guatemalteco bajo un toldo. Canastos con carteles de cartón escritos a mano, nombre en inglés y precio en quetzales: \\"bananas Q10\\", \\"mangoes Q12\\", \\"avocados Q15\\", \\"tomatoes Q8\\", \\"onions Q6\\", \\"carrots Q5\\", \\"potatoes Q7\\". Una vendedora con delantal sonríe detrás del puesto. Precios hipotéticos (no reales). Sin marcas. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"conocer","title":"One, two… plural!","prompt":"Para hablar de **más de uno**, el inglés cambia la palabra, igual que el español. Toca cada tarjeta.","type":"explain","props":{"icon":"Plus","body":"En inglés el adjetivo y el artículo no cambian: **the** tomato, **the** tomatoes. Solo cambia el sustantivo.","reveal":[{"icon":"Plus","front":"Regla general: + s","back":"one banana → two banana**s** · one carrot → three carrot**s** · one onion → four onion**s**."},{"icon":"AlertCircle","front":"Tomato y potato: + es","back":"one tomato → two tomato**es** · one potato → five potato**es**. Con **mango** se aceptan las dos formas: mango**es** o mango**s**."},{"icon":"Wheat","front":"Corn","back":"**Corn** se usa casi siempre sin plural, como \\"maíz\\": _I buy corn._ Para contar se dice **ears of corn** (mazorcas)."}]},"id":"s02-l3-1-1"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"conocer","prompt":"Muchas palabras en inglés se parecen al español. En el cartel dice **\\"avocados\\"**. ¿Qué venden en ese canasto?","explain":"**Avocado** = aguacate. Palabras como avocado, tomato y chocolate nacieron en el náhuatl, un idioma originario de México, y llegaron al inglés a través del español. Hoy aprenderás el vocabulario del mercado.","type":"choice","props":{"options":[{"id":"a","text":"Aguacates","icon":"Egg"},{"id":"b","text":"Zanahorias","icon":"Carrot","feedback":"Zanahoria se dice \\"carrot\\"."},{"id":"c","text":"Uvas","icon":"Grape","feedback":"Uva se dice \\"grape\\"."}],"correct":["a"]},"id":"s02-l3-1-2"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"conocer","title":"Fruits and vegetables","prompt":"Escucha y repite cada palabra en voz alta. Voltea la tarjeta para ver su significado y una pista de pronunciación.","media":{"id":"s02-l3-1-vocab","kind":"audio","title":"Fruits and vegetables","duration":40,"alt":"Una voz en inglés dice nombres de frutas y verduras.","brief":"Audio de 40 s. Voz adulta, inglés claro y pausado, sin música. Cada palabra dos veces con 1 s de pausa: \\"banana\\", \\"mango\\", \\"orange\\", \\"avocado\\", \\"tomato\\", \\"onion\\", \\"carrot\\", \\"potato\\", \\"corn\\". Luego: \\"one tomato, two tomatoes\\", \\"one potato, two potatoes\\"."},"type":"flashcards","props":{"cards":[{"icon":"Banana","front":"banana","back":"banano · \\"ba-NÁ-na\\""},{"icon":"Apple","front":"mango","back":"mango · \\"MÉIN-gou\\""},{"icon":"Citrus","front":"orange","back":"naranja · \\"Ó-rinch\\""},{"icon":"Egg","front":"avocado","back":"aguacate · \\"a-vo-KÁ-dou\\""},{"icon":"Cherry","front":"tomato","back":"tomate · \\"to-MÉI-tou\\""},{"icon":"Layers","front":"onion","back":"cebolla · \\"Á-nion\\""},{"icon":"Carrot","front":"carrot","back":"zanahoria · \\"KÉ-rot\\""},{"icon":"Salad","front":"potato","back":"papa · \\"po-TÉI-tou\\""},{"icon":"Wheat","front":"corn","back":"maíz · \\"korn\\""}]},"id":"s02-l3-1-3"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"conocer","title":"Numbers and prices","prompt":"Para comprar necesitas los números. Repite en voz alta. Toca cada tarjeta.","type":"explain","props":{"icon":"Coins","body":"Pregunta: **How much is it?** (¿Cuánto cuesta?) · Respuesta: **It's … quetzales.** Si es más de una cosa, también se dice **How much are they?**","reveal":[{"icon":"Hash","front":"1-10","back":"one, two, three, four, five, six, seven, eight, nine, **ten**"},{"icon":"Hash","front":"11-15","back":"**eleven** (11), **twelve** (12), **thirteen** (13), **fourteen** (14), **fifteen** (15)"},{"icon":"Hash","front":"16-20","back":"**sixteen** (16), **seventeen** (17), **eighteen** (18), **nineteen** (19), **twenty** (20)"},{"icon":"Info","front":"Truco","back":"Del 13 al 19 terminan en **-teen**: thir**teen**, four**teen**… Di la terminación con fuerza: \\"four-TEEN\\"."}]},"id":"s02-l3-1-4"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"hacer","title":"Worked example","prompt":"Mira cómo Rosa pregunta un precio en el puesto de la imagen.","type":"worked-example","props":{"icon":"ShoppingBasket","problem":"Rosa quiere mangos. El cartel dice \\"mangoes Q12\\". ¿Cómo pregunta y qué le responden?","steps":[{"text":"Rosa señala los mangos y pregunta: **\\"How much are the mangoes?\\"**","why":"Son varios mangos: \\"are\\" en lugar de \\"is\\"."},{"text":"La vendedora mira el cartel: Q12 = **twelve quetzales**."},{"text":"Responde: **\\"They're twelve quetzales.\\"** (They are = ellos/ellas son o están.)"}],"answer":"— How much are the mangoes? — **They're twelve quetzales.**","tip":"Una cosa: How much is it? → It's… · Varias: How much are they? → They're…"},"id":"s02-l3-1-5"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: une cada palabra en inglés con su significado.","hint":"Algunas se parecen al español (tomato, banana). Para las demás, repasa las tarjetas.","explain":"Onion = cebolla, carrot = zanahoria, potato = papa, orange = naranja, corn = maíz.","type":"match","props":{"leftTitle":"English","rightTitle":"Español","pairs":[{"id":"m1","left":"onion","right":"cebolla"},{"id":"m2","left":"carrot","right":"zanahoria"},{"id":"m3","left":"potato","right":"papa"},{"id":"m4","left":"orange","right":"naranja"},{"id":"m5","left":"corn","right":"maíz"}]},"id":"s02-l3-1-6"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"hacer","prompt":"Completa la lista de compras con el **plural** correcto.","explain":"Bananas y onions: + s. Tomatoes y potatoes: + es.","type":"fill-blank","props":{"text":"Shopping list: three [[bananas]], two [[onions]], four [[tomatoes]] and five [[potatoes]].","distractors":["tomatos","potatos","banana"]},"id":"s02-l3-1-7"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"hacer","prompt":"La vendedora dice: _\\"The avocados are **fifteen** quetzales.\\"_ Escribe el precio en número.","explain":"Fifteen = 15. Recuerda: los números del 13 al 19 terminan en -teen.","type":"number-input","props":{"answer":15,"unit":"quetzales","misconceptions":[{"value":50,"msg":"Fifty sería 50. Fifteen termina en -teen: es del 13 al 19."},{"value":5,"msg":"Five es 5. Fifteen es five + teen: 15."}]},"id":"s02-l3-1-8"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.1.2"],"ambito":"hacer","prompt":"Quieres saber cuánto cuesta **una piña** (pineapple). ¿Qué preguntas?","explain":"Es una sola piña: **How much is it?** o **How much is the pineapple?**","type":"choice","props":{"options":[{"id":"a","text":"How much is the pineapple?"},{"id":"b","text":"Where is the pineapple?","feedback":"\\"Where\\" pregunta dónde está, no cuánto cuesta."},{"id":"c","text":"How much are the pineapple?","feedback":"Es una sola piña: se usa \\"is\\", no \\"are\\"."}],"correct":["a"]},"id":"s02-l3-1-9"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.1.2"],"prompt":"Boleto de salida: completa en inglés. (—¿Cuánto cuesta? —Cuesta doce quetzales.)","type":"fill-blank","props":{"text":"— How [[much]] is it? — It's [[twelve]] quetzales.","distractors":["many","twenty"]},"id":"s02-l3-1-10"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.1.2"],"prompt":"¿Cuál es el plural correcto de **tomato**?","type":"choice","props":{"options":[{"id":"a","text":"tomatos"},{"id":"b","text":"tomatoes"},{"id":"c","text":"tomato"}],"correct":["b"]},"id":"s02-l3-1-11"}],"kind":"materia","area":"l3","day":2}},{"missionId":"s02","version":"cnb-sexto-9bb7fe8e9f149448","lesson":{"id":"s02-cnt-1","title":"Tipos de parásitos","icon":"Bug","minutes":14,"gancho":"Un piojo vive sobre el cuero cabelludo y una lombriz intestinal vive dentro del cuerpo. ¿Cómo se clasifican?","objetivos":["Diferenciar ectoparásitos y endoparásitos mediante su ubicación en el huésped"],"resumen":["Un parásito obtiene recursos de un huésped y puede dañarlo.","Los ectoparásitos viven sobre la superficie; los endoparásitos viven dentro.","No todo organismo pequeño es parásito y la clasificación no sustituye un diagnóstico."],"media":{"id":"s02-cnt-1-tipos-parasitos","kind":"diagram","title":"Parásitos por ubicación","aspect":"16:9","alt":"Silueta humana con un piojo señalado sobre el cabello y una lombriz intestinal señalada dentro del intestino.","brief":"Diagrama horizontal 1600×900. Silueta humana no explícita dividida en SUPERFICIE e INTERIOR. Mostrar piojo y garrapata fuera; lombriz intestinal y protozoo parásito genérico dentro. Rótulos grandes, contraste alto, escala no real y nota: ejemplos didácticos, no diagnóstico."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:1.5.1"],"title":"Huésped y parásito","prompt":"Un parásito vive en o sobre otro organismo, llamado huésped, y obtiene de él alimento o refugio.","type":"explain","props":{"icon":"Microscope","body":"La relación puede causar daño al huésped. La ubicación permite distinguir dos tipos principales."},"id":"s02-cnt-1-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.5.1"],"title":"Dos tipos","prompt":"Clasifica por el lugar donde vive el parásito.","type":"explain","props":{"icon":"ScanSearch","body":"**Ectoparásito:** sobre piel o cabello, como piojos y algunas garrapatas. **Endoparásito:** dentro del organismo, como lombrices intestinales y ciertos protozoos parásitos. Muchos protozoos no son parásitos."},"id":"s02-cnt-1-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.5.1"],"title":"Modelo de clasificación","prompt":"Usa ubicación y no tamaño o apariencia.","type":"worked-example","props":{"icon":"ListChecks","problem":"Un piojo está sobre el cabello; una lombriz vive en el intestino.","steps":[{"text":"Identifico el huésped."},{"text":"Ubico al organismo: superficie o interior."},{"text":"Superficie corresponde a ectoparásito; interior, a endoparásito."}],"answer":"Piojo: ectoparásito. Lombriz intestinal: endoparásito."},"id":"s02-cnt-1-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.5.1"],"prompt":"Clasifica los ejemplos por su ubicación en el huésped.","hint":"Ecto = afuera; endo = adentro.","explain":"La ubicación define la clasificación.","type":"sort","props":{"buckets":[{"id":"ecto","label":"Ectoparásito"},{"id":"endo","label":"Endoparásito"},{"id":"no","label":"No se describe como parásito"}],"items":[{"id":"a","text":"Piojo sobre el cabello","bucket":"ecto"},{"id":"b","text":"Lombriz en el intestino","bucket":"endo"},{"id":"c","text":"Ameba libre en un estanque","bucket":"no"},{"id":"d","text":"Garrapata adherida a la piel","bucket":"ecto"}]},"id":"s02-cnt-1-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:1.5.1"],"prompt":"Relaciona cada pista con el tipo de parásito.","hint":"Busca superficie o interior.","explain":"La pista espacial basta para clasificar, no para diagnosticar.","type":"match","props":{"pairs":[{"id":"a","left":"Sobre la piel","right":"Ectoparásito"},{"id":"b","left":"Dentro del intestino","right":"Endoparásito"},{"id":"c","left":"En el cabello","right":"Ectoparásito"}]},"id":"s02-cnt-1-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.5.1"],"prompt":"En una ficha didáctica, un organismo vive dentro de la sangre de su huésped. ¿Cómo se clasifica por ubicación?","type":"choice","props":{"options":[{"id":"a","text":"Endoparásito"},{"id":"b","text":"Ectoparásito"},{"id":"c","text":"No puede clasificarse porque es pequeño"}],"correct":["a"]},"id":"s02-cnt-1-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:1.5.1"],"prompt":"Clasifica nuevos escenarios sin asumir que todo ser microscópico es parásito.","type":"sort","props":{"buckets":[{"id":"ecto","label":"Ectoparásito"},{"id":"endo","label":"Endoparásito"},{"id":"ins","label":"Información insuficiente"}],"items":[{"id":"a","text":"Ácaro descrito sobre la piel del huésped","bucket":"ecto"},{"id":"b","text":"Organismo dentro del hígado del huésped","bucket":"endo"},{"id":"c","text":"Microorganismo observado en agua, sin huésped descrito","bucket":"ins"}]},"id":"s02-cnt-1-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.5.1"],"prompt":"¿Qué ejemplo corresponde a un ectoparásito?","type":"choice","props":{"options":[{"id":"a","text":"Una garrapata adherida a la piel"},{"id":"b","text":"Una lombriz dentro del intestino"},{"id":"c","text":"Un alga en una laguna"}],"correct":["a"]},"id":"s02-cnt-1-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:1.5.1"],"prompt":"Comprueba la clasificación de los tipos de parásitos.","type":"true-false","props":{"statements":[{"text":"Un endoparásito vive dentro del huésped.","answer":true},{"text":"Todo protozoo es un parásito.","answer":false,"why":"Hay protozoos de vida libre y también especies parásitas."},{"text":"La ubicación en superficie distingue a un ectoparásito.","answer":true}]},"id":"s02-cnt-1-9"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["cnt"],"cnb":["cnt:1.5.1"],"type":"reflection","props":{"statements":["Diferencié ectoparásitos y endoparásitos por su ubicación"]},"id":"s02-cnt-1-10"}],"kind":"materia","area":"cnt","day":1}},{"missionId":"s02","version":"cnb-sexto-8edd05af3c4edeec","lesson":{"id":"s02-cnt-2","title":"Seres de una célula y de muchas","icon":"Microscope","minutes":14,"gancho":"Una ameba realiza todas sus funciones con una célula; una persona necesita billones. ¿Cómo se organizan?","objetivos":["Organizar seres vivos en unicelulares y pluricelulares según su número y organización de células"],"resumen":["Los unicelulares tienen una célula que realiza todas las funciones vitales.","Los pluricelulares tienen muchas células especializadas que forman tejidos, órganos y sistemas.","Protozoo describe un grupo diverso de unicelulares; metazoo se refiere a animales pluricelulares."],"media":{"id":"s02-cnt-2-organizacion","kind":"diagram","title":"Una célula o muchas","aspect":"16:9","alt":"Una ameba de una célula comparada con un pez formado por muchas células especializadas.","brief":"Diagrama horizontal 1600×900. Izquierda: ameba rotulada UNICELULAR con una sola membrana y núcleo. Derecha: pez rotulado PLURICELULAR con ampliaciones de células musculares y nerviosas. Flechas a célula, tejido y órgano. Texto grande, contraste alto y escala didáctica declarada."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:2.1.1"],"title":"Número y organización","prompt":"Los seres vivos pueden estar formados por una célula o por muchas células coordinadas.","type":"explain","props":{"icon":"Microscope","body":"**Unicelular:** una célula cumple nutrición, relación y reproducción. **Pluricelular:** muchas células se especializan y cooperan."},"id":"s02-cnt-2-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.1"],"title":"Protozoos y metazoos","prompt":"Los términos describen formas de organización.","type":"explain","props":{"icon":"Microscope","body":"Los **protozoos** son organismos unicelulares; muchos viven libremente y algunos son parásitos. Los **metazoos** son animales pluricelulares, desde una lombriz hasta un jaguar."},"id":"s02-cnt-2-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.1"],"title":"Modelo de decisión","prompt":"Clasifica usando evidencia celular.","type":"worked-example","props":{"icon":"GitCompare","problem":"Una ameba tiene una célula; un pez presenta tejidos y órganos.","steps":[{"text":"Ameba: una célula realiza todas las funciones."},{"text":"Pez: muchas células especializadas forman tejidos y órganos."}],"answer":"Ameba: unicelular/protozoo. Pez: pluricelular/metazoo."},"id":"s02-cnt-2-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.1"],"prompt":"Clasifica por organización celular.","hint":"Una célula frente a tejidos y órganos.","explain":"La clasificación depende del número y coordinación de células.","type":"sort","props":{"buckets":[{"id":"uni","label":"Unicelular"},{"id":"plu","label":"Pluricelular"}],"items":[{"id":"a","text":"Ameba","bucket":"uni"},{"id":"b","text":"Paramecio","bucket":"uni"},{"id":"c","text":"Hormiga","bucket":"plu"},{"id":"d","text":"Planta de maíz","bucket":"plu"}]},"id":"s02-cnt-2-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.1"],"prompt":"Ordena la organización de un ser pluricelular.","hint":"Las células semejantes forman tejidos.","explain":"Célula, tejido, órgano, sistema y organismo.","type":"order","props":{"items":[{"id":"a","text":"Célula"},{"id":"b","text":"Tejido"},{"id":"c","text":"Órgano"},{"id":"d","text":"Sistema"},{"id":"e","text":"Organismo"}]},"id":"s02-cnt-2-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.1.1"],"prompt":"Un ser microscópico tiene una sola célula que se mueve y obtiene alimento. ¿Qué evidencia permite clasificarlo?","type":"choice","props":{"options":[{"id":"a","text":"Es unicelular porque una célula realiza sus funciones"},{"id":"b","text":"Es pluricelular porque es pequeño"},{"id":"c","text":"Es metazoo porque se mueve"}],"correct":["a"]},"id":"s02-cnt-2-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.1.1"],"prompt":"Relaciona cada descripción nueva con su organización.","type":"match","props":{"pairs":[{"id":"a","left":"Levadura: una célula","right":"Unicelular"},{"id":"b","left":"Árbol: raíces, tallo y hojas con tejidos","right":"Pluricelular"},{"id":"c","left":"Protozoo: una célula funcional","right":"Unicelular"}]},"id":"s02-cnt-2-7"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:2.1.1"],"prompt":"¿Qué rasgo distingue a un ser pluricelular?","type":"choice","props":{"options":[{"id":"a","text":"Muchas células especializadas y coordinadas"},{"id":"b","text":"Una única célula que hace todo"},{"id":"c","text":"Ser necesariamente microscópico"}],"correct":["a"]},"id":"s02-cnt-2-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:2.1.1"],"prompt":"Comprueba la organización de seres vivos.","type":"true-false","props":{"statements":[{"text":"Un protozoo es unicelular.","answer":true},{"text":"Todo organismo microscópico causa enfermedad.","answer":false},{"text":"Los metazoos son animales pluricelulares.","answer":true}]},"id":"s02-cnt-2-9"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["cnt"],"cnb":["cnt:2.1.1"],"type":"reflection","props":{"statements":["Organicé seres vivos en unicelulares y pluricelulares"]},"id":"s02-cnt-2-10"}],"kind":"materia","area":"cnt","day":3}},{"missionId":"s02","version":"cnb-sexto-7b6fee26af39f2ed","lesson":{"id":"s02-l2-2","title":"Sigo instrucciones paso a paso","icon":"ListOrdered","minutes":14,"gancho":"Tu tío armó una mesa sin leer las instrucciones… y le sobraron cuatro tornillos. ¿Qué crees que pasó?","objetivos":["Reconocer las partes de un texto de instrucciones","Usar las palabras de orden y los verbos que indican qué hacer","Seguir instrucciones escritas o dibujadas en el orden correcto"],"resumen":["Un instructivo tiene: título (qué vas a lograr), materiales y pasos en orden.","Los pasos usan verbos que indican una acción: lava, corta, mezcla (o lavar, cortar, mezclar).","Las palabras de orden guían la secuencia: primero, después, luego, a continuación, finalmente.","Las instrucciones también pueden darse con dibujos, flechas y números. Lee o mira todo antes de empezar y sigue el orden.","Al preparar alimentos para un puesto: quienes servirán se lavan las manos con agua y jabón antes de empezar; una persona adulta lava el alimento con agua apta para consumo y usa el cuchillo; la comida se mantiene tapada y el dinero permanece separado; quien cobra no toca comida y vuelve a lavarse las manos antes de cambiar a servir."],"media":{"id":"s02-l2-2-cartel-manos","kind":"diagram","title":"Cartel: procedimiento para servir fruta","aspect":"3:4","alt":"Cartel con seis dibujos numerados: separar la caja del alimento, lavarse las manos, una persona adulta corta fruta, tapar los vasos, cobrar sin tocar comida y volver a lavarse antes de servir.","brief":"Ilustración vertical tipo cartel de mercado escolar, estilo plano y claro. Seis viñetas numeradas con flechas y frases breves: (1) caja de dinero lejos de la mesa de alimento y roles de cobro y servicio señalados, (2) manos con agua y jabón, (3) una persona adulta corta fruta con cuchillo y tabla limpios mientras un niño observa a distancia, (4) vasos de fruta cubiertos y una mosca fuera de la tapa, (5) una persona cobra sin tocar la comida, (6) esa persona se lava las manos con agua y jabón antes de pasar a servir. Sin marcas comerciales. Dimensiones: 900x1200. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:2.1.1"],"ambito":"conocer","title":"Las partes de un instructivo","prompt":"Un **instructivo** es un texto que te dice **cómo hacer algo** paso a paso. Toca cada parte.","type":"explain","props":{"icon":"ClipboardList","body":"Antes de empezar: **lee o mira todo** una vez. Después, sigue los pasos **uno por uno, en orden**.","reveal":[{"icon":"Target","front":"Título","back":"Dice qué vas a lograr: \\"Cómo sembrar frijol en un vaso\\"."},{"icon":"Package","front":"Materiales","back":"La lista de lo que necesitas. Reúnelo todo antes de empezar."},{"icon":"ListOrdered","front":"Pasos numerados","back":"Cada paso es una acción. El número indica el orden."},{"icon":"Hand","front":"Verbos de acción","back":"Indican qué hacer: **lava, corta, dobla, mezcla** (o **lavar, cortar, doblar, mezclar**). Suelen ir al inicio del paso."},{"icon":"ArrowRight","front":"Palabras de orden","back":"**Primero, después, luego, a continuación, finalmente.** Te ayudan a no perderte."}]},"id":"s02-l2-2-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.1.1"],"ambito":"conocer","prompt":"Tu tío armó una mesa sin leer las instrucciones y le sobraron cuatro tornillos. ¿Qué error cometió probablemente?","explain":"Las instrucciones sirven si se **leen completas** y se siguen **en orden**. Hoy aprenderás a leerlas y seguirlas como un experto.","type":"choice","props":{"options":[{"id":"a","text":"Se saltó pasos por no leer todo antes de empezar","icon":"ListChecks"},{"id":"b","text":"La mesa venía con tornillos de sobra a propósito","icon":"Package","feedback":"A veces pasa, pero cuatro tornillos de más suelen indicar pasos que faltaron."}],"correct":["a"]},"id":"s02-l2-2-2"},{"fase":"construir","areas":["l2","cnt"],"cnb":["l2:2.1.1","cnt:1.5.3"],"ambito":"hacer","title":"Ejemplo resuelto: un procedimiento seguro","prompt":"Mira cómo el equipo convierte los dibujos del cartel en instrucciones claras para servir fruta.","type":"worked-example","props":{"icon":"ClipboardCheck","problem":"El puesto necesita evitar que las manos, las moscas, el cuchillo y el dinero contaminen la comida. ¿Cómo escribe el equipo un procedimiento que cualquiera pueda seguir?","steps":[{"text":"Anota los materiales y organiza dos lugares: la caja del **dinero queda separada** de la comida.","why":"Preparar materiales y roles antes de empezar evita cruces durante el servicio."},{"text":"**Primero**, todas las personas que servirán se lavan las manos con agua y jabón."},{"text":"**Después**, una **persona adulta** lava la fruta con agua apta para consumo y la corta con tabla y cuchillo limpios.","why":"El cuchillo lo maneja una persona adulta."},{"text":"**Luego**, se sirve la fruta en recipientes limpios y se mantiene **tapada para protegerla de las moscas**."},{"text":"**Finalmente**, una persona cobra y no toca los alimentos. Si cambia de tarea, se **lava otra vez las manos con agua y jabón** antes de servir.","why":"El dinero permanece lejos de la comida y quien lo toca se limpia las manos antes de manipular alimentos."}],"answer":"El instructivo exige lavarse las manos antes de preparar, usar agua apta para consumo, separar dinero y comida, reservar el cuchillo para una persona adulta, mantener la fruta tapada y volver a lavarse las manos después de manejar dinero.","tip":"Cada paso empieza con un verbo y deja claro quién realiza la acción."},"id":"s02-l2-2-3"},{"fase":"construir","areas":["l2","cnt"],"cnb":["l2:2.1.1","cnt:1.5.3"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: **ordena el procedimiento** para preparar y servir fruta en el puesto.","hint":"Primero organiza los lugares y lávate las manos. La comida se tapa antes de empezar a cobrar.","explain":"El orden protege la comida: dinero separado → manos lavadas → una persona adulta corta → comida tapada → cobro sin tocar alimentos → nuevo lavado de manos si se cambia de tarea.","media":{"id":"s02-l2-2-cartel-paso","kind":"image","title":"Detalle del cartel","aspect":"4:3","alt":"Las seis viñetas del procedimiento para servir fruta, desordenadas y sin números.","brief":"Las mismas seis viñetas del cartel de procedimiento para servir fruta, sin números y desordenadas en una cuadrícula de 3×2. Cada viñeta conserva sus objetos y acciones, pero no incluye palabras de orden. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"h1","text":"Separa el dinero de la comida y asigna quién cobra","icon":"BadgeDollarSign"},{"id":"h2","text":"Lávate las manos con agua y jabón antes de tocar alimentos","icon":"HandHelping"},{"id":"h3","text":"Pide a una persona adulta que corte la fruta con cuchillo y tabla limpios","icon":"UtensilsCrossed"},{"id":"h4","text":"Sirve la fruta en recipientes limpios y tápala para protegerla de las moscas","icon":"Container"},{"id":"h5","text":"Cobra sin tocar la comida y mantén el dinero lejos de los alimentos","icon":"HandCoins"},{"id":"h6","text":"Si dejas de cobrar para servir, lávate otra vez las manos con agua y jabón","icon":"RefreshCcw"}]},"id":"s02-l2-2-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:2.1.1"],"ambito":"hacer","prompt":"Toca las **palabras de orden** de estas instrucciones.","hint":"Son palabras que dicen \\"cuándo\\" va cada paso. Hay 4.","explain":"\\"Primero\\", \\"después\\", \\"luego\\" y \\"finalmente\\" ordenan los pasos. Sin ellas, sería fácil confundirse.","type":"highlight","props":{"target":"palabras de orden","text":"Cómo hacer un barquito de papel. {Primero}, dobla una hoja por la mitad. {Después}, dobla las dos esquinas de arriba hacia el centro. {Luego}, sube las orillas de abajo. {Finalmente}, abre el centro y aplánalo con cuidado."},"id":"s02-l2-2-5"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:2.1.1"],"ambito":"hacer","title":"Lectura","prompt":"Lee este instructivo y responde.","type":"reading","props":{"genre":"Instructivo","heading":"Cómo hacer un germinador de frijol","passage":"Materiales: un vaso transparente, algodón o papel de cocina, cinco frijoles y agua.\\n\\n1. Primero, llena el vaso con algodón hasta la mitad.\\n\\n2. Después, coloca los frijoles entre el algodón y la pared del vaso, para poder verlos.\\n\\n3. Luego, humedece el algodón con un poco de agua. No lo llenes de agua: solo debe quedar húmedo.\\n\\n4. A continuación, pon el vaso cerca de una ventana donde entre luz.\\n\\n5. Finalmente, revisa tus frijoles todos los días y agrega unas gotas de agua si el algodón se seca.","questions":[{"q":"¿Qué debes hacer **inmediatamente después** de colocar los frijoles?","options":[{"id":"a","text":"Humedecer el algodón"},{"id":"b","text":"Poner el vaso cerca de la ventana"},{"id":"c","text":"Llenar el vaso con algodón"}],"correct":"a","why":"El paso 3, que empieza con \\"Luego\\", dice que se humedece el algodón."},{"q":"¿Por qué el instructivo dice \\"No lo llenes de agua\\"?","options":[{"id":"a","text":"Porque el algodón solo debe quedar húmedo"},{"id":"b","text":"Porque los frijoles necesitan mucha agua"},{"id":"c","text":"Porque el vaso se puede quebrar"}],"correct":"a","why":"Es una advertencia: aclara cómo hacer bien el paso."},{"q":"¿Qué pasaría si alguien pone el vaso en un armario oscuro?","options":[{"id":"a","text":"No estaría siguiendo el paso 4"},{"id":"b","text":"Estaría siguiendo todas las instrucciones"},{"id":"c","text":"Terminaría más rápido el instructivo"}],"correct":"a","why":"El paso 4 pide un lugar con luz. Saltarse o cambiar un paso puede arruinar el resultado."}]},"id":"s02-l2-2-6"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:2.1.1"],"ambito":"hacer","prompt":"El maestro de Educación Física da estas instrucciones: _\\"Cuando suene el silbato **una vez**, caminen. Cuando suene **dos veces**, deténganse. Cuando suene **tres veces**, siéntense.\\"_ Estás caminando y el silbato suena **dos veces**. ¿Qué haces?","explain":"Dos silbatazos = deténganse. Seguir instrucciones también es escuchar bien cada condición.","type":"choice","props":{"options":[{"id":"a","text":"Me detengo"},{"id":"b","text":"Me siento","feedback":"Sentarse es con tres silbatazos."},{"id":"c","text":"Sigo caminando","feedback":"Caminar es con un silbatazo. Con dos hay que detenerse."}],"correct":["a"]},"id":"s02-l2-2-7"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:2.1.1"],"ambito":"hacer","prompt":"Escribe instrucciones para algo sencillo que sabes hacer (servir un vaso de agua pura, sembrar una semilla, doblar tu ropa…). Usa **3 o 4 pasos**, un **verbo de acción** en cada uno y **palabras de orden**.","type":"short-answer","props":{"minWords":25,"placeholder":"Cómo… Primero, …","model":"Cómo doblar una camisa. Primero, extiende la camisa sobre la cama con los botones hacia abajo. Después, dobla las mangas hacia el centro. Luego, dobla la camisa por la mitad, de abajo hacia arriba. Finalmente, guárdala en tu gaveta.","rubric":["Tiene un título que dice qué se va a lograr","Cada paso empieza con un verbo de acción","Usé al menos tres palabras de orden","Los pasos están en el orden correcto"]},"id":"s02-l2-2-8"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:2.1.1"],"prompt":"Boleto de salida: ordena las instrucciones para sembrar una semilla en una maceta.","type":"order","props":{"labels":{"start":"Primero","end":"Finalmente"},"items":[{"id":"q1","text":"Llena la maceta con tierra"},{"id":"q2","text":"Haz un agujerito con el dedo"},{"id":"q3","text":"Pon la semilla y tápala con tierra"},{"id":"q4","text":"Riega con poca agua"}]},"id":"s02-l2-2-9"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:2.1.1"],"prompt":"¿Cuál es una instrucción **clara** para un instructivo?","type":"choice","props":{"options":[{"id":"a","text":"Después, corta el papel en cuatro partes iguales."},{"id":"b","text":"El papel es bonito y de colores."},{"id":"c","text":"Ayer corté papel con mi hermana."}],"correct":["a"]},"id":"s02-l2-2-10"},{"fase":"reflexionar","areas":["l2"],"cnb":[],"ambito":"ser","prompt":"¿Cómo te fue esta semana?","type":"reflection","props":{"statements":["Uso saludos, \\"por favor\\", \\"gracias\\" y \\"con permiso\\"","Escribo bien los títulos abreviados (Sr., Dra., Lic.)","Sigo instrucciones escritas o dibujadas en orden"],"commitments":["Saludaré con respeto a las personas que me atienden","Preguntaré en mi familia cómo se muestra respeto en nuestro idioma","Leeré todas las instrucciones antes de empezar una tarea"]},"id":"s02-l2-2-11"}],"kind":"materia","area":"l2","day":4}},{"missionId":"s02","version":"cnb-sexto-7519c9483dc9052d","lesson":{"id":"s02-l1-3","title":"Leer para estudiar: datos, listas y tablas","icon":"ClipboardList","minutes":14,"gancho":"Si alguien te pregunta qué día hay mercado en Chichicastenango, ¿lees todo un libro o buscas rápido el dato?","objetivos":["Localizar datos en textos de estudio de distintas materias","Leer una tabla por filas y columnas","Usar negritas, listas y subtítulos como guías de lectura"],"resumen":["En los textos de estudio, los subtítulos, las negritas y las listas te guían: te dicen dónde está cada información.","Para buscar un dato no hace falta leer todo con detalle: primero ubica la parte donde está (lectura de búsqueda) y luego lee esa parte con atención.","Una tabla organiza datos en filas (horizontales) y columnas (verticales). El dato está donde se cruzan la fila y la columna que te interesan."],"media":{"id":"s02-l1-3-tabla","kind":"diagram","title":"Cómo se lee una tabla","aspect":"16:9","alt":"Tabla de tres columnas (Mercado, Departamento, Días principales) con una fila resaltada en amarillo y una columna resaltada en celeste; en su cruce, una estrella marca el dato buscado.","brief":"Diagrama animable de una tabla sencilla con encabezados \\"Mercado\\", \\"Departamento\\", \\"Días principales\\" y tres filas: Chichicastenango | El Quiché | jueves y domingo; San Francisco El Alto | Totonicapán | viernes; Sololá | Sololá | martes y viernes. Resaltar la fila \\"Chichicastenango\\" en amarillo y la columna \\"Días principales\\" en celeste; en el cruce, una estrella y el rótulo \\"¡Aquí está el dato!\\". Flechas: \\"fila →\\", \\"columna ↓\\". Estilo plano, legible en teléfono. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:4.2.1"],"ambito":"conocer","title":"Las guías de un texto de estudio","prompt":"Los textos de estudio tienen **señales** que te ayudan a encontrar la información. Toca cada tarjeta.","type":"explain","props":{"icon":"Signpost","body":"Leer para estudiar tiene dos velocidades: **rápida** para ubicar dónde está la información y **lenta** para entenderla bien.","reveal":[{"icon":"Heading","front":"Títulos y subtítulos","back":"Dividen el texto en partes. Leyéndolos sabes en qué parte está lo que buscas."},{"icon":"Bold","front":"Negritas","back":"Las palabras en **negrita** son las más importantes: conceptos, nombres, fechas."},{"icon":"List","front":"Listas con viñetas","back":"Presentan varios elementos de forma ordenada: pasos, características, ejemplos."},{"icon":"Table","front":"Tablas","back":"Organizan datos en **filas** (horizontales →) y **columnas** (verticales ↓). El dato está en el cruce."}]},"id":"s02-l1-3-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:4.2.1"],"ambito":"conocer","prompt":"Tienes un libro de Ciencias Sociales de 200 páginas y necesitas saber **en qué departamento está San Francisco El Alto**. ¿Qué haces?","explain":"Para buscar un dato no se lee todo el libro: se usan las guías del texto (índice, subtítulos, negritas, tablas) para ir directo a la parte que sirve.","type":"choice","props":{"options":[{"id":"a","text":"Leo el libro completo desde la página 1","icon":"BookOpen","feedback":"Funcionaría… ¡pero tardarías días! Hay formas más rápidas."},{"id":"b","text":"Busco un subtítulo, una lista o una tabla sobre los municipios o mercados","icon":"Search"},{"id":"c","text":"Adivino","icon":"HelpCircle","feedback":"Adivinar no es investigar. Busca el dato en el texto."}],"correct":["b"]},"id":"s02-l1-3-2"},{"fase":"construir","areas":["l1","ccss"],"cnb":["l1:4.2.1"],"ambito":"conocer","prompt":"Lee este texto de Ciencias Sociales. Usa los **subtítulos y la lista** para encontrar rápido cada respuesta.","hint":"Primero mira los subtítulos y decide en qué parte está cada respuesta.","type":"reading","props":{"genre":"Texto expositivo (Ciencias Sociales)","heading":"Los mercados de Guatemala","passage":"**¿Qué es un día de mercado?**\\n\\nEn muchos pueblos de Guatemala, el mercado no abre igual todos los días. Hay **días de mercado**, en los que llegan vendedores y compradores de aldeas y municipios cercanos. Esos días, la plaza se llena de colores, voces y olores.\\n\\n**Algunos mercados conocidos**\\n\\n• **Chichicastenango** (El Quiché): jueves y domingo.\\n• **San Francisco El Alto** (Totonicapán): viernes; es famoso por su gran tamaño.\\n• **Sololá** (Sololá): martes y viernes.\\n\\n**Más que comprar y vender**\\n\\nEn el mercado también se encuentran familias, se comparten noticias y se hablan distintos idiomas, como el k'iche', el kaqchikel y el español. Por eso, el mercado es un lugar de **intercambio cultural**, no solo de productos.","questions":[{"q":"¿Qué días hay mercado en Chichicastenango?","options":[{"id":"a","text":"Jueves y domingo"},{"id":"b","text":"Martes y viernes"},{"id":"c","text":"Solo viernes"}],"correct":"a","why":"Está en la lista, bajo el subtítulo \\"Algunos mercados conocidos\\"."},{"q":"¿Bajo qué subtítulo buscarías **por qué el mercado es importante para la cultura**?","options":[{"id":"a","text":"\\"Más que comprar y vender\\""},{"id":"b","text":"\\"Algunos mercados conocidos\\""},{"id":"c","text":"\\"¿Qué es un día de mercado?\\""}],"correct":"a","why":"Ese subtítulo anuncia que el mercado es algo más que un lugar de compras."},{"q":"Según el texto, ¿qué significa que el mercado sea un lugar de **intercambio cultural**?","options":[{"id":"a","text":"Que ahí se comparten noticias, costumbres e idiomas, además de productos"},{"id":"b","text":"Que solo se venden artesanías"},{"id":"c","text":"Que solo llegan turistas"}],"correct":"a","why":"El último párrafo lo explica: familias que se encuentran, noticias e idiomas."}]},"id":"s02-l1-3-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:4.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: leer una tabla","prompt":"Supongamos que una escuela anotó los **precios de algunas verduras** en dos mercados. Mira cómo se encuentra un dato.","type":"worked-example","props":{"icon":"Table","problem":"Tabla (datos supuestos):\\n\\nVerdura | Mercado A | Mercado B\\nTomate (libra) | Q5 | Q4\\nGüisquil (unidad) | Q2 | Q3\\nCebolla (libra) | Q6 | Q6\\n\\n¿Cuánto cuesta el güisquil en el Mercado B?","steps":[{"text":"Leo el **título de las columnas**: Verdura, Mercado A, Mercado B.","why":"Así sé qué información hay en cada columna."},{"text":"Busco la **fila** del güisquil (horizontal →)."},{"text":"Busco la **columna** del Mercado B (vertical ↓)."},{"text":"Leo el dato donde se **cruzan**: Q3."}],"answer":"El güisquil cuesta **Q3** la unidad en el Mercado B.","tip":"Fila + columna = dato. Pon un dedo en la fila y otro en la columna, y júntalos."},"id":"s02-l1-3-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:4.2.1"],"ambito":"hacer","prompt":"Con la misma tabla del ejemplo: ¿en qué mercado el **tomate** es más barato?","hint":"Busca la fila del tomate y compara las dos columnas de mercados.","explain":"En la fila del tomate: Mercado A = Q5 y Mercado B = Q4. Es más barato en el B.","type":"choice","props":{"options":[{"id":"a","text":"En el Mercado A","feedback":"En el Mercado A cuesta Q5; en el B, Q4."},{"id":"b","text":"En el Mercado B"},{"id":"c","text":"Cuesta igual en los dos","feedback":"La que cuesta igual en ambos es la cebolla."}],"correct":["b"]},"id":"s02-l1-3-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:4.2.1"],"ambito":"hacer","prompt":"Observa la tabla del diagrama principal (mercados y días). ¿Verdadero o falso?","explain":"Para responder, cruza la fila de cada mercado con la columna \\"Días principales\\".","type":"true-false","props":{"statements":[{"text":"San Francisco El Alto está en Totonicapán.","answer":true},{"text":"Sololá tiene mercado los domingos.","answer":false,"why":"En la tabla, Sololá tiene martes y viernes."},{"text":"Los viernes hay mercado tanto en San Francisco El Alto como en Sololá.","answer":true}]},"id":"s02-l1-3-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:4.2.1"],"ambito":"hacer","prompt":"Piensa en el mercado o la tienda más cercana a tu casa. Haz una **tabla pequeña** con tres productos y su precio aproximado (pregunta en casa o recuerda). Usa columnas: Producto | Precio | Unidad (libra, unidad, manojo…). Después escribe una oración sobre algo que notes en tu tabla.","type":"short-answer","props":{"minWords":15,"placeholder":"Producto | Precio | Unidad\\n… | … | …\\n\\nOración: …","model":"Producto | Precio | Unidad\\nFrijol negro | Q8 | libra\\nAguacate | Q5 | unidad\\nCilantro | Q2 | manojo\\n\\nOración: El frijol es el más caro de mi tabla, pero se compra por libra y rinde para varios días.","rubric":["Mi tabla tiene títulos en las columnas","Cada fila tiene producto, precio y unidad","Escribí una oración que usa los datos de la tabla"]},"id":"s02-l1-3-7"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:4.2.1"],"prompt":"En una tabla, ¿dónde está el dato que buscas?","type":"choice","props":{"options":[{"id":"a","text":"Donde se cruzan la fila y la columna que te interesan"},{"id":"b","text":"Siempre en la primera fila"},{"id":"c","text":"Debajo de la tabla, en letra pequeña"}],"correct":["a"]},"id":"s02-l1-3-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:4.2.1"],"prompt":"Un libro de Ciencias Naturales tiene los subtítulos: \\"Partes de la planta\\", \\"Cómo se alimentan las plantas\\" y \\"Plantas medicinales de Guatemala\\". ¿En cuál buscarías qué es la **fotosíntesis**?","type":"choice","props":{"options":[{"id":"a","text":"\\"Cómo se alimentan las plantas\\""},{"id":"b","text":"\\"Partes de la planta\\""},{"id":"c","text":"\\"Plantas medicinales de Guatemala\\""}],"correct":["a"]},"id":"s02-l1-3-9"}],"kind":"materia","area":"l1","day":3}},{"missionId":"s02","version":"cnb-sexto-034157f6a40f6a7a","lesson":{"id":"s02-ef-1","title":"Acelerar y frenar con control","icon":"Gauge","minutes":15,"gancho":"Cuando juegas tenta, ganas si arrancas rápido… y no te caes si sabes frenar. ¿Cómo lo hace tu cuerpo?","objetivos":["Percibir la aceleración (ir cada vez más rápido) y la desaceleración (ir cada vez más lento)","Aplicar la técnica de salida y de frenado seguro","Controlar los cambios de velocidad en juegos de carrera"],"resumen":["Acelerar es aumentar la velocidad poco a poco; desacelerar es disminuirla hasta detenerse.","Para acelerar: cuerpo inclinado hacia adelante, pasos cortos y rápidos al inicio que se van alargando, brazos que se mueven fuerte de adelante hacia atrás.","Para frenar con seguridad: pasos cortos, bajar el centro de gravedad doblando las rodillas (flexión), tronco un poco hacia atrás y apoyar todo el pie.","Un frenado brusco con las piernas rectas puede provocar caídas y lastimar rodillas y tobillos."],"media":{"id":"s02-ef-1-frenado","kind":"video","title":"Arrancar y frenar","aspect":"9:16","duration":45,"alt":"Una niña arranca inclinada hacia adelante con pasos cortos que se alargan; luego frena con pasos cortos, rodillas dobladas y tronco un poco hacia atrás, sin resbalar.","brief":"Video vertical de 45 s en el patio de una escuela pública, suelo de cemento seco. Parte 1 \\"Acelera\\": salida de pie con un pie adelante, cuerpo inclinado, braceo fuerte; cámara lateral y rótulos \\"pasos cortos → pasos largos\\". Parte 2 \\"Desacelera\\": cámara lenta del frenado en 4-5 pasos cortos, rodillas flexionadas, tronco ligeramente atrás; rótulo \\"baja tu centro\\". Parte 3: contraejemplo breve (animado, no real) de frenado con piernas rectas y resbalón, con una X roja. Aviso: \\"Practica en suelo seco y despejado\\". Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:1.3.3"],"ambito":"conocer","title":"Acelerar y desacelerar","prompt":"La **velocidad** es qué tan rápido te mueves. Cuando cambia, sientes el cambio en todo el cuerpo. Toca cada tarjeta.","type":"explain","props":{"icon":"Gauge","body":"Percibir tu propia velocidad te ayuda a **controlar** tu cuerpo en juegos y deportes.","reveal":[{"icon":"TrendingUp","front":"Aceleración","back":"Aumentar la velocidad **poco a poco**. Sientes que el cuerpo \\"se va hacia adelante\\" y que tus pasos se alargan."},{"icon":"TrendingDown","front":"Desaceleración","back":"Disminuir la velocidad hasta detenerte. Sientes que el cuerpo \\"quiere seguir\\" y debes frenarlo."},{"icon":"Timer","front":"Velocidad constante","back":"Mantener el mismo ritmo, como en un trote largo. Tus pasos son iguales y regulares."}]},"id":"s02-ef-1-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.3.3"],"ambito":"conocer","prompt":"Una camioneta sale de la parada. ¿Cómo cambia su velocidad en los primeros segundos?","explain":"Va **aumentando la velocidad poco a poco**: está **acelerando**. Al llegar a la siguiente parada hace lo contrario: **desacelera**. Tu cuerpo hace lo mismo al correr.","type":"choice","props":{"options":[{"id":"a","text":"Arranca a toda velocidad de golpe","icon":"Zap","feedback":"Nada pasa de quieto a muy rápido de golpe: la velocidad aumenta poco a poco."},{"id":"b","text":"Aumenta la velocidad poco a poco","icon":"TrendingUp"},{"id":"c","text":"Siempre va a la misma velocidad","icon":"Minus","feedback":"Al salir de la parada su velocidad cambia: empieza en cero."}],"correct":["b"]},"id":"s02-ef-1-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.3.3","ef:1.3.6"],"ambito":"hacer","title":"La técnica: salir y frenar","prompt":"Mira el video y toca cada tarjeta. Fíjate en las **rodillas** y en la **inclinación del cuerpo**.","type":"explain","props":{"icon":"Footprints","body":"Frenar bien es tan importante como arrancar rápido: **evita caídas y lesiones**.","reveal":[{"icon":"ArrowRight","front":"Salida","back":"Un pie adelante y otro atrás, rodillas un poco dobladas, **cuerpo inclinado hacia adelante**. Empuja fuerte con el pie de atrás."},{"icon":"TrendingUp","front":"Acelerar","back":"Primeros pasos **cortos y rápidos**, que se van **alargando**. Mueve los brazos con fuerza, codos doblados, de adelante hacia atrás."},{"icon":"ArrowDown","front":"Frenar","back":"Pasos **cortos**, **dobla las rodillas** (flexión) para bajar tu centro de gravedad y lleva el tronco **un poco hacia atrás**."},{"icon":"X","front":"Error frecuente","back":"Frenar de golpe con las **piernas rectas**: el cuerpo sigue hacia adelante, puedes resbalar y lastimarte rodillas o tobillos."}]},"id":"s02-ef-1-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.3.3"],"ambito":"hacer","title":"Ejemplo resuelto: la carrera del mandado","prompt":"Mira cómo María planifica una carrera de 20 pasos que termina en una línea donde debe detenerse sin pasarse.","type":"worked-example","props":{"icon":"Route","problem":"María debe correr hasta la tienda (a 20 pasos) y detenerse **justo** en la línea de la puerta, sin pasarse ni caerse.","steps":[{"text":"**Pasos 1-5:** sale inclinada hacia adelante, con pasos cortos y rápidos: **acelera**."},{"text":"**Pasos 6-14:** ya va rápido; mantiene la velocidad con pasos largos y braceo."},{"text":"**Pasos 15-20:** empieza a **desacelerar** antes de llegar: acorta los pasos, dobla las rodillas y lleva el tronco un poco atrás.","why":"Si espera hasta la línea para frenar, su cuerpo seguirá de largo."},{"text":"Se detiene en la línea con **ambos pies firmes** y rodillas dobladas."}],"answer":"María **acelera** al inicio, **mantiene** en el medio y **desacelera con anticipación** para detenerse con control.","tip":"Mientras más rápido vas, antes debes empezar a frenar."},"id":"s02-ef-1-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.3.3","ef:1.3.6"],"ambito":"hacer","prompt":"Ordena las fases de una carrera **de la salida al frenado**, como la de María.","hint":"Primero la posición de salida; después se acelera, se mantiene la velocidad y al final se frena.","explain":"Posición de salida → pasos cortos y rápidos (acelerar) → pasos largos (mantener) → acortar pasos y doblar rodillas (desacelerar) → detenerse con ambos pies firmes.","type":"order","props":{"items":[{"id":"a","text":"Un pie adelante y el cuerpo inclinado hacia adelante"},{"id":"b","text":"Pasos cortos y rápidos que se van alargando"},{"id":"c","text":"Pasos largos a velocidad constante"},{"id":"d","text":"Acortar los pasos y doblar las rodillas, con el tronco un poco atrás"},{"id":"e","text":"Detenerse con los dos pies firmes"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s02-ef-1-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.3.3"],"ambito":"hacer","prompt":"¡Juego del semáforo! Pide a alguien que diga los colores (o usa tarjetas). **Calentamiento:** trote suave 1 minuto y rotación de tobillos. **Juego:** **verde** = acelera hasta correr; **amarillo** = desacelera hasta caminar; **rojo** = frena con la técnica y quédate quieto. Repite muchas veces. **Poco espacio:** hazlo en tu lugar (trote rápido, lento, alto). **Adaptación:** en silla de ruedas, acelera y frena empujando las ruedas, o hazlo con los brazos. Termina caminando y tomando agua.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después del calentamiento","exercise":{"name":"Trote suave y tobillos","icon":"Footprints","seconds":60}},{"label":"Después del juego del semáforo","exercise":{"name":"Verde acelera, amarillo desacelera, rojo frena","icon":"Gauge","seconds":90}}]},"id":"s02-ef-1-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.3.3"],"ambito":"conocer","prompt":"Clasifica cada situación del juego: ¿aceleración o desaceleración?","explain":"Aumentar la velocidad es acelerar; disminuirla es desacelerar.","type":"sort","props":{"buckets":[{"id":"a","label":"Aceleración","icon":"TrendingUp","color":"var(--area-ef)"},{"id":"d","label":"Desaceleración","icon":"TrendingDown","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"Salir corriendo cuando te van a tentar","bucket":"a"},{"id":"x2","text":"Llegar a la base y detenerte","bucket":"d"},{"id":"x3","text":"Pasar de caminar a trotar","bucket":"a"},{"id":"x4","text":"Ir más despacio al acercarte a una esquina","bucket":"d"},{"id":"x5","text":"Arrancar para alcanzar una pelota","bucket":"a"}]},"id":"s02-ef-1-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.3.3","ef:1.3.6"],"ambito":"ser","prompt":"Jorge corre muy rápido hacia la pared del salón y quiere frenar a un paso de ella con las piernas rectas. ¿Qué le aconsejas?","explain":"Hay que desacelerar con anticipación y con la técnica: pasos cortos y rodillas dobladas. Correr hacia una pared es peligroso: la meta debe estar lejos de obstáculos.","type":"choice","props":{"options":[{"id":"a","text":"Que empiece a frenar antes, con pasos cortos y rodillas dobladas, y que ponga la meta lejos de la pared"},{"id":"b","text":"Que ponga las manos adelante para frenar con la pared","feedback":"Chocar con las manos contra la pared puede lastimar muñecas y brazos."},{"id":"c","text":"Que corra más rápido para terminar pronto","feedback":"Más velocidad necesita más distancia para frenar."}],"correct":["a"]},"id":"s02-ef-1-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.3.3"],"prompt":"¿Qué es **desacelerar**?","type":"choice","props":{"options":[{"id":"a","text":"Aumentar la velocidad poco a poco"},{"id":"b","text":"Disminuir la velocidad hasta detenerse"},{"id":"c","text":"Mantener siempre la misma velocidad"}],"correct":["b"]},"id":"s02-ef-1-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.3.3","ef:1.3.6"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Para frenar con seguridad conviene doblar las rodillas.","answer":true},{"text":"Al acelerar, los primeros pasos deben ser largos y lentos.","answer":false,"why":"Los primeros pasos son cortos y rápidos; luego se alargan."},{"text":"Mientras más rápido corres, antes debes empezar a frenar.","answer":true}]},"id":"s02-ef-1-10"}],"kind":"materia","area":"ef","day":2}},{"missionId":"s02","version":"cnb-sexto-0fb8b774d322bccd","lesson":{"id":"s02-fc-1","title":"Los derechos de la niñez y quién los protege","icon":"Baby","minutes":14,"gancho":"Tienes 11 o 12 años. ¿Sabías que hay leyes escritas especialmente para proteger a personas de tu edad?","objetivos":["Conocer la Convención sobre los Derechos del Niño y la Ley PINA de Guatemala","Clasificar los derechos de la niñez en supervivencia, desarrollo, protección y participación","Reconocer a quién acudir cuando un derecho de la niñez no se respeta"],"resumen":["La Convención sobre los Derechos del Niño fue aprobada por las Naciones Unidas el 20 de noviembre de 1989; Guatemala la ratificó en 1990. Protege a toda persona menor de 18 años.","En Guatemala, la Ley de Protección Integral de la Niñez y Adolescencia (Ley PINA, Decreto 27-2003) desarrolla esos derechos.","Los derechos de la niñez se agrupan en: supervivencia (vida, salud, alimentación), desarrollo (educación, juego, cultura), protección (contra la violencia y la explotación) y participación (opinar y ser escuchado).","Si un derecho no se respeta, habla con una persona adulta de confianza. Instituciones como la Procuraduría de los Derechos Humanos y la Procuraduría General de la Nación protegen a la niñez."],"media":{"id":"s02-fc-1-cuatro-grupos","kind":"diagram","title":"Cuatro grupos de derechos","aspect":"1:1","alt":"Un círculo dividido en cuatro partes con un niño y una niña al centro: supervivencia, desarrollo, protección y participación, cada una con un ícono y ejemplos.","brief":"Diagrama circular dividido en cuatro cuadrantes de colores suaves, con una niña y un niño guatemaltecos (uno con traje maya, otro con uniforme escolar) al centro. Cuadrantes: \\"Supervivencia\\" (ícono de corazón: vida, salud, alimentación), \\"Desarrollo\\" (ícono de libro: educación, juego, cultura), \\"Protección\\" (ícono de escudo: contra violencia, explotación, abandono), \\"Participación\\" (ícono de globo de diálogo: opinar, ser escuchado, reunirse). Textos grandes y cortos, fondo blanco, estilo plano. Dimensiones: 1200x1200. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"conocer","title":"Leyes que protegen a la niñez","prompt":"Las niñas, los niños y los adolescentes están creciendo y necesitan **protección especial**. Por eso existen leyes solo para ellos. Toca cada tarjeta.","type":"explain","props":{"icon":"ScrollText","body":"Estas leyes no quitan responsabilidades: los derechos van de la mano con **deberes**, como respetar a los demás, estudiar y cuidar lo común.","reveal":[{"icon":"Globe","front":"Convención sobre los Derechos del Niño","back":"Tratado de las **Naciones Unidas** aprobado el **20 de noviembre de 1989**. Protege a toda persona **menor de 18 años**. Guatemala la ratificó en **1990**."},{"icon":"Landmark","front":"Ley PINA","back":"Ley de Protección Integral de la Niñez y Adolescencia, **Decreto 27-2003** del Congreso de Guatemala. Aplica la Convención en nuestro país."},{"icon":"Star","front":"Interés superior del niño","back":"Principio clave: en toda decisión que afecte a una niña o un niño, se debe buscar **lo que más le conviene** para su bienestar y desarrollo."},{"icon":"Scale","front":"No discriminación","back":"Los derechos son para **toda** la niñez: de cualquier pueblo, idioma, religión, sexo, condición económica o discapacidad."},{"icon":"Phone","front":"¿A quién acudir?","back":"Primero, a una **persona adulta de confianza** (familia, maestra, directora). Además, la **Procuraduría de los Derechos Humanos** y la **Procuraduría General de la Nación** (por medio de su Procuraduría de la Niñez y la Adolescencia) protegen a la niñez."}]},"id":"s02-fc-1-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"conocer","prompt":"Comprueba las ideas centrales que acabas de estudiar sobre los derechos de la niñez.","explain":"Hoy verás que la niñez tiene derechos **especiales** además de los derechos humanos de todas las personas, y que en Guatemala existe una ley para protegerlos.","type":"true-false","props":{"statements":[{"text":"Las niñas y los niños tienen derecho a jugar y descansar.","answer":true},{"text":"Los niños solo tienen derechos cuando cumplen 18 años.","answer":false,"why":"Tienen derechos desde que nacen. A los 18 años se adquieren además derechos políticos, como votar."},{"text":"Una niña tiene derecho a dar su opinión sobre lo que le afecta.","answer":true}]},"id":"s02-fc-1-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"conocer","title":"Cuatro grupos de derechos","prompt":"Para estudiarlos, los derechos de la niñez se agrupan en **cuatro familias**. Toca cada una.","type":"explain","props":{"icon":"Layers","body":"Una pista para recordarlas: **vivir**, **crecer**, **estar a salvo** y **tener voz**.","reveal":[{"icon":"HeartPulse","front":"Supervivencia (vivir)","back":"Derecho a la **vida**, la **salud**, la **alimentación**, el agua y una vivienda digna."},{"icon":"BookOpen","front":"Desarrollo (crecer)","back":"Derecho a la **educación**, al **juego** y el descanso, a la **cultura** y a su propio idioma, a un nombre y una identidad."},{"icon":"Shield","front":"Protección (estar a salvo)","back":"Derecho a ser protegido de la **violencia**, el maltrato, el abandono y los **trabajos que dañan** su salud o le impiden estudiar."},{"icon":"MessageCircle","front":"Participación (tener voz)","back":"Derecho a **opinar y ser escuchado** en lo que le afecta, a reunirse y a organizarse, por ejemplo en el gobierno escolar."}]},"id":"s02-fc-1-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"prompt":"Clasifica cada derecho en su familia.","hint":"Usa la pista: vivir (supervivencia), crecer (desarrollo), estar a salvo (protección), tener voz (participación).","explain":"Supervivencia: vivir sano. Desarrollo: crecer y aprender. Protección: estar a salvo del daño. Participación: tener voz.","type":"sort","props":{"layout":"grid2","buckets":[{"id":"sup","label":"Supervivencia","icon":"HeartPulse","color":"var(--c-ok)"},{"id":"des","label":"Desarrollo","icon":"BookOpen","color":"var(--c-jade)"},{"id":"pro","label":"Protección","icon":"Shield","color":"var(--area-fc)"},{"id":"par","label":"Participación","icon":"MessageCircle","color":"var(--c-maiz-strong)"}],"items":[{"id":"d1","text":"Recibir vacunas y atención médica","bucket":"sup"},{"id":"d2","text":"Ir a la escuela","bucket":"des"},{"id":"d3","text":"No ser golpeado ni humillado","bucket":"pro"},{"id":"d4","text":"Votar en la elección del gobierno escolar","bucket":"par"},{"id":"d5","text":"Comer lo suficiente cada día","bucket":"sup"},{"id":"d6","text":"Jugar y aprender en su propio idioma","bucket":"des"},{"id":"d7","text":"No hacer trabajos peligrosos","bucket":"pro","feedback":"Los trabajos que dañan la salud o impiden estudiar van contra el derecho a la protección."},{"id":"d8","text":"Dar su opinión en una asamblea de la comunidad","bucket":"par"}]},"id":"s02-fc-1-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"hacer","title":"Ejemplo resuelto: ¿qué derecho está en juego?","prompt":"Mira cómo se analiza un caso de la niñez usando lo que aprendiste.","type":"worked-example","props":{"icon":"Search","problem":"Supongamos que **Ana**, de 11 años, dejó la escuela porque su familia la necesita para cuidar a sus hermanos pequeños todo el día mientras sus papás venden en el mercado.","steps":[{"text":"**¿Qué derecho se afecta?** El derecho a la **educación** (familia: desarrollo)."},{"text":"**¿Hay otro derecho en juego?** El derecho al **juego y al descanso**, porque pasa todo el día trabajando en casa.","why":"Cuidar hermanos un rato es una responsabilidad familiar; hacerlo todo el día en lugar de estudiar ya afecta sus derechos."},{"text":"**¿Qué dice el principio del interés superior?** Hay que buscar la solución que más convenga a Ana: que pueda estudiar."},{"text":"**¿Qué se puede hacer?** La maestra puede hablar con la familia y buscar apoyos de la comunidad (por ejemplo, un programa de cuidado infantil o turnos entre familiares)."}],"answer":"El caso de Ana afecta sus derechos de **desarrollo**. La solución debe buscar **su interés superior**: que vuelva a estudiar.","tip":"Analizar no es culpar: la familia de Ana también necesita apoyo. Los derechos se cumplen entre todos."},"id":"s02-fc-1-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"prompt":"En una reunión de la comunidad se decide dónde construir un parque infantil, pero **nadie pregunta a las niñas y los niños**. ¿Qué derecho no se está tomando en cuenta?","hint":"¿Cuál de las cuatro familias habla de \\"tener voz\\"?","explain":"El derecho a **opinar y ser escuchado** (participación). El parque es para la niñez: su opinión importa.","type":"choice","props":{"options":[{"id":"a","text":"Participación: opinar y ser escuchado","icon":"MessageCircle"},{"id":"b","text":"Supervivencia: alimentación","icon":"Wheat","feedback":"La comida no es el tema aquí. Fíjate en quién no fue consultado."},{"id":"c","text":"Protección contra la violencia","icon":"Shield","feedback":"Nadie está en peligro. El problema es que no se escucha a la niñez."}],"correct":["a"]},"id":"s02-fc-1-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"convivir","prompt":"¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Shield","text":"Tu amigo **Luis** llega varios días con moretones y te cuenta, triste, que en su casa le pegan cuando se equivoca. Te pide que no le digas a nadie."},"options":[{"id":"a","icon":"Lock","text":"Guardar el secreto como te pidió","consequence":"Luis sigue sufriendo en silencio. Guardar un secreto que hace daño no es ayudar.","values":["Lealtad mal entendida"],"constructive":false},{"id":"b","icon":"HeartHandshake","text":"Decirle que no es su culpa y acompañarlo a hablar con la maestra o la directora","consequence":"Una persona adulta de confianza sabe cómo buscar protección para Luis. Él se siente acompañado.","values":["Solidaridad","Protección","Valentía"],"constructive":true},{"id":"c","icon":"Home","text":"Contarle a tu mamá, papá o encargado para que te ayuden a saber qué hacer","consequence":"Un adulto de confianza puede orientar y avisar a quien corresponde. Luis recibe apoyo.","values":["Responsabilidad","Confianza"],"constructive":true}]},"id":"s02-fc-1-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.2"],"prompt":"Une cada situación con la **familia de derechos** que se ve afectada.","explain":"Identificar la familia del derecho ayuda a saber qué tipo de apoyo se necesita.","type":"match","props":{"leftTitle":"Situación","rightTitle":"Familia de derechos","pairs":[{"id":"x1","left":"Un bebé no recibió sus vacunas","leftIcon":"Syringe","right":"Supervivencia"},{"id":"x2","left":"Un niño trabaja cargando bultos pesados en lugar de estudiar","leftIcon":"Package","right":"Protección"},{"id":"x3","left":"En una escuela no dejan que los estudiantes elijan a su gobierno escolar","leftIcon":"Vote","right":"Participación"},{"id":"x4","left":"Una niña no tiene libros ni útiles para aprender","leftIcon":"BookOpen","right":"Desarrollo"}]},"id":"s02-fc-1-8"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.2"],"prompt":"¿Cómo se llama la ley de Guatemala que protege los derechos de la niñez y la adolescencia?","type":"choice","props":{"options":[{"id":"a","text":"Ley de Protección Integral de la Niñez y Adolescencia (Ley PINA)"},{"id":"b","text":"Ley de Tránsito"},{"id":"c","text":"Declaración de Independencia"}],"correct":["a"]},"id":"s02-fc-1-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.2"],"prompt":"Clasifica cada derecho en su familia.","type":"sort","props":{"buckets":[{"id":"sup","label":"Supervivencia","icon":"HeartPulse"},{"id":"pro","label":"Protección","icon":"Shield"},{"id":"par","label":"Participación","icon":"MessageCircle"}],"items":[{"id":"k1","text":"Tener agua limpia para beber","bucket":"sup"},{"id":"k2","text":"No sufrir maltrato","bucket":"pro"},{"id":"k3","text":"Ser escuchado cuando se decide algo que le afecta","bucket":"par"},{"id":"k4","text":"No ser obligado a trabajar en lugar de estudiar","bucket":"pro"}]},"id":"s02-fc-1-10"}],"kind":"materia","area":"fc","day":2}},{"missionId":"s02","version":"cnb-sexto-cd4771e05207030e","lesson":{"id":"s02-l2-1","title":"Palabras que muestran respeto","icon":"Handshake","minutes":14,"gancho":"En el mercado, ¿a quién le venden más rápido y con una sonrisa: al que dice \\"¡Deme tomates!\\" o al que dice \\"Buenos días, doña Juana, ¿me da tomates, por favor\\"?","objetivos":["Usar saludos y expresiones de cortesía en español","Elegir entre usted, tú o vos según la persona","Usar y escribir bien los títulos de respeto (don, doña, Sr., Dra., Lic.…)"],"resumen":["Expresiones de cortesía: buenos días, por favor, gracias, con permiso, disculpe.","Usamos \\"usted\\" con personas mayores, desconocidas o con autoridad; \\"tú\\" o \\"vos\\" con amistades y familia de confianza.","Títulos: don/doña van antes del nombre (doña Rosa); señor/señora antes del apellido (Sr. López). Las abreviaturas empiezan con mayúscula y llevan punto: Sr., Sra., Dr., Dra., Lic., Licda.","Muchos idiomas mayas tienen sus propias formas de respeto, como los clasificadores personales. Pregunta en tu familia cómo se usan."],"media":{"id":"s02-l2-1-mercado-cortesia","kind":"video","title":"Una compra con respeto","aspect":"16:9","duration":50,"alt":"Un niño compra en un puesto de verduras dos veces: primero sin saludar y después con saludo, título y por favor. La vendedora reacciona distinto.","brief":"Video (o animación con personajes) de 50 s en un mercado guatemalteco: puesto de verduras con tomates, güisquiles y hierbas; la vendedora usa corte y güipil (sin identificar una etnia específica de forma estereotipada). Escena 1 (20 s): un niño llega, no saluda y dice \\"¡Deme una libra de tomates!\\"; la vendedora lo atiende seria. Escena 2 (20 s): el mismo niño llega, dice \\"Buenos días, doña Juana. ¿Me da una libra de tomates, por favor?\\"; ella sonríe y le regala una ramita de cilantro; él dice \\"Muchas gracias\\". Cierre (10 s): en pantalla aparecen \\"Buenos días · por favor · gracias · doña\\". Sin marcas comerciales. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:1.3.1"],"ambito":"convivir","title":"Expresiones de cortesía","prompt":"La **cortesía** es tratar a los demás con amabilidad y respeto. En español se nota en ciertas palabras. Toca cada tarjeta.","type":"explain","props":{"icon":"Smile","body":"Estas expresiones abren puertas en cualquier lugar: la escuela, el centro de salud, la municipalidad o la tienda.","reveal":[{"icon":"Sunrise","front":"Saludar","back":"**Buenos días** (en la mañana), **buenas tardes** (después del mediodía), **buenas noches** (al oscurecer). Se saluda al llegar, antes de pedir algo."},{"icon":"HandHeart","front":"Pedir y agradecer","back":"**Por favor** al pedir. **Gracias** o **muchas gracias** al recibir. Se responde: **con gusto** o **de nada**."},{"icon":"Footprints","front":"Pasar o interrumpir","back":"**Con permiso** para pasar o entrar. **Disculpe** para interrumpir o llamar la atención de alguien."},{"icon":"Users","front":"Usted, tú o vos","back":"**Usted** con personas mayores, desconocidas o con autoridad: \\"¿Usted me puede ayudar?\\". **Tú** o **vos** (muy usado en Guatemala) con amigos y familia de confianza."}]},"id":"s02-l2-1-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.3.1"],"ambito":"convivir","prompt":"Imagina que vas al mercado a comprar. ¿Qué forma de pedir **muestra más respeto**?","explain":"La segunda forma tiene un **saludo**, un **título de respeto** (\\"doña\\"), una **pregunta amable** y **\\"por favor\\"**. Hoy aprenderás a usar cada una de estas herramientas.","type":"choice","props":{"options":[{"id":"a","text":"\\"¡Deme una libra de tomates!\\"","icon":"Megaphone","feedback":"Se entiende, pero suena a orden. Falta saludo y amabilidad."},{"id":"b","text":"\\"Buenos días, doña Juana. ¿Me da una libra de tomates, por favor?\\"","icon":"Handshake"}],"correct":["b"]},"id":"s02-l2-1-2"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.3.1"],"ambito":"convivir","title":"Títulos de respeto","prompt":"Los **títulos** se ponen antes del nombre o del apellido. Fíjate cuándo van completos y cuándo **abreviados**.","type":"explain","props":{"icon":"GraduationCap","body":"Regla de escritura: la **abreviatura** empieza con **mayúscula** y termina con **punto** (Sr., Dra.). Si escribes el título completo dentro de una oración, va con minúscula: \\"Saludé a **doña** Rosa y al **doctor** Morales\\".","reveal":[{"icon":"User","front":"don / doña","back":"Personas adultas, antes del **nombre**: don Pedro, doña Rosa. Dentro de una oración se escriben con minúscula: \\"Saludé a doña Rosa\\"."},{"icon":"Users","front":"Sr. / Sra.","back":"Señor, señora: antes del **apellido**: Sr. López, Sra. Tzoc."},{"icon":"Stethoscope","front":"Dr. / Dra.","back":"Doctor, doctora: Dr. Morales, Dra. Xiloj."},{"icon":"Briefcase","front":"Lic. / Licda.","back":"Licenciado, licenciada (forma usada en Guatemala): Lic. Ramírez, Licda. Pop."},{"icon":"Languages","front":"En idiomas mayas","back":"Varios idiomas mayas usan **clasificadores personales**: palabritas antes del nombre que indican, por ejemplo, si se habla de un hombre, de una mujer o de una persona mayor. **Pregunta en tu familia o comunidad** cómo se dicen en tu idioma."}]},"id":"s02-l2-1-3"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.3.1"],"ambito":"convivir","prompt":"Ahora tú, con ayuda: une cada situación con la expresión de respeto más adecuada.","hint":"Pregúntate: ¿conozco el nombre o el apellido? ¿Tiene una profesión? ¿Estoy hablando o escribiendo?","explain":"Elegir el título y la expresión correctos demuestra respeto y buena educación. Al escribir se abrevia (Dr. Morales); al hablar se dice completo (licenciada Pop).","type":"match","props":{"leftTitle":"Situación","rightTitle":"Expresión","pairs":[{"id":"r1","left":"Saludas a Rosa, la señora que vende tortillas","leftIcon":"Store","right":"\\"Buenos días, doña Rosa.\\""},{"id":"r2","left":"Escribes una nota al médico Juan Morales","leftIcon":"Mail","right":"\\"Estimado Dr. Morales:\\""},{"id":"r3","left":"Necesitas pasar entre dos personas que conversan","leftIcon":"Footprints","right":"\\"Con permiso.\\""},{"id":"r4","left":"Interrumpes a la licenciada Pop para preguntar algo","leftIcon":"Briefcase","right":"\\"Disculpe, licenciada Pop…\\""}]},"id":"s02-l2-1-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.3.1"],"ambito":"hacer","title":"Ejemplo resuelto","prompt":"Mira cómo Mario escribe el inicio de una nota respetuosa.","type":"worked-example","props":{"icon":"PenLine","problem":"Mario quiere pedirle a la doctora **Marta Xiloj**, del puesto de salud, que visite su escuela. ¿Cómo empieza su nota?","steps":[{"text":"Elige un saludo formal para una carta: **Estimada**.","why":"Es formal y amable. \\"Estimada\\" va en femenino porque es una mujer."},{"text":"Agrega el título abreviado: **Dra.**, con mayúscula y punto."},{"text":"Escribe el **apellido**: Xiloj, con mayúscula porque es nombre propio."},{"text":"Termina el saludo de la carta con **dos puntos** (:).","why":"En español, el saludo de una carta termina con dos puntos, no con coma."}],"answer":"**Estimada Dra. Xiloj:**","tip":"Al hablar, di el título completo (\\"doctora Xiloj\\"); al escribir, puedes abreviarlo (\\"Dra. Xiloj\\")."},"id":"s02-l2-1-5"},{"fase":"construir","areas":["l2"],"cnb":["l2:1.3.1"],"ambito":"convivir","prompt":"Completa el diálogo en la municipalidad con expresiones de cortesía.","hint":"Piensa qué se dice al llegar, al pedir algo y al recibir ayuda. La señora es una persona desconocida: se le habla de usted.","explain":"Saludo al llegar, \\"por favor\\" al pedir, \\"usted\\" con una persona desconocida y \\"gracias\\" al final.","type":"fill-blank","props":{"text":"Lucía: [[Buenas tardes]], señora. ¿Me podría ayudar, [[por favor]]?\\nSecretaria: Claro, ¿en qué le ayudo?\\nLucía: ¿Sabe [[usted]] dónde entregan los certificados de nacimiento?\\nSecretaria: En la ventanilla 3.\\nLucía: Muchas [[gracias]].\\nSecretaria: Con gusto.","distractors":["vos","Oiga","nada"]},"id":"s02-l2-1-6"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:1.3.1"],"ambito":"convivir","prompt":"¿Cómo le hablarías a cada persona? Clasifícalas.","explain":"Usamos **usted** para mostrar respeto a personas mayores, desconocidas o con autoridad. Con amistades y familia de confianza usamos **tú** o **vos**. En algunas familias guatemaltecas los hijos hablan de usted a sus padres y abuelos: también está bien.","type":"sort","props":{"buckets":[{"id":"u","label":"Usted (respeto)","icon":"Crown","color":"var(--area-l2)"},{"id":"t","label":"Tú o vos (confianza)","icon":"Smile","color":"var(--c-ok)"}],"items":[{"id":"p1","text":"La alcaldesa del municipio","bucket":"u"},{"id":"p2","text":"Tu mejor amiga","bucket":"t"},{"id":"p3","text":"Un señor que no conoces y te pregunta una dirección","bucket":"u"},{"id":"p4","text":"Tu primo de 10 años","bucket":"t"},{"id":"p5","text":"El agente de tránsito","bucket":"u"},{"id":"p6","text":"Tu compañero de pupitre","bucket":"t"}]},"id":"s02-l2-1-7"},{"fase":"aplicar","areas":["l2","fc"],"cnb":["l2:1.3.1"],"ambito":"convivir","prompt":"¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Store","text":"En el mercado, doña Candelaria vende tejidos. Ella habla principalmente q’eqchi’ y está aprendiendo español. Un comprador le habla rápido y con prisa, y unos jóvenes se ríen de cómo ella pronuncia algunas palabras."},"options":[{"id":"a","icon":"EyeOff","text":"Reírme también para no quedar mal","consequence":"Doña Candelaria se siente humillada. Burlarse de cómo alguien habla un segundo idioma es una falta de respeto.","values":["Presión de grupo"],"constructive":false},{"id":"b","icon":"HeartHandshake","text":"Saludarla con respeto, hablarle despacio y ayudar a traducir si ella lo desea","consequence":"La compra se hace con calma y respeto. Hablar despacio y con amabilidad ayuda a quien aprende un idioma.","values":["Respeto","Solidaridad","Interculturalidad"],"constructive":true},{"id":"c","icon":"MessageCircle","text":"Decirles a los jóvenes: \\"Ella habla dos idiomas; eso tiene mucho mérito\\"","consequence":"Algunos jóvenes se quedan pensando. Hablar dos idiomas es un esfuerzo que merece respeto.","values":["Valentía","Respeto a la diversidad"],"constructive":true}]},"id":"s02-l2-1-8"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:1.3.1"],"ambito":"hacer","prompt":"¿En qué oración está **bien escrito** el título abreviado?","explain":"Las abreviaturas de los títulos empiezan con mayúscula y terminan con punto: **Sr.** Cux.","type":"choice","props":{"options":[{"id":"a","text":"Mañana nos visita el Sr. Cux."},{"id":"b","text":"Mañana nos visita el sr Cux.","feedback":"Falta la mayúscula y el punto de la abreviatura."},{"id":"c","text":"Mañana nos visita el SR Cux.","feedback":"Solo la primera letra va en mayúscula, y lleva punto: Sr."}],"correct":["a"]},"id":"s02-l2-1-9"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:1.3.1"],"prompt":"Boleto de salida: ¿cuál expresión está **bien escrita** y muestra respeto?","type":"choice","props":{"options":[{"id":"a","text":"Buenas tardes, Licda. Pop."},{"id":"b","text":"buenas tardes, licda pop"},{"id":"c","text":"Oiga, Pop."}],"correct":["a"]},"id":"s02-l2-1-10"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:1.3.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"\\"Don\\" y \\"doña\\" se usan antes del nombre: doña Rosa.","answer":true},{"text":"A una persona desconocida y mayor es más respetuoso hablarle de \\"vos\\".","answer":false,"why":"Con personas desconocidas o mayores se usa \\"usted\\"."},{"text":"\\"Con permiso\\" se dice para pasar entre personas o entrar a un lugar.","answer":true}]},"id":"s02-l2-1-11"}],"kind":"materia","area":"l2","day":2}},{"missionId":"s02","version":"cnb-sexto-423fab0f2242bdae","lesson":{"id":"s02-mat-5","title":"Polígonos en la cultura maya","icon":"Landmark","minutes":15,"gancho":"Si volaras sobre una pirámide maya de Tikal, ¿qué figuras verías desde arriba?","objetivos":["Identificar polígonos regulares e irregulares en la arquitectura y los tejidos mayas","Interpretar cómo se usa la geometría en diseños de tu cultura","Repasar polígonos, sus nombres y sus ángulos"],"resumen":["Las pirámides mayas escalonadas, vistas desde arriba, muestran cuadrados o rectángulos uno dentro de otro: cada cuerpo es más pequeño que el de abajo.","En los tejidos aparecen rombos, triángulos, cuadrados y zigzags hechos con simetría.","Para interpretar un diseño: nombra sus polígonos, di si son regulares o irregulares y busca el patrón que se repite.","El significado de los diseños puede variar entre comunidades: vale la pena preguntar a quienes tejen."],"media":{"id":"s02-mat-5-tikal","kind":"image","title":"Geometría en Tikal y en un güipil","aspect":"16:9","alt":"A la izquierda, un templo escalonado de Tikal visto de frente y desde arriba, con sus cuerpos como rectángulos uno dentro de otro. A la derecha, un güipil con rombos, triángulos y zigzags.","brief":"Ilustración en dos mitades. Izquierda: un templo maya escalonado de Tikal (Petén) entre la selva; un recuadro muestra su vista desde arriba como rectángulos de colores uno dentro de otro, con la etiqueta \\"vista desde arriba\\". Derecha: la parte frontal de un güipil con franjas de rombos, triángulos en zigzag y cuadrados, con uno de los rombos resaltado con contorno. Sin personas identificables, sin reproducir un diseño específico de una comunidad; colores inspirados en textiles del altiplano. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:1.1.10","mat:1.1.6"],"ambito":"conocer","title":"Cómo interpretar un diseño","prompt":"Interpretar un diseño con ojos de matemático es responder tres preguntas. Toca cada tarjeta.","type":"explain","props":{"icon":"Search","body":"Nombrar, clasificar y buscar el patrón.","reveal":[{"icon":"Tag","front":"1. ¿Qué polígonos hay?","back":"Nómbralos por su número de lados: triángulos, cuadrados, rombos, rectángulos…"},{"icon":"Hexagon","front":"2. ¿Regulares o irregulares?","back":"El cuadrado y el triángulo equilátero son regulares. El rombo (sin ángulos rectos) y el rectángulo son irregulares."},{"icon":"Repeat","front":"3. ¿Qué se repite?","back":"Busca la simetría (una mitad refleja la otra) y la franja que se repite a lo largo."}]},"id":"s02-mat-5-1"},{"fase":"construir","areas":["mat","ccss"],"cnb":["mat:1.1.10"],"ambito":"conocer","prompt":"Una pirámide maya escalonada tiene varios \\"pisos\\" o cuerpos, cada uno más pequeño que el de abajo. **Vista desde arriba**, ¿qué verías?","explain":"Verías **cuadriláteros uno dentro de otro**: cada cuerpo es un rectángulo o cuadrado más pequeño, encima del anterior.","type":"choice","props":{"options":[{"id":"a","text":"Círculos uno dentro de otro","icon":"Target","feedback":"Los cuerpos de estas pirámides tienen lados rectos, no curvos."},{"id":"b","text":"Cuadriláteros uno dentro de otro","icon":"Square"},{"id":"c","text":"Un solo triángulo","icon":"Triangle","feedback":"De frente puede parecer un triángulo; desde arriba se ven los cuerpos escalonados."}],"correct":["b"]},"id":"s02-mat-5-2"},{"fase":"construir","areas":["mat","ccss"],"cnb":["mat:1.1.10"],"ambito":"conocer","prompt":"Lee este texto sobre la geometría en la cultura maya y responde.","type":"reading","props":{"heading":"Geometría que se construye y se teje","genre":"texto expositivo","passage":"Los antiguos mayas construyeron grandes ciudades como Tikal, en Petén. Sus templos son pirámides escalonadas: varios cuerpos de piedra, uno encima de otro, cada uno más pequeño que el de abajo. Vistos desde arriba, esos cuerpos forman rectángulos o cuadrados uno dentro de otro. Para construirlos se necesitaba medir, trazar ángulos rectos y repetir formas.\\n\\nEn muchas ciudades mayas también había canchas para el juego de pelota. Su forma, vista desde arriba, se parece a una letra I mayúscula: un rectángulo largo en el centro y dos rectángulos más anchos en los extremos.\\n\\nLa geometría sigue viva en los tejidos. En güipiles, fajas y cortes aparecen rombos, triángulos, cuadrados y zigzags. Las tejedoras cuentan hilos para que cada figura sea igual a la otra y para que el diseño sea simétrico. Muchas tejedoras explican que sus figuras tienen significados, por ejemplo relacionados con la naturaleza o con el universo, y esos significados pueden cambiar de una comunidad a otra.","questions":[{"q":"¿Qué forma tienen los cuerpos de una pirámide escalonada vistos desde arriba?","options":[{"id":"a","text":"Rectángulos o cuadrados uno dentro de otro"},{"id":"b","text":"Círculos concéntricos"},{"id":"c","text":"Hexágonos"}],"correct":"a","why":"El texto dice que forman rectángulos o cuadrados uno dentro de otro."},{"q":"¿Por qué las tejedoras cuentan hilos?","options":[{"id":"a","text":"Para gastar menos hilo"},{"id":"b","text":"Para que las figuras sean iguales y el diseño simétrico"},{"id":"c","text":"Para tejer más rápido"}],"correct":"b","why":"Contar hilos asegura figuras congruentes y simetría."},{"q":"Si quieres saber qué significa un rombo en el güipil de tu comunidad, ¿qué es lo más adecuado?","options":[{"id":"a","text":"Suponer que significa lo mismo en todos los pueblos"},{"id":"b","text":"Preguntar con respeto a una tejedora de tu comunidad"},{"id":"c","text":"Decir que no significa nada"}],"correct":"b","why":"El texto dice que los significados pueden cambiar entre comunidades; quienes tejen son la mejor fuente."}]},"id":"s02-mat-5-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.1.10","mat:1.1.6"],"prompt":"Estos polígonos aparecen en construcciones y tejidos mayas. ¿Son regulares o irregulares?","hint":"Regular: todos los lados iguales y todos los ángulos iguales.","explain":"Cuadrados y triángulos equiláteros son regulares; rombos sin ángulos rectos y rectángulos, irregulares.","type":"sort","props":{"buckets":[{"id":"re","label":"Regular","icon":"Hexagon","color":"var(--c-ok)"},{"id":"ir","label":"Irregular","icon":"Shapes","color":"var(--c-maiz-strong)"}],"items":[{"id":"a","text":"Cuerpo cuadrado de una pirámide, vista desde arriba","bucket":"re"},{"id":"b","text":"Rombo de un güipil con ángulos de 60° y 120°","bucket":"ir"},{"id":"c","text":"Rectángulo central de una cancha de juego de pelota","bucket":"ir"},{"id":"d","text":"Triángulo de un zigzag con sus 3 lados iguales","bucket":"re"},{"id":"e","text":"Estela de piedra: rectángulo de 3 m × 1 m","bucket":"ir"}]},"id":"s02-mat-5-4"},{"fase":"aplicar","areas":["mat","art"],"cnb":["mat:1.1.10"],"ambito":"hacer","prompt":"Teje un **rombo** con un **rombo más pequeño adentro**, como en muchas fajas. Completa la mitad derecha reflejando la izquierda.","explain":"El reflejo produce dos mitades congruentes: el rombo completo queda simétrico.","type":"symmetry-loom","props":{"motif":"Rombo dentro de rombo","palette":["#c0283b","#1c9a6b","#eeae1f"],"half":[[null,null,null,0],[null,null,0,1],[null,0,1,2],[0,1,2,2],[null,0,1,2],[null,null,0,1],[null,null,null,0]]},"id":"s02-mat-5-5"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.10","mat:1.1.7"],"prompt":"Vista desde arriba, una cancha de juego de pelota tiene forma de **I mayúscula**: un rectángulo largo y dos rectángulos más anchos en los extremos. Si recorres **todo el borde** de la figura completa, ¿cuántos lados tiene ese polígono?","hint":"Dibuja una I con \\"sombrero\\" y \\"zapatos\\" y cuenta los segmentos del contorno uno por uno.","explain":"Cada extremo ancho aporta 5 lados visibles (arriba, dos costados y dos pedacitos por dentro) y el centro aporta 2 lados largos: 5 + 5 + 2 = 12. Es un polígono irregular de 12 lados.","type":"number-input","props":{"answer":12,"misconceptions":[{"value":4,"msg":"Eso sería un solo rectángulo. La I tiene \\"escalones\\" que agregan lados."},{"value":8,"msg":"Casi: no olvides los pedacitos de borde por dentro de cada extremo."}]},"id":"s02-mat-5-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.8"],"prompt":"Repaso: un bordado tiene un **octágono**. ¿Cuánto suman sus ángulos interiores?","explain":"Octágono: 8 − 2 = 6 triángulos. 6 × 180° = 1,080°.","type":"number-input","props":{"answer":1080,"unit":"°","misconceptions":[{"value":1440,"msg":"Multiplicaste 8 × 180. Recuerda: son 2 triángulos menos que lados."},{"value":135,"msg":"135° mide cada ángulo si el octágono es regular. Te piden la suma."}]},"id":"s02-mat-5-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.1.6","mat:1.1.7","mat:1.1.8","mat:1.1.9"],"prompt":"Repaso de la semana. ¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Un decágono tiene 10 lados.","answer":true},{"text":"El rectángulo es un polígono regular.","answer":false,"why":"Sus lados no son todos iguales."},{"text":"El diámetro mide el doble del radio.","answer":true},{"text":"Un hexágono se divide en 6 triángulos desde un vértice.","answer":false,"why":"Se divide en 6 − 2 = 4."}]},"id":"s02-mat-5-8"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.10"],"prompt":"Una faja tiene rombos con sus 4 lados iguales y ángulos de **45° y 135°**, separados por cuadrados. ¿Qué afirmación es correcta?","type":"choice","props":{"options":[{"id":"a","text":"Los rombos son irregulares y los cuadrados son regulares"},{"id":"b","text":"Los rombos y los cuadrados son regulares"},{"id":"c","text":"Los rombos son regulares y los cuadrados irregulares"}],"correct":["a"]},"id":"s02-mat-5-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.1.10","mat:1.1.7"],"prompt":"Vista desde arriba, una plataforma maya tiene **8 lados iguales y 8 ángulos iguales**. ¿Cómo se describe?","type":"choice","props":{"options":[{"id":"a","text":"Octágono regular"},{"id":"b","text":"Hexágono regular"},{"id":"c","text":"Octágono irregular"}],"correct":["a"]},"id":"s02-mat-5-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["mat"],"cnb":[],"type":"reflection","props":{"statements":["Nombro polígonos de hasta 10 lados","Distingo polígonos regulares e irregulares","Calculo la suma de ángulos de pentágonos y hexágonos","Creo diseños con círculos"],"commitments":["Buscaré polígonos en los tejidos de mi familia o comunidad","Preguntaré a una tejedora qué significan sus figuras","Haré una roseta con compás o cordel"]},"id":"s02-mat-5-11"}],"kind":"materia","area":"mat","day":5}},{"missionId":"s02","version":"cnb-sexto-725568e503acd2a4","lesson":{"id":"s02-fc-2","title":"Desarrollo social: ¿se cumplen los derechos en Guatemala?","icon":"TrendingUp","minutes":15,"gancho":"En algunas comunidades hay escuela, agua y centro de salud; en otras, faltan. ¿Cómo podemos saber si un país avanza en el cumplimiento de los derechos?","objetivos":["Explicar qué es el desarrollo social y cómo se relaciona con los derechos humanos","Analizar datos sencillos para comparar la situación de los derechos en distintos lugares","Reconocer retos reales de Guatemala, como la desnutrición crónica, y quién vigila los derechos"],"resumen":["El desarrollo social es la mejora de la calidad de vida de toda la población: salud, educación, alimentación, vivienda, empleo y participación. Hay desarrollo social cuando los derechos se vuelven realidad para todos.","Para analizar la situación de un derecho se usan datos (indicadores): cuántas casas tienen agua potable, cuántos niños van a la escuela, etc. Comparar lugares muestra desigualdades (brechas).","Un gran reto de Guatemala es la desnutrición crónica: según la encuesta nacional de salud de 2014-2015, casi la mitad de las niñas y los niños menores de cinco años la padecían. Afecta su salud y su aprendizaje.","La Procuraduría de los Derechos Humanos vigila que se respeten los derechos. El Estado, las comunidades y las familias trabajan juntos para el desarrollo social."],"media":{"id":"s02-fc-2-brecha","kind":"animation","title":"Dos aldeas, una brecha","aspect":"16:9","duration":45,"alt":"Dos aldeas lado a lado; en cada una se llenan barras de agua potable, escuela y centro de salud, y se ve que una tiene mucho más que la otra.","brief":"Animación 2D de 45 s. Pantalla dividida: \\"Aldea A\\" (con carretera asfaltada) y \\"Aldea B\\" (lejana, camino de tierra). Sobre cada aldea suben tres barras con íconos: gota (agua potable), libro (niños en la escuela), cruz (centro de salud cerca). En la Aldea A las barras suben alto; en la B quedan bajas. Aparece una llave de corchete entre las barras con la palabra \\"brecha\\". Narración: \\"Los datos nos ayudan a ver dónde los derechos todavía no se cumplen\\". Etiqueta visible: \\"Datos hipotéticos\\". Sin cifras reales, estilo plano, colores cálidos. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"conocer","title":"¿Qué es el desarrollo social?","prompt":"Un país no se desarrolla solo porque tenga edificios altos. Toca cada tarjeta para entender el **desarrollo social**.","type":"explain","props":{"icon":"TrendingUp","body":"Desarrollo social y derechos humanos van juntos: **hay desarrollo social cuando los derechos se cumplen para todas las personas**, no solo para algunas.","reveal":[{"icon":"Users","front":"Desarrollo social","back":"La mejora de la **calidad de vida de toda la población**: salud, educación, alimentación, vivienda, empleo y participación."},{"icon":"BarChart3","front":"Indicador","back":"Un **dato** que muestra cómo está un derecho. Ejemplo: de cada 10 casas, cuántas tienen agua potable."},{"icon":"Scale","front":"Brecha","back":"La **diferencia** entre dos grupos o lugares. Ejemplo: entre el área urbana y el área rural, o entre niñas y niños."},{"icon":"Landmark","front":"Procuraduría de los Derechos Humanos","back":"Institución creada por la **Constitución de 1985**. El Procurador vigila que el Estado respete los derechos humanos y recibe denuncias."}]},"id":"s02-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"conocer","prompt":"Si quisieras saber si en tu municipio se cumple el derecho a la educación, ¿qué dato te ayudaría **más**?","explain":"Los **datos** (cuántos niños estudian, cuántas casas tienen agua…) permiten analizar la situación de los derechos con hechos, no solo con opiniones.","type":"choice","props":{"options":[{"id":"a","text":"Cuántas niñas y niños en edad escolar van a la escuela","icon":"School"},{"id":"b","text":"Cuántos equipos de fútbol hay","icon":"Trophy","feedback":"Es un dato interesante, pero no dice nada sobre la educación."},{"id":"c","text":"De qué color están pintadas las escuelas","icon":"Palette","feedback":"El color no nos dice si los niños están aprendiendo."}],"correct":["a"]},"id":"s02-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"hacer","prompt":"Supongamos que un comité revisó **10 casas** en la aldea El Porvenir. Construye la gráfica con estos datos: agua potable **6**, electricidad **8**, casas donde todos los niños van a la escuela **9**, centro de salud a menos de 30 minutos **2**.","hint":"Cada barra sube de 1 en 1. Busca cada dato en la consigna y súbela hasta ese número.","explain":"La barra más baja (centro de salud cercano: 2 de 10) muestra el derecho que **menos** se cumple en esa aldea: la salud.","type":"chart-builder","props":{"categories":[{"id":"agua","label":"Agua potable","icon":"Droplets","color":"var(--area-ccss)"},{"id":"luz","label":"Electricidad","icon":"Zap","color":"var(--c-maiz-strong)"},{"id":"esc","label":"Escuela","icon":"School","color":"var(--c-jade)"},{"id":"sal","label":"Salud cerca","icon":"Stethoscope","color":"var(--area-fc)"}],"data":[6,8,9,2],"max":10,"step":1,"unit":"casas de 10","source":"Datos hipotéticos de la aldea El Porvenir"},"id":"s02-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"hacer","title":"Ejemplo resuelto: leer la gráfica como ciudadano","prompt":"Una gráfica no termina en las barras: hay que **interpretarla**. Mira cómo.","type":"worked-example","props":{"icon":"BarChart3","problem":"Con los datos de El Porvenir (agua 6, electricidad 8, escuela 9, salud cercana 2, de 10 casas), ¿qué derecho está en peor situación y qué se puede proponer?","steps":[{"text":"**Busco el dato más bajo:** salud cercana, **2 de 10** casas."},{"text":"**Lo traduzco a derechos:** 8 de cada 10 familias no tienen un centro de salud cerca. El **derecho a la salud** no se cumple plenamente.","why":"10 − 2 = 8 familias sin servicio cercano."},{"text":"**Comparo:** la escuela (9 de 10) está mucho mejor. Hay una **brecha** entre educación y salud en la aldea."},{"text":"**Propongo:** el COCODE puede presentar estos datos a la municipalidad y al Ministerio de Salud para pedir un puesto de salud o jornadas médicas."}],"answer":"El derecho en peor situación es la **salud**. Con los datos, la comunidad puede **pedir soluciones con argumentos**.","tip":"Dato → derecho → comparación → propuesta."},"id":"s02-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"conocer","prompt":"Lee este texto sobre la situación real de algunos derechos en Guatemala y responde.","type":"reading","props":{"genre":"Texto informativo","heading":"Derechos que aún son un reto","passage":"La **Constitución Política de la República de Guatemala** reconoce que todas las personas tienen derecho a la vida, la salud y la educación. Sin embargo, esos derechos no se cumplen igual en todo el país.\\n\\nUno de los mayores retos es la **desnutrición crónica**: una niña o un niño la padece cuando, por no alimentarse bien durante mucho tiempo, su estatura queda por debajo de la que corresponde a su edad. Según la encuesta nacional de salud de 2014-2015, **casi la mitad** de las niñas y los niños menores de cinco años en Guatemala la padecían. Esto afecta su salud y su aprendizaje durante toda la vida.\\n\\nTambién hay **brechas**: en muchas comunidades rurales el centro de salud o la escuela quedan a varios kilómetros. Para vigilar que se respeten los derechos existe la **Procuraduría de los Derechos Humanos**. El **desarrollo social** se logra cuando el Estado, las comunidades y las familias trabajan juntos para que los derechos sean una realidad para todos.","questions":[{"q":"¿Qué es la desnutrición crónica, según el texto?","options":[{"id":"a","text":"Tener una estatura menor a la de la edad por no alimentarse bien durante mucho tiempo"},{"id":"b","text":"Comer demasiados dulces un día"},{"id":"c","text":"Una enfermedad que se contagia por el aire"}],"correct":"a"},{"q":"¿Por qué la desnutrición afecta también el derecho a la educación?","options":[{"id":"a","text":"Porque un niño mal alimentado tiene más dificultad para concentrarse y aprender"},{"id":"b","text":"Porque la comida y la escuela no tienen relación"},{"id":"c","text":"Porque solo afecta a las personas adultas"}],"correct":"a","why":"Los derechos son interdependientes: sin alimentación adecuada, aprender es más difícil."},{"q":"¿Qué institución vigila el respeto de los derechos humanos?","options":[{"id":"a","text":"La Procuraduría de los Derechos Humanos"},{"id":"b","text":"El mercado municipal"},{"id":"c","text":"La liga de fútbol"}],"correct":"a"}]},"id":"s02-fc-2-5"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"hacer","prompt":"Supongamos que en otra aldea, Las Flores, **7 de cada 10** casas **no** tienen agua potable. En un grupo de **30 casas**, ¿cuántas **sí** tienen agua potable?","explain":"Si 7 de cada 10 no tienen agua, 3 de cada 10 sí tienen. En 30 casas hay 3 grupos de 10: 3 × 3 = 9 casas con agua potable.","type":"number-input","props":{"answer":9,"unit":"casas","misconceptions":[{"value":21,"msg":"21 son las casas que NO tienen agua (7 × 3). La pregunta es por las que sí tienen."},{"value":3,"msg":"3 es por cada 10 casas. Hay 30 casas: son 3 grupos de 10."}]},"id":"s02-fc-2-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.2"],"prompt":"Clasifica: ¿es un **avance** del desarrollo social o un **reto pendiente**?","explain":"Analizar la situación de los derechos es reconocer lo que se ha logrado y lo que falta, sin exagerar ni negar los problemas.","type":"sort","props":{"buckets":[{"id":"av","label":"Avance","icon":"TrendingUp","color":"var(--c-ok)"},{"id":"re","label":"Reto pendiente","icon":"Target","color":"var(--c-maiz-strong)"}],"items":[{"id":"r1","text":"Una aldea recibe por primera vez un puesto de salud con enfermera","bucket":"av"},{"id":"r2","text":"Muchas niñas y niños pequeños con desnutrición crónica","bucket":"re"},{"id":"r3","text":"Escuelas rurales que enseñan en el idioma materno y en español","bucket":"av"},{"id":"r4","text":"Familias rurales que caminan horas para llegar a un centro de salud","bucket":"re"},{"id":"r5","text":"Un sistema de agua potable construido con la comunidad y la municipalidad","bucket":"av"}]},"id":"s02-fc-2-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.2"],"ambito":"hacer","prompt":"Elige **un derecho de la niñez** y analiza su situación en tu comunidad: ¿qué dato o hecho observas?, ¿es un avance o un reto?, ¿quién debería actuar y qué propones?","type":"short-answer","props":{"minWords":35,"placeholder":"Elegí el derecho a… En mi comunidad observo que…","model":"Elegí el derecho a la educación. En mi comunidad observo que casi todos los niños van a la escuela primaria, pero varios jóvenes no siguen el básico porque el instituto queda lejos. Es un avance en primaria y un reto en básico. La municipalidad y el Ministerio de Educación deberían actuar; propongo que el COCODE pida transporte escolar o un instituto por cooperativa más cerca.","rubric":["Elegí un derecho de la niñez","Usé un dato o un hecho observado","Dije si es un avance o un reto","Nombré quién debe actuar y propuse algo posible"]},"id":"s02-fc-2-8"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.2"],"prompt":"¿Cuál es la mejor definición de **desarrollo social**?","type":"choice","props":{"options":[{"id":"a","text":"La mejora de la calidad de vida de toda la población, cuando los derechos se cumplen para todos"},{"id":"b","text":"Construir muchos edificios altos en la capital"},{"id":"c","text":"Que unas pocas familias tengan mucho dinero"}],"correct":["a"]},"id":"s02-fc-2-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.2"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"La desnutrición crónica es uno de los grandes retos para los derechos de la niñez en Guatemala.","answer":true},{"text":"Una brecha es la diferencia en la situación de dos lugares o grupos.","answer":true},{"text":"En Guatemala todos los derechos se cumplen igual en todas las comunidades.","answer":false,"why":"Todavía hay brechas, por ejemplo entre áreas urbanas y rurales."},{"text":"La Convención sobre los Derechos del Niño protege a toda persona menor de 18 años.","answer":true}]},"id":"s02-fc-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["fc"],"cnb":["fc:1.2.2"],"type":"reflection","props":{"statements":["Conozco la Convención sobre los Derechos del Niño y la Ley PINA","Clasifico los derechos de la niñez en cuatro familias","Analizo con datos si un derecho se cumple en un lugar"],"commitments":["Contaré a mi familia qué es el interés superior del niño","Observaré un dato de mi comunidad (agua, escuela, salud) y lo anotaré","Si sé de un niño que sufre, hablaré con una persona adulta de confianza"]},"id":"s02-fc-2-11"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s02","version":"cnb-sexto-38d78aa1b016aaa8","lesson":{"id":"s02-l1-3","title":"Leer para estudiar: datos, listas y tablas","icon":"ClipboardList","minutes":14,"gancho":"Si alguien te pregunta qué día hay mercado en Chichicastenango, ¿lees todo un libro o buscas rápido el dato?","objetivos":["Localizar datos en textos de estudio de distintas materias","Leer una tabla por filas y columnas","Usar negritas, listas y subtítulos como guías de lectura"],"resumen":["En los textos de estudio, los subtítulos, las negritas y las listas te guían: te dicen dónde está cada información.","Para buscar un dato no hace falta leer todo con detalle: primero ubica la parte donde está (lectura de búsqueda) y luego lee esa parte con atención.","Una tabla organiza datos en filas (horizontales) y columnas (verticales). El dato está donde se cruzan la fila y la columna que te interesan."],"media":{"id":"s02-l1-3-tabla","kind":"diagram","title":"Cómo se lee una tabla","aspect":"16:9","alt":"Tabla de tres columnas (Mercado, Departamento, Días principales) con una fila resaltada en amarillo y una columna resaltada en celeste; en su cruce, una estrella marca el dato buscado.","brief":"Diagrama animable de una tabla sencilla con encabezados \\"Mercado\\", \\"Departamento\\", \\"Días principales\\" y tres filas: Chichicastenango | El Quiché | jueves y domingo; San Francisco El Alto | Totonicapán | viernes; Sololá | Sololá | martes y viernes. Resaltar la fila \\"Chichicastenango\\" en amarillo y la columna \\"Días principales\\" en celeste; en el cruce, una estrella y el rótulo \\"¡Aquí está el dato!\\". Flechas: \\"fila →\\", \\"columna ↓\\". Estilo plano, legible en teléfono. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:4.2.1"],"ambito":"conocer","title":"Las guías de un texto de estudio","prompt":"Los textos de estudio tienen **señales** que te ayudan a encontrar la información. Toca cada tarjeta.","type":"explain","props":{"icon":"Signpost","body":"Leer para estudiar tiene dos velocidades: **rápida** para ubicar dónde está la información y **lenta** para entenderla bien.","reveal":[{"icon":"Heading","front":"Títulos y subtítulos","back":"Dividen el texto en partes. Leyéndolos sabes en qué parte está lo que buscas."},{"icon":"Bold","front":"Negritas","back":"Las palabras en **negrita** son las más importantes: conceptos, nombres, fechas."},{"icon":"List","front":"Listas con viñetas","back":"Presentan varios elementos de forma ordenada: pasos, características, ejemplos."},{"icon":"Table","front":"Tablas","back":"Organizan datos en **filas** (horizontales →) y **columnas** (verticales ↓). El dato está en el cruce."}]},"id":"s02-l1-3-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:4.2.1"],"ambito":"conocer","prompt":"Tienes un libro de Ciencias Sociales de 200 páginas y necesitas saber **en qué departamento está San Francisco El Alto**. ¿Qué haces?","explain":"Para buscar un dato no se lee todo el libro: se usan las guías del texto (índice, subtítulos, negritas, tablas) para ir directo a la parte que sirve.","type":"choice","props":{"options":[{"id":"a","text":"Leo el libro completo desde la página 1","icon":"BookOpen","feedback":"Funcionaría… ¡pero tardarías días! Hay formas más rápidas."},{"id":"b","text":"Busco un subtítulo, una lista o una tabla sobre los municipios o mercados","icon":"Search"},{"id":"c","text":"Adivino","icon":"HelpCircle","feedback":"Adivinar no es investigar. Busca el dato en el texto."}],"correct":["b"]},"id":"s02-l1-3-2"},{"fase":"construir","areas":["l1","ccss"],"cnb":["l1:4.2.1"],"ambito":"conocer","prompt":"Lee este texto de Ciencias Sociales. Usa los **subtítulos y la lista** para encontrar rápido cada respuesta.","hint":"Primero mira los subtítulos y decide en qué parte está cada respuesta.","type":"reading","props":{"genre":"Texto expositivo (Ciencias Sociales)","heading":"Los mercados de Guatemala","passage":"**¿Qué es un día de mercado?**\\n\\nEn muchos pueblos de Guatemala, el mercado no abre igual todos los días. Hay **días de mercado**, en los que llegan vendedores y compradores de aldeas y municipios cercanos. Esos días, la plaza se llena de colores, voces y olores.\\n\\n**Algunos mercados conocidos**\\n\\n• **Chichicastenango** (El Quiché): jueves y domingo.\\n• **San Francisco El Alto** (Totonicapán): viernes; es famoso por su gran tamaño.\\n• **Sololá** (Sololá): martes y viernes.\\n\\n**Más que comprar y vender**\\n\\nEn el mercado también se encuentran familias, se comparten noticias y se hablan distintos idiomas, como el k'iche', el kaqchikel y el español. Por eso, el mercado es un lugar de **intercambio cultural**, no solo de productos.","questions":[{"q":"¿Qué días hay mercado en Chichicastenango?","options":[{"id":"a","text":"Jueves y domingo"},{"id":"b","text":"Martes y viernes"},{"id":"c","text":"Solo viernes"}],"correct":"a","why":"Está en la lista, bajo el subtítulo \\"Algunos mercados conocidos\\"."},{"q":"¿Bajo qué subtítulo buscarías **por qué el mercado es importante para la cultura**?","options":[{"id":"a","text":"\\"Más que comprar y vender\\""},{"id":"b","text":"\\"Algunos mercados conocidos\\""},{"id":"c","text":"\\"¿Qué es un día de mercado?\\""}],"correct":"a","why":"Ese subtítulo anuncia que el mercado es algo más que un lugar de compras."},{"q":"Según el texto, ¿qué significa que el mercado sea un lugar de **intercambio cultural**?","options":[{"id":"a","text":"Que ahí se comparten noticias, costumbres e idiomas, además de productos"},{"id":"b","text":"Que solo se venden artesanías"},{"id":"c","text":"Que solo llegan turistas"}],"correct":"a","why":"El último párrafo lo explica: familias que se encuentran, noticias e idiomas."}]},"id":"s02-l1-3-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:4.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: leer una tabla","prompt":"Supongamos que una escuela anotó los **precios de algunas verduras** en dos mercados. Mira cómo se encuentra un dato.","type":"worked-example","props":{"icon":"Table","problem":"Tabla (datos supuestos):\\n\\nVerdura | Mercado A | Mercado B\\nTomate (libra) | Q5 | Q4\\nGüisquil (unidad) | Q2 | Q3\\nCebolla (libra) | Q6 | Q6\\n\\n¿Cuánto cuesta el güisquil en el Mercado B?","steps":[{"text":"Leo el **título de las columnas**: Verdura, Mercado A, Mercado B.","why":"Así sé qué información hay en cada columna."},{"text":"Busco la **fila** del güisquil (horizontal →)."},{"text":"Busco la **columna** del Mercado B (vertical ↓)."},{"text":"Leo el dato donde se **cruzan**: Q3."}],"answer":"El güisquil cuesta **Q3** la unidad en el Mercado B.","tip":"Fila + columna = dato. Pon un dedo en la fila y otro en la columna, y júntalos."},"id":"s02-l1-3-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:4.2.1"],"ambito":"hacer","prompt":"Con la misma tabla del ejemplo: ¿en qué mercado el **tomate** es más barato?","hint":"Busca la fila del tomate y compara las dos columnas de mercados.","explain":"En la fila del tomate: Mercado A = Q5 y Mercado B = Q4. Es más barato en el B.","type":"choice","props":{"options":[{"id":"a","text":"En el Mercado A","feedback":"En el Mercado A cuesta Q5; en el B, Q4."},{"id":"b","text":"En el Mercado B"},{"id":"c","text":"Cuesta igual en los dos","feedback":"La que cuesta igual en ambos es la cebolla."}],"correct":["b"]},"id":"s02-l1-3-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:4.2.1"],"ambito":"hacer","prompt":"Lee la tabla de mercados. ¿Verdadero o falso?\\n**Mercado · Departamento · Días principales**\\nChichicastenango · El Quiché · jueves y domingo\\nSan Francisco El Alto · Totonicapán · viernes\\nSololá · Sololá · martes y viernes","explain":"Para responder, cruza la fila de cada mercado con la columna \\"Días principales\\".","type":"true-false","props":{"statements":[{"text":"San Francisco El Alto está en Totonicapán.","answer":true},{"text":"Sololá tiene mercado los domingos.","answer":false,"why":"En la tabla, Sololá tiene martes y viernes."},{"text":"Los viernes hay mercado tanto en San Francisco El Alto como en Sololá.","answer":true}]},"id":"s02-l1-3-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:4.2.1"],"ambito":"hacer","prompt":"Piensa en el mercado o la tienda más cercana a tu casa. Haz una **tabla pequeña** con tres productos y su precio aproximado (pregunta en casa o recuerda). Usa columnas: Producto | Precio | Unidad (libra, unidad, manojo…). Después escribe una oración sobre algo que notes en tu tabla.","type":"short-answer","props":{"minWords":15,"placeholder":"Producto | Precio | Unidad\\n… | … | …\\n\\nOración: …","model":"Producto | Precio | Unidad\\nFrijol negro | Q8 | libra\\nAguacate | Q5 | unidad\\nCilantro | Q2 | manojo\\n\\nOración: El frijol es el más caro de mi tabla, pero se compra por libra y rinde para varios días.","rubric":["Mi tabla tiene títulos en las columnas","Cada fila tiene producto, precio y unidad","Escribí una oración que usa los datos de la tabla"]},"id":"s02-l1-3-7"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:4.2.1"],"prompt":"En una tabla, ¿dónde está el dato que buscas?","type":"choice","props":{"options":[{"id":"a","text":"Donde se cruzan la fila y la columna que te interesan"},{"id":"b","text":"Siempre en la primera fila"},{"id":"c","text":"Debajo de la tabla, en letra pequeña"}],"correct":["a"]},"id":"s02-l1-3-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:4.2.1"],"prompt":"Un libro de Ciencias Naturales tiene los subtítulos: \\"Partes de la planta\\", \\"Cómo se alimentan las plantas\\" y \\"Plantas medicinales de Guatemala\\". ¿En cuál buscarías qué es la **fotosíntesis**?","type":"choice","props":{"options":[{"id":"a","text":"\\"Cómo se alimentan las plantas\\""},{"id":"b","text":"\\"Partes de la planta\\""},{"id":"c","text":"\\"Plantas medicinales de Guatemala\\""}],"correct":["a"]},"id":"s02-l1-3-9"}],"kind":"materia","area":"l1","day":3}},{"missionId":"s02","version":"cnb-sexto-4521d865fee05326","lesson":{"id":"s02-ef-2","title":"Combinar habilidades: correr, saltar y girar","icon":"Footprints","minutes":15,"gancho":"Un portero de fútbol corre, salta y atrapa en un solo movimiento. ¿Cómo aprende el cuerpo a unir varias acciones sin trabarse?","objetivos":["Reconocer las habilidades motrices simples: desplazarse, saltar, girar, lanzar y atrapar","Combinar dos o más habilidades simples en una habilidad genérica","Coordinar flexión, extensión y rotación al saltar, caer y girar"],"resumen":["Las habilidades simples (básicas) son: desplazarse (caminar, correr), saltar, girar, lanzar y recibir (atrapar).","Una habilidad genérica combina dos o más habilidades simples de forma fluida: correr y saltar, botar mientras corres, girar y lanzar. Son la base de todos los deportes.","En el salto: flexión de rodillas para prepararse, extensión fuerte para impulsarse y flexión otra vez para caer suave, sobre la punta de los pies y luego todo el pie.","Para combinar habilidades: practica cada una por separado, luego únelas despacio y aumenta la velocidad poco a poco."],"media":{"id":"s02-ef-2-circuito","kind":"video","title":"Circuito de habilidades","aspect":"9:16","duration":50,"alt":"Un niño corre, salta una línea, cae con rodillas dobladas, gira media vuelta y lanza una pelota a un aro; primero despacio y luego fluido.","brief":"Video vertical de 50 s en patio escolar. Un niño y una niña (ropa deportiva sencilla, rostros no protagonistas) demuestran un circuito: (1) cada habilidad por separado con rótulo (\\"correr\\", \\"saltar\\", \\"girar\\", \\"lanzar\\"); (2) la combinación despacio; (3) la combinación fluida. Cámara lenta en el salto con rótulos \\"flexión → extensión → flexión (caída suave)\\". Materiales caseros: línea de yeso, llanta vieja como aro, pelota de trapo. Aviso \\"Practica en suelo seco y despejado\\". Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:1.3.5"],"ambito":"conocer","title":"De simples a genéricas","prompt":"Así como las letras forman palabras, las **habilidades simples** se unen para formar **habilidades genéricas**. Toca cada tarjeta.","type":"explain","props":{"icon":"Blocks","body":"Primero dominamos las simples; luego las combinamos; después las usamos en deportes (habilidades específicas).","reveal":[{"icon":"Footprints","front":"Desplazarse","back":"Caminar, correr, reptar, cuadrupedia. Mover todo el cuerpo de un lugar a otro."},{"icon":"ArrowUp","front":"Saltar","back":"Despegar del suelo con una o dos piernas y caer con control."},{"icon":"RotateCw","front":"Girar","back":"Rotar el cuerpo: media vuelta, vuelta completa, rodar."},{"icon":"Target","front":"Lanzar y recibir","back":"Enviar un objeto con las manos o los pies, y atraparlo o detenerlo."},{"icon":"Layers","front":"Genéricas","back":"Combinaciones fluidas: **correr + saltar** un charco, **correr + botar**, **girar + lanzar**, **saltar + atrapar**."}]},"id":"s02-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.3.5"],"ambito":"conocer","prompt":"En el **basquetbol**, una jugadora **corre botando la pelota** hacia la canasta. ¿Cuántas habilidades está haciendo a la vez?","explain":"Dos: **correr** (desplazarse) y **botar** la pelota. Cuando unimos habilidades simples en una sola acción fluida, formamos una **habilidad genérica**.","type":"choice","props":{"options":[{"id":"a","text":"Una sola","icon":"Circle","feedback":"Fíjate en sus pies y en sus manos: hacen cosas distintas al mismo tiempo."},{"id":"b","text":"Dos: correr y botar","icon":"Layers"}],"correct":["b"]},"id":"s02-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.3.6"],"ambito":"hacer","title":"El salto: flexión, extensión, flexión","prompt":"El salto es una habilidad que usa los tres movimientos que aprendiste la semana pasada. Toca cada fase.","media":{"id":"s02-ef-2-salto","kind":"animation","title":"Las fases del salto","aspect":"16:9","duration":30,"alt":"Una figura de niña salta: primero dobla rodillas y brazos atrás, luego se estira hacia arriba con brazos al cielo, y cae doblando las rodillas.","brief":"Animación 2D de 30 s, figura de niña en silueta con articulaciones marcadas (cadera, rodilla, tobillo). Fase 1 \\"Preparación\\": flexión de rodillas y cadera, brazos atrás (arcos de ángulo en rojo que se cierran). Fase 2 \\"Impulso\\": extensión explosiva de piernas y brazos arriba (arcos que se abren en verde). Fase 3 \\"Vuelo\\". Fase 4 \\"Caída\\": contacto con punta de pie → todo el pie, flexión de rodillas para amortiguar (resorte dibujado). Se repite en cámara lenta. Rótulos grandes."},"type":"explain","props":{"icon":"ArrowUp","body":"Las piernas funcionan como un **resorte**: se doblan para cargar energía y se estiran para liberarla.","reveal":[{"icon":"ArrowDown","front":"1. Preparación","back":"**Flexión** de rodillas y cadera, brazos hacia atrás. Cargas energía como un resorte."},{"icon":"ArrowUp","front":"2. Impulso","back":"**Extensión** fuerte de piernas y brazos hacia arriba y adelante."},{"icon":"Feather","front":"3. Caída suave","back":"Caes en la **punta de los pies** y luego todo el pie, con **flexión** de rodillas para amortiguar. Nunca caigas con las piernas rectas."},{"icon":"RotateCw","front":"+ Rotación","back":"Si quieres girar en el aire, **rota** hombros y cadera hacia donde quieres ir al despegar."}]},"id":"s02-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.3.5","ef:1.3.6"],"ambito":"hacer","title":"Ejemplo resuelto: aprender a correr y saltar un charco","prompt":"Mira cómo Fernanda aprende a combinar **correr + saltar** sin detenerse.","type":"worked-example","props":{"icon":"Droplets","problem":"Después de la lluvia hay un charco en el camino a la escuela (imaginario: una línea doble de yeso en el patio). Fernanda quiere pasarlo corriendo, sin frenar ni mojarse.","steps":[{"text":"**Practica cada habilidad sola:** corre 10 pasos; luego salta la línea desde parada, con la técnica de flexión-extensión-flexión."},{"text":"**Une despacio:** trota, y a 3 pasos de la línea mira dónde va a despegar.","why":"Calcular el lugar de despegue evita frenarse o pisar el charco."},{"text":"**Despega con un pie** y lleva la otra pierna adelante (como un paso largo en el aire)."},{"text":"**Cae con la pierna adelantada**, rodilla doblada, y **sigue corriendo**.","why":"Si la caída es suave y sigue el movimiento, la combinación queda fluida."},{"text":"**Aumenta la velocidad** poco a poco en los siguientes intentos."}],"answer":"Fernanda formó la habilidad genérica **correr + saltar**: primero practicó por separado, luego unió despacio y al final aceleró.","tip":"Si te trabas, vuelve a la velocidad lenta: la coordinación se construye con repeticiones."},"id":"s02-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.3.5"],"ambito":"conocer","prompt":"Clasifica cada acción: ¿habilidad **simple** o **genérica** (combinación)?","hint":"Cuenta cuántas acciones distintas hay: si hay dos o más unidas, es genérica.","explain":"Una sola acción = simple. Dos o más acciones unidas de forma fluida = genérica.","type":"sort","props":{"buckets":[{"id":"s","label":"Simple","icon":"Circle","color":"var(--area-ef)"},{"id":"g","label":"Genérica","icon":"Layers","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"Saltar con los pies juntos en el lugar","bucket":"s"},{"id":"x2","text":"Correr y saltar una cuerda que gira","bucket":"g"},{"id":"x3","text":"Caminar","bucket":"s"},{"id":"x4","text":"Girar media vuelta y lanzar una pelota","bucket":"g"},{"id":"x5","text":"Atrapar una pelota estando quieto","bucket":"s"},{"id":"x6","text":"Correr botando una pelota","bucket":"g"}]},"id":"s02-ef-2-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.3.5","ef:1.3.6"],"ambito":"hacer","prompt":"¡Circuito del mandadero! **Calentamiento (1 min):** trote suave, rotación de tobillos, rodillas y cadera. **Circuito (repite 3 veces):** corre 5 pasos → **salta** una línea (flexión-extensión-flexión) → **gira** media vuelta → **lanza** una pelota de trapo o un calcetín enrollado a una caja o llanta → corre de regreso. Primero despacio, luego fluido. **Poco espacio:** paso largo en lugar de correr, salto en el lugar, giro y lanzamiento a una caja cercana. **Adaptación:** en silla de ruedas: avanza, gira la silla y lanza. **Estira** piernas al final y toma agua.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después del calentamiento","exercise":{"name":"Trote suave y rotaciones","icon":"RotateCw","seconds":60}},{"label":"Después del circuito","exercise":{"name":"Correr, saltar, girar y lanzar","icon":"Footprints","seconds":90}}]},"id":"s02-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.3.6"],"ambito":"hacer","prompt":"Al saltar la línea, Pablo siente un golpe fuerte en las rodillas cada vez que cae. ¿Qué está haciendo mal?","explain":"Al caer hay que **flexionar** las rodillas y apoyar primero la punta del pie: así los músculos amortiguan el impacto como un resorte.","type":"choice","props":{"options":[{"id":"a","text":"Cae con las piernas rectas, sin doblar las rodillas"},{"id":"b","text":"Dobla las rodillas antes de saltar","feedback":"Eso es correcto: es la fase de preparación."},{"id":"c","text":"Mueve los brazos hacia arriba al impulsarse","feedback":"Eso es correcto: los brazos ayudan al impulso."}],"correct":["a"]},"id":"s02-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.3.5"],"ambito":"hacer","prompt":"Ordena los pasos para **aprender** una habilidad genérica nueva.","explain":"Separado → unido despacio → unido con más velocidad → usado en un juego.","type":"order","props":{"items":[{"id":"a","text":"Practicar cada habilidad simple por separado"},{"id":"b","text":"Unirlas despacio"},{"id":"c","text":"Aumentar la velocidad poco a poco"},{"id":"d","text":"Usar la combinación en un juego"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s02-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.3.5"],"prompt":"¿Qué ejemplo combina dos habilidades simples en una **habilidad genérica**?","type":"choice","props":{"options":[{"id":"a","text":"Correr y saltar un obstáculo"},{"id":"b","text":"Caminar"},{"id":"c","text":"Estar sentado"}],"correct":["a"]},"id":"s02-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.3.6"],"prompt":"Une cada fase del salto con el movimiento de las rodillas.","type":"match","props":{"pairs":[{"id":"p","left":"Preparación","right":"Flexión para cargar energía"},{"id":"i","left":"Impulso","right":"Extensión fuerte"},{"id":"c","left":"Caída","right":"Flexión para amortiguar"}]},"id":"s02-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["ef"],"cnb":["ef:1.3.5"],"type":"reflection","props":{"statements":["Acelero y freno con control y seguridad","Reconozco habilidades simples y genéricas","Salto y caigo suave con flexión y extensión"],"commitments":["Jugaré al semáforo con mi familia","Practicaré correr y saltar una línea","Siempre caeré con las rodillas dobladas"]},"id":"s02-ef-2-11"}],"kind":"materia","area":"ef","day":5}}]`),o={mission:a,lessons:e};export{o as default,e as lessons,a as mission};
